1	// Cyrus studios (R1b): who sees the studios and what each plan may do in them. Pure + client-safe; the API runs
2	// the same functions again on every request (the UI only shows the result as a hint).
3	//
4	// TWO gates, both server side:
5	//  1. Visibility (`studiosOpen`): the Cyrus studio access rule (lib/modbuilder/access.ts modBuilderUser: private
6	//     preview, or the public once Cyrus launches) AND the NEW setting `cyrus_studios_enabled` (default OFF).
7	//     While the setting is off ONLY preview accounts see the studios (same rule as the rest of Cyrus), so nothing
8	//     visible changes for customers until the owner flips it.
9	//  2. Plan (`studioPlanView`): lib/cyrus/engine-core/asset-gate.ts canAsset. Texture Studio + Texture Library = the
10	//     top plan (`all`, shown as "All models"); Sound Studio + Sound Library = Saka and up; Free / Katara none. Only
11	//     create/edit is gated: assets already in a project are always viewable, installable and exportable. An unknown
12	//     plan fails CLOSED for editing and never for viewing or keeping.
13	import { canAsset, downgradeSpecAssets, normalizePlan, PLAN_LABEL, type AssetDecision, type AssetPlan } from "../engine-core/asset-gate";
14	
15	export const STUDIO_KINDS = ["texture", "sound"] as const;
16	export type StudioKind = (typeof STUDIO_KINDS)[number];
17	export const STUDIO_NAME: Record<StudioKind, string> = { texture: "Texture Studio", sound: "Sound Studio" };
18	
19	/**
20	 * Owner defaults for the open design questions (2026-10-10). Change them here; DOCUMENTATION.md "Cyrus studios UI
21	 * (R1b)" lists them.
22	 */
23	export const STUDIO_DEFAULTS = {
24	  /** the prompt dock shows an estimated token cost for an asset edit (a change build) */
25	  showEditEstimate: true,
26	  /** packs are optional on join; a per-mod "required" option exists (lib/cyrus/packhost applyPackChange `required`) */
27	  packRequiredByDefault: false,
28	  /** the mob-skin row is shown as "coming soon", not hidden */
29	  mobSkin: "coming_soon" as "coming_soon" | "hidden",
30	  /** phones get a read-only preview + approve / reject (approving saves a revision) */
31	  mobile: "review_and_approve" as "review_and_approve" | "view_only",
32	  /** editors open full page; the inspector has a quick-entry Assets tab */
33	  editorsOpen: "full_page" as const,
34	} as const;
35	
36	/** Visibility gate (both inputs come from the server). */
37	export const studiosOpen = (o: { cyrusUser: boolean; previewUser: boolean; flagOn: boolean }) => o.cyrusUser && (o.previewUser || o.flagOn);
38	
39	export type StudioPlanView = {
40	  plan: AssetPlan | null;
41	  planLabel: string;
42	  /** may create/edit (studio, library pick, upload, AI edit) per kind */
43	  edit: Record<StudioKind, AssetDecision>;
44	};
45	
46	export function studioPlanView(rawPlan: unknown): StudioPlanView {
47	  const plan = normalizePlan(rawPlan);
48	  return {
49	    plan, planLabel: plan ? PLAN_LABEL[plan] : "Unknown",
50	    edit: { texture: canAsset(plan, "texture", "edit"), sound: canAsset(plan, "sound", "edit") },
51	  };
52	}
53	
54	/** The plan matrix of the locked-states page (rows straight from the gate). */
55	export type MatrixRow = { group: string } | { label: string; allowed: (p: AssetPlan) => boolean };
56	export const PLAN_ORDER: readonly AssetPlan[] = ["free", "katara", "saka", "all"];
57	export const PLAN_MATRIX: readonly MatrixRow[] = [
58	  { group: "Studios" },
59	  { label: "Sound Studio", allowed: (p) => canAsset(p, "sound", "edit").ok },
60	  { label: "Sound Library", allowed: (p) => canAsset(p, "sound", "create").ok },
61	  { label: "Texture Studio", allowed: (p) => canAsset(p, "texture", "edit").ok },
62	  { label: "Texture Library", allowed: (p) => canAsset(p, "texture", "create").ok },
63	  { group: "Inside builds" },
64	  { label: "Cyrus makes custom sounds", allowed: (p) => canAsset(p, "sound", "create").ok },
65	  { label: "Cyrus makes custom textures", allowed: (p) => canAsset(p, "texture", "create").ok },
66	  { group: "Every plan" },
67	  { label: "Keep, install, export assets", allowed: (p) => canAsset(p, "texture", "keep").ok && canAsset(p, "sound", "export").ok },
68	  { label: "Rebuild unchanged", allowed: (p) => canAsset(p, "texture", "rebuild").ok },
69	  { label: "Mod Packs", allowed: (p) => canAsset(p, "texture", "compose").ok },
70	  { label: "Import your own mod", allowed: (p) => canAsset(p, "texture", "import").ok },
71	];
72	
73	/** What a build says under "Good to know" on this plan: the router downgrade's own notices (sound first). */
74	export function buildNotices(rawPlan: unknown, ids: { sound?: string | null; texture?: string | null }): string[] {
75	  const assets = [
76	    ...(ids.sound ? [{ id: ids.sound, kind: "sound" as const, purpose: "custom sound", source: "generate" as const, requirementIds: [] }] : []),
77	    ...(ids.texture ? [{ id: ids.texture, kind: "texture" as const, purpose: "custom texture", source: "generate" as const, requirementIds: [] }] : []),
78	  ];
79	  return downgradeSpecAssets({ assets }, normalizePlan(rawPlan)).notices;
80	}
81	// Cyrus studios (R1b): the REAL dependencies of the studio API. SERVER ONLY. This is the one file that reaches Nxeon:
82	// through the existing small seams only (the Cyrus access rule modBuilderUser + the preview list, the settings
83	// table for the flag, tokens tierOf for the plan, the ModBuild chain the studio already lives on, the rate limiter).
84	// Everything it writes goes to Cyrus tables through lib/cyrus/engine-core/store.ts.
85	import type { User } from "@prisma/client";
86	import { modBuilderUser } from "../../modbuilder/access";
87	import { isPreviewUser } from "../../preview-access";
88	import { getSettingBool } from "../../settings";
89	import { checkRateLimit } from "../../rate-limit";
90	import { MANAGED_REAL_FLAG } from "../managed/installer";
91	import { selectPackStore } from "../packhost/config";
92	import { publishPack } from "../packhost/publish";
93	import { SoundLibraryProvider, TextureLibraryProvider } from "../library/providers";
94	import { userAssetProviders } from "../library/user-assets";
95	import { prismaUserAssetStore } from "../library/user-store";
96	import { tierOf } from "../tokens/access";
97	import { studiosOpen } from "./access";
98	import { changeBuildCandidates } from "./candidates";
99	import { chainOf, prismaStudioStore } from "./store-prisma";
100	export { chainOf, prismaStudioStore };
101	import { fakeCandidates, type CandidateBackend, type StudioServiceDeps } from "./service";
102	import type { StudioApiDeps, StudioViewer, UploadStore } from "./http";
103	import { localUploadStore } from "./uploads";
104	
105	export const CYRUS_STUDIOS_FLAG = "cyrus_studios_enabled";
106	
107	/** The studios setting. Fails CLOSED: a settings/DB error never opens them. */
108	export async function studiosFlagOn(): Promise<boolean> {
109	  try { return await getSettingBool(CYRUS_STUDIOS_FLAG, false); } catch { return false; }
110	}
111	
112	/** Who may see the studios now: a Cyrus user (preview or public launch) AND (preview OR the setting is on). */
113	export async function studioViewer(): Promise<(StudioViewer & { user: User }) | null> {
114	  const user = await modBuilderUser().catch(() => null);
115	  if (!user) return null;
116	  const [previewUser, flagOn] = await Promise.all([isPreviewUser(user, "modbuilder").catch(() => false), studiosFlagOn()]);
117	  return studiosOpen({ cyrusUser: true, previewUser, flagOn }) ? { userId: user.id, user, preview: previewUser } : null;
118	}
119	
120	/**
121	 * The plan lookup (host seam: tokens tierOf). Non-production only: CYRUS_STUDIO_TEST_PLAN_UNKNOWN=<userId,...> makes
122	 * the lookup fail for those accounts, so the fail-closed "plan unknown" state can be exercised on devhost.
123	 */
124	export function studioPlanOf(env: Record<string, string | undefined> = process.env) {
125	  const faulty = env.NODE_ENV !== "production" ? new Set((env.CYRUS_STUDIO_TEST_PLAN_UNKNOWN ?? "").split(",").filter(Boolean)) : new Set<string>();
126	  return async (userId: string): Promise<unknown> => { if (faulty.has(userId)) throw new Error("plan lookup failed (test fault)"); return tierOf(userId); };
127	}
128	
129	export function serviceDeps(env: Record<string, string | undefined> = process.env): StudioServiceDeps {
130	  return {
131	    store: prismaStudioStore,
132	    planOf: studioPlanOf(env),
133	    chain: chainOf,
134	    deliveryOn: () => env[MANAGED_REAL_FLAG] === "1",
135	    publish: async (zip) => {
136	      const sel = selectPackStore(env);
137	      if (!sel.ok) return { ok: false, reason: sel.reason };
138	      const r = await publishPack(sel.store, zip, { maxBytes: sel.maxBytes });
139	      return r.ok ? { ok: true, url: r.url, sha1: r.sha1 } : { ok: false, reason: r.error };
140	    },
141	  };
142	}
143	
144	/** CYRUS_STUDIO_CANDIDATES=fake (devhost / tests only) swaps the change-build backend for the deterministic fake. */
145	// one fake per process (globalThis: each Next route bundle has its own module instance)
146	const G = globalThis as { __cyrusFakeCandidates?: CandidateBackend };
147	export function candidateBackend(env: Record<string, string | undefined> = process.env): CandidateBackend {
148	  if (env.CYRUS_STUDIO_CANDIDATES === "fake" && env.NODE_ENV !== "production") return (G.__cyrusFakeCandidates ??= fakeCandidates({ readyAfter: 1 }));
149	  return changeBuildCandidates(prismaStudioStore);
150	}
151	
152	export function apiDeps(env: Record<string, string | undefined> = process.env): StudioApiDeps {
153	  const uploads: UploadStore | null = env.CYRUS_UPLOAD_STORE === "local" && env.NODE_ENV !== "production" ? localUploadStore(env.CYRUS_UPLOAD_DIR || ".data/cyrus-uploads") : null;
154	  return {
155	    viewer: studioViewer,
156	    service: serviceDeps(env),
157	    candidates: candidateBackend(env),
158	    catalog: { providers: [SoundLibraryProvider, TextureLibraryProvider, ...userAssetProviders(prismaUserAssetStore)], planOf: studioPlanOf(env) },
159	    rateLimit: (key, max, windowMs) => checkRateLimit(`cyrus:studio:${key}`, { max, windowMs }),
160	    uploads,
161	  };
162	}
163	// Cyrus studios (R1b): the server-side service behind /api/cyrus/assets/v1. Every dependency is injected (host seam):
164	// the Cyrus tables through `StudioStore`, the build chain through `chain`, the plan through `planOf`, pack hosting
165	// through `publish`. lib/cyrus/studios/deps.ts wires the real ones; tests use in-memory fakes. No Nxeon internals here.
166	//
167	// Model: a project's texture = the newest CyrusProjectAsset row for its key (kind texture) that is not an undecided
168	// Cyrus candidate. Rows are append-only and content-addressed; the studio never edits a row or a revision: a save is
169	// a NEW revision (kind "asset") plus a new asset row holding the TextureDoc (spec + sparse paint layer, ./paint.ts).
170	import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
171	import type { AddRevisionInput, RecordAssetInput } from "../engine-core/store";
172	import type { ManifestEntry } from "../engine-core/revisions";
173	import type { IdentifierKind } from "../engine-core/identifiers";
174	import type { MbAssets } from "../../modbuilder/types";
175	import { checkSpec, type TextureSpec } from "../textures/dsl";
176	import { encodePng } from "../textures/png";
177	import { QUALITY_VERSION, type QualityReport } from "../textures/quality";
178	import { buildPack } from "../textures/pack";
179	import { canonicalJson, sha256Hex } from "../assets/textures";
180	import { checkDoc, docFromSpec, docQuality, renderDoc, TEXTURE_DOC_MIME, type DocDecision, type TextureDoc } from "./paint";
181	import { studioPlanView, type StudioPlanView } from "./access";
182	
183	export type ProjectRow = { id: string; userId: string; namespace: string; rootBuildId: string | null; headRevisionId: string | null; title: string | null };
184	export type AssetRow = { id: string; projectId: string; revisionId: string; assetKey: string; kind: string; sha256: string; size: number; origin: string; mime: string | null; path: string | null; provenance: unknown; createdAt: Date | string };
185	export type RevRow = { id: string; seq: number; kind: string; status: string; message: string | null; createdAt: Date | string; manifest: ManifestEntry[]; modBuildId: string | null };
186	
187	export interface StudioStore {
188	  projectForRoot(rootBuildId: string): Promise<ProjectRow | null>;
189	  project(id: string): Promise<ProjectRow | null>;
190	  assets(projectId: string): Promise<AssetRow[]>;
191	  assetById(id: string): Promise<AssetRow | null>;
192	  revisions(projectId: string): Promise<RevRow[]>;
193	  addRevision(projectId: string, input: AddRevisionInput): Promise<{ id: string; seq: number }>;
194	  recordAsset(projectId: string, a: RecordAssetInput): Promise<{ id: string }>;
195	  reserve(projectId: string, kind: IdentifierKind, key: string): Promise<{ fullId: string }>;
196	}
197	
198	/** The mod's build chain as far as the studio needs it (read through the existing ModBuild seam). */
199	export type ChainInfo = {
200	  rootBuildId: string;
201	  latestBuildId: string | null;
202	  mcVersion: string;
203	  pluginName: string | null;
204	  /** ModBuild.result.assets of the newest build that has one */
205	  assets: MbAssets | null;
206	  /** builds the Texture Studio started as AI candidates (change builds with the studio marker) */
207	  candidateBuilds: { id: string; key: string; status: string; error: string | null; createdAt: string; summary?: string }[];
208	};
209	
210	export type PublishResult = { ok: true; url: string; sha1: string } | { ok: false; reason: string };
211	export type StudioServiceDeps = {
212	  store: StudioStore;
213	  planOf: (userId: string) => Promise<unknown>;
214	  chain: (userId: string, rootBuildId: string) => Promise<ChainInfo | null>;
215	  /** publish a rebuilt pack; absent / not configured = the pack is built and recorded but not hosted */
216	  publish?: (zip: Buffer) => Promise<PublishResult>;
217	  /** CYRUS_MANAGED_PLUGINS_REAL: packs are delivered to servers */
218	  deliveryOn: () => boolean;
219	};
220	
221	export class StudioError extends Error {
222	  constructor(public status: number, public code: string, message: string, public extra: Record<string, unknown> = {}) { super(message); }
223	}
224	
225	export const docSha = (doc: TextureDoc) => { const canonical = canonicalJson(doc); return { canonical, sha256: sha256Hex(canonical) }; };
226	const ts = (d: Date | string) => new Date(d).getTime();
227	const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});
228	
229	/** The TextureDoc an asset row holds (generated rows hold a bare spec; uploads hold no pixels here: library only). */
230	export function docOfRow(row: AssetRow): TextureDoc | null {
231	  if (row.kind !== "texture") return null;
232	  const p = obj(row.provenance);
233	  if (row.mime === TEXTURE_DOC_MIME) { const d = checkDoc(p.doc); return d.ok ? d.doc : null; }
234	  if (p.spec) {
235	    const c = checkSpec(p.spec);
236	    if (!c.ok) return null;
237	    // a generated spec supersedes itself: a later build that returns it unchanged keeps any studio edit on top
238	    return { ...docFromSpec(c.spec), supersedes: [row.sha256] };
239	  }
240	  return null;
241	}
242	
243	export type TextureEntry = {
244	  key: string; assetId: string; origin: string; revisionId: string; createdAt: string;
245	  doc: TextureDoc; quality: QualityReport; specSha256: string | null;
246	  history: { assetId: string; origin: string; revisionId: string; createdAt: string; doc: TextureDoc; label: string; decision: DocDecision | null }[];
247	  candidates: { buildId: string; assetId: string; createdAt: string; doc: TextureDoc; specSha256: string }[];
248	};
249	
250	const ORIGIN_LABEL: Record<string, string> = { generated: "Generated by Cyrus", edited: "Edited in Texture Studio", library: "From the Texture Library", imported: "Imported", upload: "Uploaded" };
251	function labelOf(row: AssetRow, doc: TextureDoc): string {
252	  const p = obj(row.provenance);
253	  if (doc.decision && !doc.decision.accepted) return "Kept current (Cyrus candidate rejected)";
254	  if (doc.decision?.accepted) return "Accepted Cyrus candidate";
255	  if (p.keptStudioEdit) return "Studio edits kept by a build";
256	  if (row.origin === "generated" && p.kept) return "Kept unchanged by a build";
257	  return ORIGIN_LABEL[row.origin] ?? row.origin;
258	}
259	
260	/** Pure: resolve each texture key's current doc, its history and its open candidates. */
261	export function resolveTextures(rows: readonly AssetRow[], candidateBuildIds: ReadonlySet<string>): TextureEntry[] {
262	  const byKey = new Map<string, AssetRow[]>();
263	  for (const r of rows) if (r.kind === "texture" && r.mime !== "image/png") byKey.set(r.assetKey, [...(byKey.get(r.assetKey) ?? []), r]);
264	  const out: TextureEntry[] = [];
265	  for (const [key, list] of byKey) {
266	    list.sort((a, b) => ts(a.createdAt) - ts(b.createdAt) || (a.id < b.id ? -1 : 1));
267	    const docs = list.map((r) => ({ r, doc: docOfRow(r) })).filter((x): x is { r: AssetRow; doc: TextureDoc } => !!x.doc);
268	    const isCand = (r: AssetRow) => r.origin === "generated" && candidateBuildIds.has(String(obj(r.provenance).modBuildId ?? ""));
269	    const decided = new Set(docs.flatMap((x) => (x.doc.decision ? [x.doc.decision.candidate] : [])));
270	    const cur = [...docs].reverse().find((x) => !isCand(x.r));
271	    if (!cur) continue;
272	    out.push({
273	      key, assetId: cur.r.id, origin: cur.r.origin, revisionId: cur.r.revisionId, createdAt: new Date(cur.r.createdAt).toISOString(),
274	      doc: cur.doc, quality: docQuality(cur.doc), specSha256: cur.doc.spec ? sha256Hex(canonicalJson(cur.doc.spec)) : null,
275	      history: docs.filter((x) => !isCand(x.r)).reverse().slice(0, 20).map((x) => ({ assetId: x.r.id, origin: x.r.origin, revisionId: x.r.revisionId, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, label: labelOf(x.r, x.doc), decision: x.doc.decision ?? null })),
276	      candidates: docs.filter((x) => isCand(x.r) && !decided.has(String(obj(x.r.provenance).modBuildId))).map((x) => ({ buildId: String(obj(x.r.provenance).modBuildId), assetId: x.r.id, createdAt: new Date(x.r.createdAt).toISOString(), doc: x.doc, specSha256: x.r.sha256 })),
277	    });
278	  }
279	  // the mod's order: the oldest texture first (what the build made, then studio additions)
280	  const first = (t: TextureEntry) => ts(t.history[t.history.length - 1]?.createdAt ?? t.createdAt);
281	  return out.sort((a, b) => first(a) - first(b) || (a.key < b.key ? -1 : 1));
282	}
283	
284	/** The current studio doc of one key, for lib/cyrus/assets/sync.ts (a build keeps studio edits it did not replace). */
285	export async function currentStudioDoc(store: Pick<StudioStore, "assets">, projectId: string, key: string, candidateBuildIds: ReadonlySet<string> = new Set()) {
286	  const t = resolveTextures(await store.assets(projectId), candidateBuildIds).find((x) => x.key === key);
287	  if (!t || (t.origin !== "edited" && t.origin !== "library")) return null; // nothing the studio made
288	  const { canonical, sha256 } = docSha(t.doc);
289	  return { doc: t.doc, sha256, canonical };
290	}
291	
292	// ---------------------------------------------------------------------------- reads
293	
294	export type PackStatus = {
295	  state: "hosted" | "delivery_off" | "unhosted" | "failed" | "none";
296	  sha1: string | null; bytes: number | null; format: number | null; mcVersion: string; required: boolean;
297	  textures: number; sounds: number; editedSinceBuild: boolean; notices: string[];
298	};
299	
300	export function packStatusOf(chain: ChainInfo, deliveryOn: boolean, editedSinceBuild: boolean): PackStatus {
301	  const a = chain.assets;
302	  const state: PackStatus["state"] = !a || !a.pack ? (a?.status === "failed" ? "failed" : "none") : !deliveryOn ? "delivery_off" : a.status === "ready" && a.pack.url ? "hosted" : "unhosted";
303	  return {
304	    state, sha1: a?.pack?.sha1 ?? null, bytes: a?.pack?.bytes ?? null, format: a?.pack?.format ?? null, mcVersion: chain.mcVersion,
305	    required: a?.loader?.required ?? false, textures: a?.textures.length ?? 0, sounds: a?.sounds?.length ?? 0, editedSinceBuild, notices: (a?.notices ?? []).slice(0, 6),
306	  };
307	}
308	
309	export type ProjectAssetsView = {
310	  project: { id: string; namespace: string; title: string | null; rootBuildId: string | null } | null;
311	  access: StudioPlanView;
312	  headRevisionId: string | null;
313	  textures: TextureEntry[];
314	  sounds: NonNullable<MbAssets["sounds"]>;
315	  soundRender: MbAssets["soundRender"] | null;
316	  pack: PackStatus | null;
317	  /** candidate build id -> what the customer asked for (the change request without the studio marker) */
318	  candidateSummaries: Record<string, string>;
319	  /** revision id -> seq (History shows "Revision N") */
320	  revisionSeq: Record<string, number>;
321	  mcVersion: string | null;
322	};
323	
324	async function ownedProject(deps: StudioServiceDeps, userId: string, projectId: string): Promise<ProjectRow> {
325	  const p = await deps.store.project(projectId);
326	  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
327	  return p;
328	}
329	const planView = async (deps: StudioServiceDeps, userId: string) => studioPlanView(await deps.planOf(userId).catch(() => null));
330	
331	export async function projectAssets(deps: StudioServiceDeps, userId: string, rootBuildId: string): Promise<ProjectAssetsView> {
332	  const chain = await deps.chain(userId, rootBuildId);
333	  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
334	  const access = await planView(deps, userId);
335	  const p = await deps.store.projectForRoot(chain.rootBuildId);
336	  if (!p || p.userId !== userId) return { project: null, access, headRevisionId: null, textures: [], sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: chain.assets ? packStatusOf(chain, deps.deliveryOn(), false) : null, revisionSeq: {}, mcVersion: chain.mcVersion, candidateSummaries: {} };
337	  const revs = await deps.store.revisions(p.id);
338	  const textures = resolveTextures(await deps.store.assets(p.id), new Set(chain.candidateBuilds.map((b) => b.id)));
339	  const lastBuildRev = chain.assets?.revisionId ?? null;
340	  const edited = textures.some((t) => (t.origin === "edited" || t.origin === "library") && t.revisionId !== lastBuildRev);
341	  return {
342	    project: { id: p.id, namespace: p.namespace, title: p.title, rootBuildId: p.rootBuildId }, access, headRevisionId: p.headRevisionId,
343	    textures, sounds: chain.assets?.sounds ?? [], soundRender: chain.assets?.soundRender ?? null, pack: packStatusOf(chain, deps.deliveryOn(), edited),
344	    revisionSeq: Object.fromEntries(revs.map((r) => [r.id, r.seq])), mcVersion: chain.mcVersion,
345	    candidateSummaries: Object.fromEntries(chain.candidateBuilds.filter((b) => b.summary).map((b) => [b.id, b.summary!])),
346	  };
347	}
348	
349	// ---------------------------------------------------------------------------- writes
350	
351	const gateOrThrow = (d: AssetDecision) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };
352	
353	export type SaveInput = {
354	  userId: string; projectId: string; key: string; doc: unknown;
355	  /** the asset row the edit started from (null = a new texture) */
356	  baseAssetId: string | null;
357	  /** the project head the client saw; a newer head = 409 stale_head */
358	  expectedHeadId: string | null;
359	  origin?: "edited" | "library";
360	  decision?: DocDecision | null;
361	  /** spec sha256 values this doc also supersedes (server-computed: a rejected / accepted candidate) */
362	  alsoSupersedes?: string[];
363	  message?: string | null;
364	  provenance?: Record<string, unknown>;
365	};
366	export type SaveResult = { revisionId: string; seq: number; assetId: string; quality: QualityReport; pack: { sha1: string; hosted: boolean } | { skipped: string } };
367	
368	export async function saveTexture(deps: StudioServiceDeps, input: SaveInput): Promise<SaveResult> {
369	  const origin = input.origin ?? "edited";
370	  gateOrThrow(canAsset(await deps.planOf(input.userId).catch(() => null), "texture", origin === "library" ? "create" : "edit"));
371	  const project = await ownedProject(deps, input.userId, input.projectId);
372	  const d = checkDoc(input.doc);
373	  if (!d.ok) throw new StudioError(400, "bad_doc", d.error);
374	  if (d.doc.name !== input.key) throw new StudioError(400, "bad_doc", "the texture name must match its key");
375	  const rows = await deps.store.assets(project.id);
376	  const base = input.baseAssetId ? rows.find((r) => r.id === input.baseAssetId && r.kind === "texture") : null;
377	  if (input.baseAssetId && !base) throw new StudioError(404, "not_found", "The texture this edit started from is not in this project.");
378	  if (!input.baseAssetId && rows.some((r) => r.kind === "texture" && r.assetKey === input.key && r.mime !== "image/png")) throw new StudioError(409, "exists", `This mod already has a texture called ${input.key}.`);
379	  const baseDoc = base ? docOfRow(base) : null;
380	  // supersedes is computed here, never taken from the client
381	  const sup = new Set<string>([...(baseDoc?.supersedes ?? []), ...(input.alsoSupersedes ?? [])]);
382	  const doc: TextureDoc = { ...d.doc, ...(sup.size ? { supersedes: [...sup].sort() } : {}), ...(input.decision ? { decision: input.decision } : {}) };
383	  if (!sup.size) delete doc.supersedes;
384	  if (!input.decision) delete doc.decision;
385	  const quality = docQuality(doc);
386	  if (quality.verdict === "fail") throw new StudioError(422, "quality", "This texture fails the quality checks, so it can't be saved. Fix the failing checks first.", { quality });
387	  const { canonical, sha256 } = docSha(doc);
388	  const png = encodePng(renderDoc(doc));
389	
390	  // the pack, rebuilt from every current texture of the mod (sound packs are re-rendered by the next build instead)
391	  const revs = await deps.store.revisions(project.id);
392	  const head = revs.length ? revs[revs.length - 1] : null;
393	  if (input.expectedHeadId !== undefined && (head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
394	  const chain = project.rootBuildId ? await deps.chain(input.userId, project.rootBuildId) : null;
395	  const current = resolveTextures(rows, new Set(chain?.candidateBuilds.map((b) => b.id) ?? [])).filter((t) => t.key !== input.key).map((t) => t.doc);
396	  let pack: SaveResult["pack"] = { skipped: "no build to rebuild the pack for yet" };
397	  let packEntry: ManifestEntry | null = null;
398	  if (chain && chain.assets?.sounds?.length) pack = { skipped: "this pack also carries sounds; the next build rebuilds it with your texture" };
399	  else if (chain) {
400	    const built = buildPack({ namespace: project.namespace, description: `${chain.pluginName || "This mod"}: custom textures by Cyrus`.slice(0, 100), mcVersion: chain.mcVersion, textures: [...current, doc].slice(0, 24) });
401	    if (!built.ok) pack = { skipped: built.error };
402	    else {
403	      packEntry = { path: `resourcepack/${built.pack.sha1}.zip`, sha256: sha256Hex(built.pack.zip), role: "resourcePack" };
404	      const pub = deps.publish ? await deps.publish(built.pack.zip).catch((e) => ({ ok: false as const, reason: (e as Error).message })) : { ok: false as const, reason: "pack hosting is not configured" };
405	      pack = { sha1: built.pack.sha1, hosted: pub.ok };
406	    }
407	  }
408	  const path = `assets/textures/${input.key}.json`;
409	  const manifest: ManifestEntry[] = [
410	    ...(head?.manifest ?? []).filter((e) => e.path !== path && !(packEntry && e.role === "resourcePack")),
411	    { path, sha256, role: "asset" },
412	    ...(packEntry ? [packEntry] : []),
413	  ];
414	  let rev: { id: string; seq: number };
415	  try {
416	    rev = await deps.store.addRevision(project.id, {
417	      kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null,
418	      engine: { toolchain: `cyrus-texture-studio ${QUALITY_VERSION}` },
419	      message: (input.message ?? (input.decision ? (input.decision.accepted ? `Accepted Cyrus candidate for ${input.key}` : `Kept ${input.key} (rejected a Cyrus candidate)`) : origin === "library" ? `Added ${input.key} from the Texture Library` : `Edited ${input.key} in Texture Studio`)).slice(0, 200),
420	    });
421	  } catch (e) {
422	    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
423	    throw e;
424	  }
425	  const asset = await deps.store.recordAsset(project.id, {
426	    revisionId: rev.id, assetKey: input.key, kind: "texture", sha256, size: Buffer.byteLength(canonical), origin, mime: TEXTURE_DOC_MIME, path,
427	    provenance: { generator: "cyrus-texture-studio", doc, quality, pngSha256: sha256Hex(png), basedOn: base?.id ?? null, packSha1: "sha1" in pack ? pack.sha1 : null, ...(input.provenance ?? {}) },
428	  });
429	  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, quality, pack };
430	}
431	
432	// ---------------------------------------------------------------------------- candidates (the AI edit interface)
433	
434	/**
435	 * The interface the studio uses to ask Cyrus for a texture edit. The real implementation (./candidates.ts
436	 * changeBuildCandidates) creates a CHANGE BUILD through the existing flow and returns the build's texture when it
437	 * completes; tests and devhost use fakeCandidates. A candidate is never applied by the backend: the customer
438	 * accepts (saves a revision), applies part of it, or rejects it.
439	 */
440	export type CandidateRequest = { userId: string; user: unknown; project: ProjectRow; chain: ChainInfo; key: string; prompt: string; current: TextureEntry };
441	export type CandidatePoll =
442	  | { status: "pending"; note?: string }
443	  | { status: "ready"; doc: TextureDoc; specSha256: string; summary: string }
444	  | { status: "failed"; error: string };
445	export interface CandidateBackend {
446	  readonly id: string;
447	  request(r: CandidateRequest): Promise<{ ok: true; requestId: string } | { ok: false; status: number; code: string; error: string }>;
448	  poll(r: { userId: string; project: ProjectRow; chain: ChainInfo; key: string; requestId: string }): Promise<CandidatePoll>;
449	}
450	
451	export const MAX_PROMPT = 600;
452	
453	export async function textureForEdit(deps: StudioServiceDeps, userId: string, projectId: string, key: string) {
454	  gateOrThrow(canAsset(await deps.planOf(userId).catch(() => null), "texture", "edit"));
455	  const project = await ownedProject(deps, userId, projectId);
456	  if (!project.rootBuildId) throw new StudioError(409, "no_build", "Build the mod once before asking Cyrus to edit its textures.");
457	  const chain = await deps.chain(userId, project.rootBuildId);
458	  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
459	  const t = resolveTextures(await deps.store.assets(project.id), new Set(chain.candidateBuilds.map((b) => b.id))).find((x) => x.key === key);
460	  if (!t) throw new StudioError(404, "not_found", `No texture called ${key} in this mod.`);
461	  return { project, chain, texture: t };
462	}
463	
464	/**
465	 * The spec sha256 of a candidate, read on the SERVER (never from the client): a candidate build the asset sync already
466	 * recorded (any backend), else the backend's own poll. Null when it is not ready.
467	 */
468	export async function candidateSpecSha(backend: CandidateBackend, r: { userId: string; project: ProjectRow; chain: ChainInfo; texture: TextureEntry; key: string; requestId: string }): Promise<string | null> {
469	  const persisted = r.texture.candidates.find((c) => c.buildId === r.requestId);
470	  if (persisted) return persisted.specSha256;
471	  const poll = await backend.poll({ userId: r.userId, project: r.project, chain: r.chain, key: r.key, requestId: r.requestId });
472	  return poll.status === "ready" ? poll.specSha256 : null;
473	}
474	
475	/** Reject a candidate: keep the current doc as a new revision that records the decision (and supersedes the candidate spec). */
476	export async function rejectCandidate(deps: StudioServiceDeps, backend: CandidateBackend, i: { userId: string; projectId: string; key: string; requestId: string; expectedHeadId: string | null }) {
477	  const { project, chain, texture } = await textureForEdit(deps, i.userId, i.projectId, i.key);
478	  const sha = await candidateSpecSha(backend, { userId: i.userId, project, chain, texture, key: i.key, requestId: i.requestId });
479	  const also = sha ? [sha] : [];
480	  return saveTexture(deps, {
481	    userId: i.userId, projectId: project.id, key: i.key, doc: { ...texture.doc, decision: undefined }, baseAssetId: texture.assetId, expectedHeadId: i.expectedHeadId,
482	    decision: { candidate: i.requestId, accepted: false }, alsoSupersedes: also,
483	  });
484	}
485	
486	/** A deterministic fake: the "edit" applies the Style DNA (drops noise and gradient ops) or adds a 1 px highlight. */
487	export function fakeCandidates(opts: { readyAfter?: number } = {}): CandidateBackend & { requests: Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }> } {
488	  const requests = new Map<string, { key: string; prompt: string; base: TextureDoc; polls: number }>();
489	  let n = 0;
490	  return {
491	    id: "fake", requests,
492	    async request(r) {
493	      const requestId = `fake${(++n).toString().padStart(4, "0")}${r.key.slice(0, 8)}`;
494	      requests.set(requestId, { key: r.key, prompt: r.prompt, base: r.current.doc, polls: 0 });
495	      return { ok: true, requestId };
496	    },
497	    async poll(r) {
498	      const q = requests.get(r.requestId);
499	      if (!q || q.key !== r.key) return { status: "failed", error: "unknown candidate" };
500	      if (++q.polls <= (opts.readyAfter ?? 1)) return { status: "pending", note: "Cyrus is drawing a candidate" };
501	      const spec = q.base.spec;
502	      if (!spec) return { status: "failed", error: "this texture has no generated base to edit" };
503	      let ops = spec.ops.filter((o) => o.op !== "noise" && o.op !== "gradient");
504	      if (ops.length === spec.ops.length) {
505	        const light = Object.entries(spec.palette).sort((a, b) => parseInt(b[1].slice(1), 16) - parseInt(a[1].slice(1), 16))[0][0];
506	        const at = Math.max(0, ops.findIndex((o) => o.op === "shade" || o.op === "outline"));
507	        ops = [...ops.slice(0, at), { op: "px", x: Math.floor(spec.size / 3), y: Math.floor(spec.size / 3), c: light }, ...ops.slice(at)];
508	      }
509	      const cand: TextureSpec = { ...spec, ops };
510	      return { status: "ready", doc: { ...docFromSpec(cand), name: q.key }, specSha256: sha256Hex(canonicalJson(cand)), summary: q.prompt };
511	    },
512	  };
513	}
514

// Cyrus studios (R1b): the HTTP handlers of /api/cyrus/assets/v1/** (versioned). Framework-free (Request -> Response)
// so they are tested with fakes; app/api/cyrus/assets/v1/** are one-line wrappers with apiDeps() (./deps.ts).
// Every handler: viewer (Cyrus user + studios visibility; anyone else gets a 404 as if the route did not exist) ->
// rate limit -> input validation -> the plan gate (create/edit only, server side, fail closed) -> the service.
import { canBrowse } from "../library/gate";
import { browseLibrary, type CatalogDeps } from "../library/catalog";
import { decodePng } from "../library/png-decode";
import { uploadTexture, UPLOAD_LIMITS, type UploadStorage } from "../library/upload";
import { useTextureFromLibrary } from "../library/use-in-project";
import { LIBRARY_KINDS, LIBRARY_SOURCES, type LibraryAsset } from "../library/types";
import { libraryTexture, librarySpec } from "../texture-library/library";
import { template } from "../texture-library/templates";
import { checkDoc, docFromRaster, docFromSpec, docQuality, type TextureDoc } from "./paint";
import {
  candidateSpecSha, docOfRow, MAX_PROMPT, packStatusOf, projectAssets, rejectCandidate, resolveTextures, saveTexture, StudioError, textureForEdit,
  type CandidateBackend, type StudioServiceDeps,
} from "./service";

export type StudioViewer = { userId: string; user?: unknown; preview: boolean };
export type UploadStore = UploadStorage & { get(path: string): Promise<Buffer | null> };
export type StudioApiDeps = {
  viewer: () => Promise<StudioViewer | null>;
  service: StudioServiceDeps;
  candidates: CandidateBackend;
  catalog: CatalogDeps;
  rateLimit: (key: string, max: number, windowMs: number) => { ok: boolean; retryAfterSec?: number };
  /** null = uploads are not switched on (no production upload storage yet) */
  uploads: UploadStore | null;
};

const H = { "cache-control": "no-store", "x-robots-tag": "noindex" };
const json = (status: number, body: unknown) => Response.json(body, { status, headers: H });
export const NOT_FOUND = () => json(404, { error: "Not found" });
const RE = {
  root: /^[A-Za-z0-9_-]{1,64}$/, project: /^cp[0-9a-f]{20}$/, key: /^[a-z][a-z0-9_]{1,31}$/, id: /^[A-Za-z0-9_-]{1,64}$/,
  ref: /^(sound|texture|model)\/(builtin|user|project)\/[A-Za-z0-9_:.-]{1,120}$/,
};
const MAX_BODY = 512 * 1024;

async function readJson(req: Request): Promise<Record<string, unknown>> {
  const len = Number(req.headers.get("content-length") ?? 0);
  if (len > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  const text = await req.text();
  if (text.length > MAX_BODY) throw new StudioError(413, "too_large", "That request is too large.");
  try { const v = JSON.parse(text || "{}"); if (v && typeof v === "object" && !Array.isArray(v)) return v; } catch { /* fallthrough */ }
  throw new StudioError(400, "bad_json", "Send a JSON object.");
}

type Ctx = { deps: StudioApiDeps; viewer: StudioViewer };
/** viewer + rate limit + error mapping around a handler body. */
async function run(deps: StudioApiDeps, limit: { key: string; max: number }, body: (c: Ctx) => Promise<Response>): Promise<Response> {
  const viewer = await deps.viewer().catch(() => null);
  if (!viewer) return NOT_FOUND();
  const rl = deps.rateLimit(`${limit.key}:${viewer.userId}`, limit.max, 60_000);
  if (!rl.ok) return json(429, { error: `Too many requests. Wait ${rl.retryAfterSec ?? 30}s.`, code: "rate_limited" });
  try {
    return await body({ deps, viewer });
  } catch (e) {
    if (e instanceof StudioError) return json(e.status, { error: e.message, code: e.code, ...e.extra });
    console.error("[cyrus-studio]", limit.key, (e as Error).message);
    return json(500, { error: "Something went wrong on our side. Nothing was changed.", code: "server_error" });
  }
}
const need = (ok: boolean, msg: string) => { if (!ok) throw new StudioError(400, "bad_request", msg); };

// ---------------------------------------------------------------------------- projects + textures

/** GET /api/cyrus/assets/v1/projects?root=<rootBuildId>: the mod's assets, the viewer's studio access and pack status. */
export const handleProjectAssets = (req: Request, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const root = new URL(req.url).searchParams.get("root") ?? "";
  need(RE.root.test(root), "root must be a build id");
  return json(200, { ...(await projectAssets(deps.service, viewer.userId, root)), uploads: !!deps.uploads, candidates: deps.candidates.id });
});

type P = { projectId?: string; key?: string; requestId?: string; assetId?: string };
const params = (p: P, ...names: (keyof P)[]) => {
  for (const n of names) {
    const v = p[n] ?? "";
    const re = n === "projectId" ? RE.project : n === "key" ? RE.key : RE.id;
    need(re.test(v), `${n} is not valid`);
  }
  return p as Required<P>;
};

/** GET .../projects/:projectId/textures/:key/revisions: the texture's history (every revision keeps its doc + quality). */
export const handleTextureHistory = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const { projectId, key } = params(p, "projectId", "key");
  const proj = await deps.service.store.project(projectId);
  if (!proj || proj.userId !== viewer.userId) throw new StudioError(404, "not_found", "Project not found.");
  const chain = proj.rootBuildId ? await deps.service.chain(viewer.userId, proj.rootBuildId) : null;
  const t = resolveTextures(await deps.service.store.assets(projectId), new Set(chain?.candidateBuilds.map((b) => b.id) ?? [])).find((x) => x.key === key);
  if (!t) throw new StudioError(404, "not_found", `No texture called ${key} in this mod.`);
  const revs = await deps.service.store.revisions(projectId);
  const seq = new Map(revs.map((r) => [r.id, r.seq]));
  return json(200, { key, history: t.history.map((h) => ({ ...h, revisionSeq: seq.get(h.revisionId) ?? null, quality: docQuality(h.doc) })) });
});

/** POST .../projects/:projectId/textures/:key/revisions { doc, baseAssetId, expectedHeadId, decision? }: save as a NEW revision. */
export const handleSaveRevision = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "save", max: 30 }, async ({ viewer }) => {
  const { projectId, key } = params(p, "projectId", "key");
  const b = await readJson(req);
  need(b.baseAssetId === null || (typeof b.baseAssetId === "string" && RE.id.test(b.baseAssetId)), "baseAssetId must be an asset id or null");
  need(b.expectedHeadId === null || (typeof b.expectedHeadId === "string" && RE.id.test(b.expectedHeadId)), "expectedHeadId must be a revision id or null");
  let decision = null;
  let also: string[] = [];
  if (b.acceptCandidate !== undefined) {
    // accepting: the server re-reads the candidate (never trusts a client copy of it) and records the decision
    need(typeof b.acceptCandidate === "string" && RE.id.test(b.acceptCandidate), "acceptCandidate must be a candidate id");
    const { project, chain, texture } = await textureForEdit(deps.service, viewer.userId, projectId, key);
    const sha = await candidateSpecSha(deps.candidates, { userId: viewer.userId, project, chain, texture, key, requestId: b.acceptCandidate as string });
    if (!sha) throw new StudioError(409, "candidate_not_ready", "That candidate isn't ready.");
    decision = { candidate: b.acceptCandidate as string, accepted: true };
    also = [sha];
  }
  const r = await saveTexture(deps.service, {
    userId: viewer.userId, projectId, key, doc: b.doc, baseAssetId: (b.baseAssetId as string | null) ?? null, expectedHeadId: (b.expectedHeadId as string | null) ?? null,
    decision, alsoSupersedes: also,
  });
  return json(201, r);
});

/** POST /api/cyrus/assets/v1/quality { doc }: the real tq-1 checks on the composite (read-only, no plan gate). */
export const handleQuality = (req: Request, deps: StudioApiDeps) => run(deps, { key: "quality", max: 120 }, async () => {
  const b = await readJson(req);
  const d = checkDoc(b.doc);
  if (!d.ok) throw new StudioError(400, "bad_doc", d.error);
  return json(200, docQuality(d.doc));
});

/** GET .../projects/:projectId/pack: resource pack status of the mod. */
export const handlePackStatus = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const { projectId } = params(p, "projectId");
  const proj = await deps.service.store.project(projectId);
  if (!proj || proj.userId !== viewer.userId || !proj.rootBuildId) throw new StudioError(404, "not_found", "Project not found.");
  const chain = await deps.service.chain(viewer.userId, proj.rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  return json(200, packStatusOf(chain, deps.service.deliveryOn(), false));
});

// ---------------------------------------------------------------------------- candidates

/** POST .../textures/:key/candidates { prompt }: ask Cyrus for an edit (a candidate, never applied by itself). */
export const handleRequestCandidate = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "candidate", max: 6 }, async ({ viewer }) => {
  const { projectId, key } = params(p, "projectId", "key");
  const b = await readJson(req);
  const prompt = typeof b.prompt === "string" ? b.prompt.trim() : "";
  need(prompt.length >= 4 && prompt.length <= MAX_PROMPT, `Describe the change in 4 to ${MAX_PROMPT} characters.`);
  const { project, chain, texture } = await textureForEdit(deps.service, viewer.userId, projectId, key);
  const r = await deps.candidates.request({ userId: viewer.userId, user: viewer.user, project, chain, key, prompt, current: texture });
  if (!r.ok) return json(r.status, { error: r.error, code: r.code });
  return json(202, { requestId: r.requestId, backend: deps.candidates.id });
});

/** GET .../textures/:key/candidates/:requestId: pending | ready (with the candidate doc + quality) | failed. */
export const handlePollCandidate = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "poll", max: 120 }, async ({ viewer }) => {
  const { projectId, key, requestId } = params(p, "projectId", "key", "requestId");
  const { project, chain } = await textureForEdit(deps.service, viewer.userId, projectId, key);
  const r = await deps.candidates.poll({ userId: viewer.userId, project, chain, key, requestId });
  return json(200, r.status === "ready" ? { ...r, quality: docQuality(r.doc) } : r);
});

/** POST .../textures/:key/candidates/:requestId/reject { expectedHeadId }: keep the current texture, record the decision. */
export const handleRejectCandidate = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "save", max: 30 }, async ({ viewer }) => {
  const { projectId, key, requestId } = params(p, "projectId", "key", "requestId");
  const b = await readJson(req);
  need(b.expectedHeadId === null || (typeof b.expectedHeadId === "string" && RE.id.test(b.expectedHeadId)), "expectedHeadId must be a revision id or null");
  return json(201, await rejectCandidate(deps.service, deps.candidates, { userId: viewer.userId, projectId, key, requestId, expectedHeadId: (b.expectedHeadId as string | null) ?? null }));
});

// ---------------------------------------------------------------------------- library

export type LibraryItem = Pick<LibraryAsset, "ref" | "kind" | "source" | "id" | "name" | "category" | "subcategory" | "tags" | "useCases" | "descriptors"> & {
  ledger: { provenance: string; licenceStatus: string; original: boolean };
  /** texture pixels to preview (template spec, or a project doc); `png` = an upload's preview URL */
  preview: { doc?: TextureDoc; png?: string } | null;
};

async function previewOf(a: LibraryAsset, deps: StudioApiDeps, userId: string): Promise<LibraryItem["preview"]> {
  if (a.preview.type === "texture-template") {
    const item = libraryTexture(a.preview.itemId);
    const spec = item ? librarySpec(item) : null;
    const t = item ? template(item.templateId) : null;
    return spec ? { doc: { ...docFromSpec(spec), ...(t?.profile === "tile" ? { tile: { tileable: t.tileable, framed: !!t.framed } } : {}) } } : null;
  }
  if (a.preview.type === "texture-asset") {
    const row = await deps.service.store.assetById(a.preview.assetId);
    if (!row) return null;
    const proj = await deps.service.store.project(row.projectId);
    if (!proj || proj.userId !== userId) return null;
    const doc = docOfRow(row);
    return doc ? { doc } : row.mime === "image/png" ? { png: `/api/cyrus/assets/v1/library/asset/${row.id}/png` } : null;
  }
  return null;
}

/** GET /api/cyrus/assets/v1/library?kind=&q=&category=&tags=&source=&offset=&limit=&projectId= */
export const handleBrowse = (req: Request, deps: StudioApiDeps) => run(deps, { key: "browse", max: 120 }, async ({ viewer }) => {
  const u = new URL(req.url).searchParams;
  const kind = u.get("kind") ?? "texture";
  need((LIBRARY_KINDS as readonly string[]).includes(kind), "kind must be sound, texture or model");
  const text = (u.get("q") ?? "").slice(0, 120);
  const category = u.get("category"), sub = u.get("sub"), source = u.get("source");
  need(!category || /^[a-z_]{1,40}$/.test(category), "bad category");
  need(!sub || /^[a-z_]{1,40}$/.test(sub), "bad subcategory");
  need(!source || (LIBRARY_SOURCES as readonly string[]).includes(source), "bad source");
