  need(tags.length <= 8 && tags.every((t) => /^[a-z0-9_-]{1,32}$/.test(t)), "bad tags");
  const offset = Math.max(0, Math.min(5000, Number(u.get("offset") ?? 0) | 0));
  const limit = Math.max(1, Math.min(60, Number(u.get("limit") ?? 40) | 0));
