  if (projectId) { need(RE.project.test(projectId), "bad projectId"); const pr = await deps.service.store.project(projectId); if (!pr || pr.userId !== viewer.userId) projectId = null; }
  const r = await browseLibrary(deps.catalog, {
    userId: viewer.userId, projectId,
    query: { kinds: [kind as LibraryAsset["kind"]], text, ...(category ? { category } : {}), ...(sub ? { subcategory: sub } : {}), ...(source ? { sources: [source as LibraryAsset["source"]] } : {}), ...(tags.length ? { tags } : {}), offset, limit },
  });
  const items: LibraryItem[] = [];
  for (const a of r.items) items.push({
