175	    if (typeof e.event !== "string" || !EVENT.test(e.event)) return { ok: false, error: `${at}.event must be lowercase letters, digits and underscores (1-24 chars)` };
176	    if (events.some((x) => x.event === e.event)) return { ok: false, error: `${at}: duplicate event ${e.event}` };
177	    if (!(SOUND_ROLES as readonly string[]).includes(e.role as string)) return { ok: false, error: `${at}.role must be one of ${SOUND_ROLES.join(", ")}` };
178	    const role = e.role as SoundRole;
179	    let category = DEFAULT_CATEGORY[role];
180	    if (e.category !== undefined) { if (!(SOUND_CATEGORIES as readonly string[]).includes(e.category as string)) return { ok: false, error: `${at}.category must be one of ${SOUND_CATEGORIES.join(", ")}` }; category = e.category as SoundCategory; }
181	    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3 || e.subtitle.length > 60 || /[\u0000-\u001f<>§]/.test(e.subtitle)) return { ok: false, error: `${at}.subtitle is required: 3-60 characters of plain text (what a deaf player should read, e.g. "Banshee wails")` };
182	    if (!Array.isArray(e.variants) || e.variants.length < 1 || e.variants.length > MAX_VARIANTS) return { ok: false, error: `${at}.variants must be a list of 1-${MAX_VARIANTS}` };
183	    const variants: SoundVariant[] = [];
184	    for (const [vi, rawV] of e.variants.entries()) {
185	      const vat = `${at}.variants[${vi}]`;
186	      if (!rawV || typeof rawV !== "object" || Array.isArray(rawV)) return { ok: false, error: `${vat} must be an object` };
187	      const v = rawV as Record<string, unknown>;
188	      for (const k of Object.keys(v)) if (!["weight", "layers", "processing"].includes(k)) return { ok: false, error: `${vat}: unknown field ${k}` };
189	      let weight = 1;
190	      if (v.weight !== undefined) { if (typeof v.weight !== "number" || !Number.isInteger(v.weight) || v.weight < 1 || v.weight > 10) return { ok: false, error: `${vat}.weight must be an integer 1-10` }; weight = v.weight; }
191	      if (!Array.isArray(v.layers) || v.layers.length < 1 || v.layers.length > MAX_LAYERS) return { ok: false, error: `${vat}.layers must be a list of 1-${MAX_LAYERS}` };
192	      const layers: SoundLayer[] = [];
193	      for (const [li, rawL] of v.layers.entries()) { const c = checkLayer(rawL, `${vat}.layers[${li}]`, ctx); if (!c.ok) return c; layers.push(c.layer); }
194	      if (layers.every((l) => l.source === "silence")) return { ok: false, error: `${vat}: needs at least one layer that is not silence` };
195	      const pc = checkProcessing(v.processing, `${vat}.processing`);
196	      if (!pc.ok) return pc;
197	      const variant: SoundVariant = { weight, layers, processing: pc.p };
198	      if (rawLibraryCopy(variant)) return { ok: false, error: `${vat}: a library sound may not ship unchanged; change its pitch, layer it with another sound or add lowpass/highpass/reverb/echo` };
199	      const est = estimateVariantSeconds(variant, ctx.catalog);
200	      if (est > ROLE_PROFILE[role].maxSeconds + 0.5) return { ok: false, error: `${vat} is about ${est.toFixed(2)} s; a ${role} sound may be at most ${ROLE_PROFILE[role].maxSeconds} s (trim it with "length")` };
201	      seconds += est;
202	      variants.push(variant);
203	    }
204	    events.push({ event: e.event, role, category, subtitle: e.subtitle.trim(), variants });
205	  }
206	  seconds = r4(seconds);
207	  if (seconds > MAX_SPEC_SECONDS) return { ok: false, error: `the variants add up to about ${seconds.toFixed(1)} s; the limit per sound set is ${MAX_SPEC_SECONDS} s` };
208	  return { ok: true, spec: { version: 1, name: r.name, events }, seconds };
209	}
