270	// SoundSpec -> PCM (Cyrus R1 sound slice). Pure: the caller supplies decoded library sources (mono 44.1 kHz), so
271	// this runs the same in the render host (runner.ts, real library via ffmpeg) and in tests (synth-only / fake sources).
272	// Chain per variant:
273	//   layers: source (library | synth preset | silence) -> trimStart/length -> pitch (resample) -> fades -> gain -> mix at start
274	//   processing: highpass, lowpass, echo, reverb
275	//   finish: 30 Hz rumble cut + DC block -> trim leading/trailing silence (-60 dBFS) -> cap at the role's max length
276	//           -> 2 ms / 8 ms edge fades -> normalise to the role's loudness target -> look-ahead limiter at -1.5 dBFS
277	//           (the -1 dBTP ceiling is checked again on the DECODED Ogg, after the encoder).
278	import { biquad, capLength, dcBlock, echo, fade, gain, limit, mixAt, repitch, reverb, trim, trimSilence, type Mono } from "./dsp";
279	import { measure, normalizeGainDb, rumbleCut } from "./measure";
280	import { ROLE_PROFILE, type SoundRole, type SoundSpec, type SoundVariant, type SynthPreset } from "./spec";
281	import { synth } from "./synth";
282	
283	export const RENDER_VERSION = "sr-1";
284	export const LIMIT_CEILING_DB = -1.5;
285	
286	export type SourceLoader = (libraryId: string) => Mono;
287	export type RenderedVariant = { pcm: Mono; truncated: boolean; gainDb: number; peakLimited: boolean };
288	
289	export function renderVariant(v: SoundVariant, role: SoundRole, load: SourceLoader, ceilingDb = LIMIT_CEILING_DB): RenderedVariant {
290	  let mix: Mono = new Float64Array(0);
291	  for (const l of v.layers) {
292	    let x: Mono;
293	    if (l.source === "silence") x = new Float64Array(Math.round((l.length ?? 0) * 44100));
294	    else if (l.source.startsWith("synth:")) x = synth(l.source.slice(6) as SynthPreset, l.length ?? 0.5, l.seed, l.params);
295	    else x = trim(load(l.source.slice(4)), l.trimStart, l.length ?? undefined);
296	    x = repitch(x, l.pitch);
297	    if (l.fadeIn || l.fadeOut) x = fade(x, l.fadeIn, l.fadeOut);
298	    x = gain(x, l.gain);
299	    mix = mixAt(mix, x, l.start);
300	  }
301	  const p = v.processing;
302	  if (p.highpass) mix = biquad(mix, "highpass", p.highpass);
303	  if (p.lowpass) mix = biquad(mix, "lowpass", p.lowpass);
304	  if (p.echo) mix = echo(mix, p.echo.delay, p.echo.feedback, p.echo.mix);
305	  if (p.reverb > 0) mix = reverb(mix, p.reverb);
306	  mix = trimSilence(dcBlock(rumbleCut(mix)));
307	  const capped = capLength(mix, ROLE_PROFILE[role].maxSeconds);
308	  mix = fade(capped.pcm, 2, 8);
309	  if (!mix.length) return { pcm: mix, truncated: capped.truncated, gainDb: 0, peakLimited: false };
310	  const g = normalizeGainDb(measure(mix), role, ceilingDb);
311	  mix = limit(gain(mix, Math.max(-40, Math.min(40, g.gainDb))), ceilingDb);
312	  return { pcm: mix, truncated: capped.truncated, gainDb: g.gainDb, peakLimited: g.peakLimited };
313	}
