326	// Cyrus sound measurement + quality bar v1 (`sq-1`, R1 sound slice). Pure and deterministic.
327	//   measure(): sample peak, true-peak estimate (4x oversampling, BS.1770-style), integrated loudness approximation
328	//   (K-weighting + 400 ms gated blocks; one ungated block for clips shorter than 400 ms), silence ratio, DC offset.
329	//   soundQuality(): the checks every shipped variant must pass (measured on the DECODED Ogg, i.e. what players hear).
330	import { biquad, biquadRaw, dbToLin, linToDb, SAMPLE_RATE, type Mono } from "./dsp";
331	import { ROLE_PROFILE, type SoundRole } from "./spec";
332	
333	export const SOUND_QUALITY_VERSION = "sq-1";
334	const r2 = (v: number) => (Number.isFinite(v) ? Math.round(v * 100) / 100 : v === Infinity ? 999 : -999);
335	
336	/** K-weighting coefficients (BS.1770) for any sample rate (the pyloudnorm derivation). */
337	function kWeight(x: Mono, fs: number): Mono {
338	  let K = Math.tan((Math.PI * 1681.974450955533) / fs);
339	  const Q1 = 0.7071752369554196, Vh = Math.pow(10, 3.999843853973347 / 20), Vb = Math.pow(Vh, 0.4996667741545416);
340	  let a0 = 1 + K / Q1 + K * K;
341	  const s1 = [(Vh + (Vb * K) / Q1 + K * K) / a0, (2 * (K * K - Vh)) / a0, (Vh - (Vb * K) / Q1 + K * K) / a0, (2 * (K * K - 1)) / a0, (1 - K / Q1 + K * K) / a0];
342	  K = Math.tan((Math.PI * 38.13547087602444) / fs);
343	  const Q2 = 0.5003270373238773;
344	  a0 = 1 + K / Q2 + K * K;
345	  const s2 = [1, -2, 1, (2 * (K * K - 1)) / a0, (1 - K / Q2 + K * K) / a0];
346	  return biquadRaw(biquadRaw(x, s1), s2);
347	}
348	
349	/** Integrated loudness (LUFS) of a mono clip; -999 for digital silence. */
350	export function loudness(x: Mono, fs = SAMPLE_RATE): number {
351	  if (!x.length) return -999;
352	  const y = kWeight(x, fs);
353	  const block = Math.round(0.4 * fs), step = Math.round(0.1 * fs);
354	  const ms: number[] = [];
355	  if (y.length < block) { let s = 0; for (let i = 0; i < y.length; i++) s += y[i] * y[i]; ms.push(s / y.length); }
356	  else for (let a = 0; a + block <= y.length; a += step) { let s = 0; for (let i = a; i < a + block; i++) s += y[i] * y[i]; ms.push(s / block); }
357	  const L = (z: number) => -0.691 + 10 * Math.log10(z);
358	  const abs = ms.filter((z) => z > 0 && L(z) > -70);
359	  if (!abs.length) return -999;
360	  const relGate = L(abs.reduce((a, b) => a + b, 0) / abs.length) - 10;
361	  const gated = ms.length === 1 ? abs : abs.filter((z) => L(z) > relGate);
362	  return r2(L(gated.reduce((a, b) => a + b, 0) / gated.length));
363	}
364	
365	// 4-phase, 12-tap Hann-windowed sinc interpolator for the true-peak estimate.
366	const TP_PHASES = (() => {
367	  const taps = 12, phases = 4, out: number[][] = [];
368	  for (let p = 0; p < phases; p++) {
369	    const h: number[] = [];
370	    for (let k = 0; k < taps; k++) {
371	      const t = k - taps / 2 + 1 - p / phases;
372	      const sinc = t === 0 ? 1 : Math.sin(Math.PI * t) / (Math.PI * t);
373	      const w = 0.5 + 0.5 * Math.cos((Math.PI * t) / (taps / 2));
374	      h.push(sinc * w);
375	    }
376	    const sum = h.reduce((a, b) => a + b, 0);
377	    out.push(h.map((v) => v / sum));
378	  }
379	  return out;
380	})();
381	
382	export function truePeakDb(x: Mono): number {
383	  let m = 0;
384	  for (let i = 0; i < x.length; i++) {
385	    const a = Math.abs(x[i]); if (a > m) m = a;
386	    for (let p = 1; p < 4; p++) {
387	      let s = 0; const h = TP_PHASES[p];
388	      for (let k = 0; k < h.length; k++) { const j = i + k - 5; if (j >= 0 && j < x.length) s += x[j] * h[k]; }
389	      const b = Math.abs(s); if (b > m) m = b;
390	    }
391	  }
392	  return r2(linToDb(m));
393	}
394	
395	export type SoundMeasure = { durationS: number; samplePeakDb: number; truePeakDb: number; lufs: number; silenceRatio: number; dcOffset: number };
396	
397	export function measure(x: Mono, fs = SAMPLE_RATE): SoundMeasure {
398	  let peak = 0, sum = 0;
399	  for (let i = 0; i < x.length; i++) { const a = Math.abs(x[i]); if (a > peak) peak = a; sum += x[i]; }
400	  const win = Math.round(0.01 * fs), t = dbToLin(-50);
401	  let quiet = 0, wins = 0;
402	  for (let a = 0; a < x.length; a += win) {
403	    let s = 0; const b = Math.min(x.length, a + win);
404	    for (let i = a; i < b; i++) s += x[i] * x[i];
405	    wins++; if (Math.sqrt(s / (b - a)) < t) quiet++;
406	  }
407	  return {
408	    durationS: Math.round((x.length / fs) * 1000) / 1000, samplePeakDb: r2(linToDb(peak)), truePeakDb: truePeakDb(x), lufs: loudness(x, fs),
409	    silenceRatio: wins ? Math.round((quiet / wins) * 1000) / 1000 : 1, dcOffset: x.length ? Math.round((sum / x.length) * 1e6) / 1e6 : 0,
410	  };
411	}
412	
413	/** Gain (dB) that brings a clip to the role's target loudness, never above the true-peak ceiling. */
414	export function normalizeGainDb(m: SoundMeasure, role: SoundRole, ceilingDbtp: number): { gainDb: number; peakLimited: boolean } {
415	  const want = m.lufs <= -998 ? 0 : ROLE_PROFILE[role].target - m.lufs;
416	  const room = ceilingDbtp - m.truePeakDb;
417	  return { gainDb: r2(want), peakLimited: want > room };
418	}
