420	export type SoundCheck = { id: string; status: "pass" | "warn" | "fail"; value: number | string; limit: string; message: string };
421	export type SoundQualityReport = { version: string; verdict: "pass" | "warn" | "fail"; role: SoundRole; checks: SoundCheck[] };
422	export type EncodedInfo = { codec: string; channels: number; sampleRate: number };
423	
424	export const TRUE_PEAK_MAX = -1;
425	
426	/** The quality bar for one rendered variant (decoded from its Ogg). */
427	export function soundQuality(m: SoundMeasure, enc: EncodedInfo, role: SoundRole): SoundQualityReport {
428	  const prof = ROLE_PROFILE[role];
429	  const checks: SoundCheck[] = [];
430	  checks.push({ id: "format", status: enc.codec === "vorbis" && enc.channels === 1 ? "pass" : "fail", value: `${enc.codec}/${enc.channels}ch/${enc.sampleRate}`, limit: "vorbis, mono", message: enc.channels === 1 ? "mono Ogg Vorbis (positional in game)" : "must be mono: stereo sounds ignore distance in Minecraft" });
431	  checks.push({ id: "true_peak", status: m.truePeakDb <= TRUE_PEAK_MAX ? "pass" : m.truePeakDb <= -0.3 ? "warn" : "fail", value: m.truePeakDb, limit: `<= ${TRUE_PEAK_MAX} dBTP`, message: m.truePeakDb <= TRUE_PEAK_MAX ? "no clipping headroom problem" : "too close to clipping" });
432	  const inBand = m.lufs >= prof.min && m.lufs <= prof.max;
433	  const near = m.lufs >= prof.min - 4 && m.lufs <= prof.max + 2;
434	  checks.push({ id: "loudness", status: inBand ? "pass" : near ? "warn" : "fail", value: m.lufs, limit: `${prof.min}..${prof.max} LUFS (${role})`, message: inBand ? `loudness fits a ${role} sound` : m.lufs < prof.min ? `quieter than a ${role} sound should be` : `louder than a ${role} sound should be` });
435	  checks.push({ id: "audible", status: m.samplePeakDb > -40 ? "pass" : "fail", value: m.samplePeakDb, limit: "> -40 dBFS peak", message: m.samplePeakDb > -40 ? "audible" : "practically silent" });
436	  checks.push({ id: "silence_ratio", status: m.silenceRatio <= 0.35 ? "pass" : m.silenceRatio <= 0.6 ? "warn" : "fail", value: m.silenceRatio, limit: "<= 0.35 (fail > 0.6)", message: m.silenceRatio <= 0.35 ? "little dead air" : "long silent stretches" });
437	  const dc = Math.abs(m.dcOffset);
438	  checks.push({ id: "dc_offset", status: dc <= 0.002 ? "pass" : dc <= 0.01 ? "warn" : "fail", value: m.dcOffset, limit: "|dc| <= 0.002 (fail > 0.01)", message: dc <= 0.002 ? "centred" : "the waveform is off-centre" });
439	  checks.push({ id: "duration", status: m.durationS >= 0.03 && m.durationS <= prof.maxSeconds ? "pass" : "fail", value: m.durationS, limit: `0.03..${prof.maxSeconds} s (${role})`, message: m.durationS > prof.maxSeconds ? `too long for a ${role} sound` : m.durationS < 0.03 ? "too short to hear" : "length fits" });
440	  const verdict = checks.some((c) => c.status === "fail") ? "fail" : checks.some((c) => c.status === "warn") ? "warn" : "pass";
441	  return { version: SOUND_QUALITY_VERSION, verdict, role, checks };
442	}
443	export const soundQualityProblems = (r: SoundQualityReport) => r.checks.filter((c) => c.status === "fail").map((c) => `${c.id}: ${c.message} (value ${c.value}, limit ${c.limit})`);
444	
445	/** Highpass at 30 Hz used by the render chain before measuring (rumble the client speakers cannot play anyway). */
446	export const rumbleCut = (x: Mono) => biquad(x, "highpass", 30);
