export function libraryCatalogText(files: readonly LibrarySound[] = manifest.files): string {
  const lines = [
    "# Nxeon sound library catalog (read-only). One sound per line: <id> <duration class> <use cases>.",
    "# Duration classes: stinger < 0.5 s, short < 2 s, medium < 6 s, long. Use an id as a layer source: {\"source\": \"lib:<id>\"} and trim with \"length\".",
  ];
  for (const c of CATEGORY_IDS) {
    const xs = files.filter((f) => f.category === c).sort((a, b) => (a.id < b.id ? -1 : 1));
    if (!xs.length) continue;
    lines.push(`## ${categoryLabel(c)}`);
    for (const f of xs) lines.push(`${f.id} ${f.descriptors.durationClass}${f.useCases.length ? ` ${f.useCases.join(",")}` : ""}`);
  }
  return lines.join("\n") + "\n";
}

