343	function Hud({ c, img, palette, L }: { c: { x: number; y: number } | null; img: Raster; palette: Record<string, string>; L: Layers }) {
344	  if (!c) return <><span>x –</span><span>y –</span></>;
345	  const o = (c.y * img.size + c.x) * 4;
346	  const h = img.px[o + 3] ? "#" + [0, 1, 2].map((j) => img.px[o + j].toString(16).padStart(2, "0")).join("") : null;
347	  const key = h ? Object.entries(palette).find(([, v]) => v === h)?.[0] ?? (L.paint[o + 3] ? "paint" : "derived") : "clear";
348	  return <><span>x {String(c.x).padStart(2, "0")}</span><span>y {String(c.y).padStart(2, "0")}</span>{h && <><span className="sw" style={{ background: h }} /><span>{h}</span></>}<span style={{ color: "var(--muted)" }}>{key}</span></>;
349	}
