351	function Splitter({ cvRef, stageRef, n, zoom, pan, splitX, setSplitX, show }: { cvRef: React.RefObject<HTMLCanvasElement | null>; stageRef: React.RefObject<HTMLDivElement | null>; n: number; zoom: number; pan: { x: number; y: number }; splitX: number; setSplitX: (v: number) => void; show: boolean }) {
352	  const [box, setBox] = useState<{ left: number; top: number; h: number } | null>(null);
353	  const drag = useRef(false);
354	  useEffect(() => {
355	    const cv = cvRef.current, st = stageRef.current;
356	    if (!cv || !st) return;
357	    const r = cv.getBoundingClientRect(), s = st.getBoundingClientRect();
358	    setBox({ left: r.left - s.left + Math.round(splitX * n) * zoom, top: r.top - s.top, h: n * zoom });
359	  }, [cvRef, stageRef, n, zoom, pan, splitX]);
360	  if (!show || !box) return null;
361	  return (
362	    <div className="tx-split" style={{ left: box.left, top: box.top, height: box.h }} role="slider" aria-label="Compare split" aria-valuenow={Math.round(splitX * 100)} aria-valuemin={0} aria-valuemax={100} tabIndex={0}
363	      onKeyDown={(e) => { if (e.key === "ArrowLeft") setSplitX(Math.max(0, splitX - 1 / n)); if (e.key === "ArrowRight") setSplitX(Math.min(1, splitX + 1 / n)); }}
364	      onPointerDown={(e) => { drag.current = true; (e.target as HTMLElement).setPointerCapture(e.pointerId); }}
365	      onPointerMove={(e) => { if (!drag.current || !cvRef.current) return; const r = cvRef.current.getBoundingClientRect(); setSplitX(Math.max(0, Math.min(1, (e.clientX - r.left) / r.width))); }}
366	      onPointerUp={() => { drag.current = false; }}>
367	      <span className="b">Current</span><span className="a">Candidate</span>
368	    </div>
369	  );
370	}
