406	function TileCanvas({ r }: { r: Raster }) {
407	  const ref = useRef<HTMLCanvasElement>(null);
408	  useEffect(() => {
409	    const c = ref.current; if (!c) return;
410	    const n = r.size; c.width = n * 3; c.height = n * 3;
