// Waveform PEAKS (Cyrus Sound Studio, R1b): tiny amplitude envelopes for drawing, never audio. Pure, client-safe.
//   peaksOf(pcm, n)    max |sample| per bucket (0..1)
//   encodePeaks / decodePeaks   one base-36 character per bucket on a 48 dB log scale (0 = -48 dBFS or less, z = 0 dBFS)
//   peakDiff(a, b)     per-bucket change between two renders (the History tab's waveform diff)
// The library's peaks (library-peaks.json, generated on node-2 by scripts/cyrus/sound-peaks.ts) are 64 numbers per
// file: a coarse loudness outline with no phase, pitch or timbre, from which the sound cannot be rebuilt. That is
// metadata like the manifest's duration and LUFS, not a copy of the file (DOCUMENTATION.md "Cyrus sound studio UI").
export const PEAK_BUCKETS = 64;
const ALPHA = "0123456789abcdefghijklmnopqrstuvwxyz";
const FLOOR_DB = -48;

export function peaksOf(pcm: ArrayLike<number>, buckets = PEAK_BUCKETS): number[] {
  const n = Math.max(1, Math.floor(buckets));
  const out = new Array<number>(n).fill(0);
  if (!pcm.length) return out;
  for (let b = 0; b < n; b++) {
    const a = Math.floor((b / n) * pcm.length), z = Math.max(a + 1, Math.floor(((b + 1) / n) * pcm.length));
    let m = 0;
    for (let i = a; i < z && i < pcm.length; i++) { const v = Math.abs(pcm[i]); if (v > m) m = v; }
    out[b] = Math.round(Math.min(1, m) * 1000) / 1000;
  }
  return out;
}

export function encodePeaks(peaks: readonly number[]): string {
  return peaks.map((p) => {
    const db = p > 0 ? 20 * Math.log10(p) : FLOOR_DB;
    return ALPHA[Math.max(0, Math.min(35, Math.round(((db - FLOOR_DB) / -FLOOR_DB) * 35)))];
  }).join("");
}

export function decodePeaks(s: string): number[] {
  return [...s].map((ch) => {
    const k = ALPHA.indexOf(ch);
    return k <= 0 ? 0 : Math.round(Math.pow(10, (FLOOR_DB + (k / 35) * -FLOOR_DB) / 20) * 1000) / 1000;
  });
}

/** Per bucket: the two levels and whether they differ audibly (> 3 dB, or one side silent). Resamples b to a's length. */
export function peakDiff(a: readonly number[], b: readonly number[]): { a: number; b: number; changed: boolean }[] {
  const n = a.length;
  const at = (xs: readonly number[], i: number) => (xs.length ? xs[Math.min(xs.length - 1, Math.floor((i / n) * xs.length))] : 0);
  return a.map((x, i) => {
    const y = at(b, i);
    const dx = x > 0.004 ? 20 * Math.log10(x) : -48, dy = y > 0.004 ? 20 * Math.log10(y) : -48;
    return { a: x, b: y, changed: Math.abs(dx - dy) > 3 };
  });
}
EOF
cat > /tank/dev-worktrees/cyrus-r9/scripts/cyrus/sound-peaks.ts <<'EOF'
// Cyrus Sound Studio (R1b): derive the library's waveform PEAKS (64 levels per file, lib/cyrus/sound/peaks.ts) ON
// node-2, where the audio lives. Writes lib/cyrus/sound/library-peaks.json (metadata only: no audio, no file names).
//   devhost run -- npx tsx scripts/cyrus/sound-peaks.ts            (then devhost pull lib/cyrus/sound/library-peaks.json)
// Decodes with the isolated ffmpeg (argv, file protocol only) and checks every file's sha256 against the manifest.
import { createHash } from "node:crypto";
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import path from "node:path";
import { decodeFile } from "../../lib/cyrus/sound/runner";
import { librarySounds, soundManifest } from "../../lib/cyrus/sound/library";
import { encodePeaks, peaksOf, PEAK_BUCKETS } from "../../lib/cyrus/sound/peaks";
import { SOUND_FFMPEG_DIR, SOUND_LIBRARY_DIR } from "../../lib/cyrus/sound/host";

const lib = process.env.CYRUS_SOUND_LIBRARY_DIR || SOUND_LIBRARY_DIR, ffd = process.env.CYRUS_SOUND_FFMPEG_DIR || SOUND_FFMPEG_DIR;
if (!existsSync(lib)) { console.error(`no library at ${lib}: run this on the render host (node-2)`); process.exit(2); }
const ff = { ffmpeg: path.join(ffd, "ffmpeg"), ffprobe: path.join(ffd, "ffprobe") };
const peaks: Record<string, string> = {};
let n = 0;
for (const s of [...librarySounds()].sort((a, b) => (a.id < b.id ? -1 : 1))) {
  const file = path.join(lib, s.file);
  const bytes = readFileSync(file);
  if (createHash("sha256").update(bytes).digest("hex") !== s.sha256) throw new Error(`sha256 mismatch for ${s.id}`);
  peaks[s.id] = encodePeaks(peaksOf(decodeFile(ff, file, s.channels), PEAK_BUCKETS));
  if (++n % 50 === 0) console.error(`${n} files`);
}
const out = { version: 1, buckets: PEAK_BUCKETS, scale: "one base-36 char per bucket, 48 dB log scale (lib/cyrus/sound/peaks.ts)", libraryZipSha256: soundManifest().source.zipSha256, generatedAt: new Date().toISOString().slice(0, 10), peaks };
writeFileSync(path.join(process.cwd(), "lib/cyrus/sound/library-peaks.json"), JSON.stringify(out, null, 0) + "\n");
console.error(`wrote ${n} peak strings`);
EOF
