// Cyrus SOUND STUDIO (R1b): the pure editing model. Client-safe (no manifest, no Node): the editor's state is a
// SoundSpec v1 (lib/cyrus/sound/spec.ts), edited non-destructively here; the server validates it again with
// checkSoundSpec on save (same rules as builds). Everything in this file is unit-tested (test/cyrus-sound-studio.test.ts).
//
// Draft rules: an event may have 0 variants while editing ("not used yet"), a subtitle may be empty; saveBlockers()
// lists what must be fixed before a save, with the same wording the validator would use.
import { canAsset } from "../engine-core/asset-gate";
import { MAX_LAYERS, MAX_VARIANTS, MAX_EVENTS_PER_SET, ROLE_PROFILE, SOUND_CATEGORIES, type SoundCategory, type SoundEvent, type SoundLayer, type SoundProcessing, type SoundRole, type SoundSpec, type SoundVariant, type SynthPreset } from "../sound/spec";
import { SYNTH_PARAMS } from "../sound/synth-params";

export const SOUND_DOC_MIME = "application/vnd.nxeon.sound-doc+json";
/** What happened to a Cyrus candidate (recorded on the revision that decided it). */
export type SoundDecision = { candidate: string; event: string; accepted: boolean; mode: "replace_event" | "replace_variant" | "add_variant" | "reject" };
/** A studio sound set as stored: the spec (the recipe; audio is a build artifact) + bookkeeping. */
export type SoundDoc = { v: 1; spec: SoundSpec; supersedes?: string[]; decision?: SoundDecision };

const r3 = (v: number) => Math.round(v * 1000) / 1000;
const cl = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
const clone = <T,>(v: T): T => JSON.parse(JSON.stringify(v)) as T;

// ---------------------------------------------------------------------------- event slots

export type SetKind = "mob" | "item" | "other";
/** The standard event slots the left list offers per kind of set (unused ones show as "Not used · add a sound"). */
export const SLOTS: Record<SetKind, { event: string; role: SoundRole }[]> = {
  mob: [{ event: "ambient", role: "ambient" }, { event: "hurt", role: "hurt" }, { event: "death", role: "death" }, { event: "attack", role: "attack" }, { event: "step", role: "step" }, { event: "spawn", role: "spawn" }],
  item: [{ event: "fire", role: "fire" }, { event: "reload", role: "reload" }],
  other: [],
};
const ITEM_ROLES = new Set<SoundRole>(["fire", "reload"]);

/** mob / item / other, from the roles used (fire/reload = an item) or a texture of the same name (an item). */
export function setKindOf(spec: SoundSpec, textureKeys: readonly string[] = []): SetKind {
  if (spec.events.some((e) => ITEM_ROLES.has(e.role)) || textureKeys.includes(spec.name)) return "item";
  if (spec.events.some((e) => ["ambient", "hurt", "death", "attack", "step", "spawn"].includes(e.role))) return "mob";
  return "other";
}

export type Slot = { event: string; role: SoundRole; index: number | null };
/** The set's events in spec order, then the standard slots it does not use yet. */
export function slotsFor(spec: SoundSpec, kind: SetKind): Slot[] {
  const used: Slot[] = spec.events.map((e, i) => ({ event: e.event, role: e.role, index: i }));
  if (spec.events.length >= MAX_EVENTS_PER_SET) return used;
  return [...used, ...SLOTS[kind].filter((s) => !spec.events.some((e) => e.event === s.event)).map((s) => ({ ...s, index: null }))];
}

// ---------------------------------------------------------------------------- subtitles + save blockers

/** null = fine. Mirrors checkSoundSpec's subtitle rule (3-60 characters of plain text). */
export function subtitleProblem(s: string): string | null {
  if (!s.trim()) return "Required. Every Cyrus sound ships with a subtitle; this event can't be saved without one.";
  if (s.trim().length < 3) return "Too short: write at least 3 characters (what a player with subtitles on should read).";
  if (s.length > 60) return "Too long: 60 characters at most.";
  if (/[\u0000-\u001f<>§]/.test(s)) return "Plain text only: no < > § or control characters.";
  return null;
}

export type Blocker = { event: string; message: string };
/** Why this draft cannot be saved yet (empty = it can be sent; the server validates everything again). */
export function saveBlockers(spec: SoundSpec): Blocker[] {
  const out: Blocker[] = [];
  if (!spec.events.length) out.push({ event: "", message: "This set has no events. Add a sound to at least one event." });
  for (const e of spec.events) {
    const sp = subtitleProblem(e.subtitle);
    if (sp) out.push({ event: e.event, message: `${e.event}: subtitle ${sp.charAt(0).toLowerCase()}${sp.slice(1)}` });
    if (!e.variants.length) out.push({ event: e.event, message: `${e.event} has no sound yet: add a layer, or remove the event.` });
    e.variants.forEach((v, i) => {
      if (!v.layers.length || v.layers.every((l) => l.source === "silence")) out.push({ event: e.event, message: `${e.event} V${i + 1} needs at least one layer that is not silence.` });
    });
  }
  return out;
}

/** The validator's paths ("events[2].variants[0].layers[1]") in the studio's words ("death V1 layer 2"). */
export function humanSpecError(error: string, spec: Pick<SoundSpec, "events">): string {
  return error
    .replace(/events\[(\d+)\]/g, (_, i) => spec.events[Number(i)]?.event ?? `event ${Number(i) + 1}`)
    .replace(/\.variants\[(\d+)\]/g, (_, i) => ` V${Number(i) + 1}`)
    .replace(/\.layers\[(\d+)\]/g, (_, i) => ` layer ${Number(i) + 1}`)
    .replace(/\.(subtitle|source|processing|length|gain|pitch|start|trimStart|fadeIn|fadeOut|seed|params|weight)\b/g, " $1");
}

// ---------------------------------------------------------------------------- layers

export type LayerKind = "lib" | "synth" | "silence";
export const layerKind = (l: Pick<SoundLayer, "source">): LayerKind => (l.source === "silence" ? "silence" : l.source.startsWith("synth:") ? "synth" : "lib");
export const libIdOf = (l: Pick<SoundLayer, "source">) => (l.source.startsWith("lib:") ? l.source.slice(4) : null);
const BASE: SoundLayer = { source: "silence", start: 0, gain: 0, pitch: 0, trimStart: 0, length: null, fadeIn: 0, fadeOut: 0, seed: 1, params: {} };

/** A new synth layer with the preset's documented defaults (params left out = defaults, as the validator expects). */
export function synthLayer(preset: SynthPreset, o: Partial<SoundLayer> = {}): SoundLayer {
  return clampLayer({ ...BASE, source: `synth:${preset}`, length: 0.6, fadeOut: 80, ...o });
}
export const silenceLayer = (length = 0.2, start = 0): SoundLayer => clampLayer({ ...BASE, source: "silence", length, start });
/** A library layer exactly as lib/cyrus/library/use-in-project soundLayerFrom builds it (pitch -1: never shipped unchanged). */
export const libraryLayer = (id: string, o: Partial<SoundLayer> = {}): SoundLayer => clampLayer({ ...BASE, source: `lib:${id}`, pitch: -1, ...o });

/** Clamp every field to the validator's range (sliders and drags can never produce an invalid layer). */
export function clampLayer(l: SoundLayer): SoundLayer {
  const k = layerKind(l);
  const out: SoundLayer = {
    source: l.source, start: r3(cl(l.start, 0, 5)), gain: Math.round(cl(l.gain, -40, 12) * 2) / 2, pitch: Math.round(cl(l.pitch, -24, 24)),
    trimStart: k === "lib" ? r3(cl(l.trimStart, 0, 60)) : 0, length: l.length == null ? (k === "lib" ? null : 0.2) : r3(cl(l.length, 0.01, 8)),
    fadeIn: Math.round(cl(l.fadeIn, 0, 2000)), fadeOut: Math.round(cl(l.fadeOut, 0, 4000)), seed: k === "synth" ? Math.round(cl(l.seed, 0, 2147483647)) : 1, params: {},
  };
  if (k === "synth") {
    const defs = SYNTH_PARAMS[l.source.slice(6) as SynthPreset] ?? {};
    for (const [p, v] of Object.entries(l.params ?? {})) if (defs[p]) out.params[p] = Math.round(cl(v, defs[p].min, defs[p].max) * 1000) / 1000;
  }
  return out;
}

/** Seconds of SOURCE material a layer uses (before pitch). Library layers without a length run to the file's end. */
export function layerSourceSeconds(l: SoundLayer, libDuration: number | null): number {
  if (l.length != null) return libIdOf(l) && libDuration != null ? Math.max(0.01, Math.min(l.length, libDuration - l.trimStart)) : l.length;
  return Math.max(0.01, (libDuration ?? 1) - l.trimStart);
}
/** Where a layer sits on the variant's timeline (after pitch: pitching up shortens it, like Minecraft's pitch). */
export function layerSpan(l: SoundLayer, libDuration: number | null) {
  const k = Math.pow(2, l.pitch / 12);
  const dur = layerSourceSeconds(l, libDuration) / k;
  return { start: l.start, end: l.start + dur, dur, fadeIn: Math.min(dur, l.fadeIn / 1000), fadeOut: Math.min(dur, l.fadeOut / 1000) };
}
/** The end of the last layer (the waveform's natural width before the render's tails). */
export function variantSpan(v: SoundVariant, durOf: (id: string) => number | null): number {
  return v.layers.reduce((m, l) => Math.max(m, layerSpan(l, libIdOf(l) ? durOf(libIdOf(l)!) : null).end), 0);
}

export type Handle = "move" | "trimStart" | "end" | "fadeIn" | "fadeOut" | "gain";
/**
 * One drag on the waveform, from the layer as it was when the drag started. `ds` = seconds moved on the timeline,
 * `dGainDb` = vertical gain change (the gain handle only). Trimming the start of a library layer moves the in-point
 * (trimStart) and keeps the rest where it was; on a synth/silence layer it shortens it from the left.
 */
export function dragLayer(o: SoundLayer, h: Handle, ds: number, libDuration: number | null, dGainDb = 0): SoundLayer {
  const k = Math.pow(2, o.pitch / 12);
  const len0 = layerSourceSeconds(o, libDuration);
  const l = { ...o };
  if (h === "move") l.start = o.start + ds;
  else if (h === "end") l.length = Math.min(len0 + ds * k, libDuration != null && libIdOf(o) ? libDuration - o.trimStart : 8);
  else if (h === "trimStart") {
    if (libIdOf(o)) { const d = cl(ds * k, -o.trimStart, len0 - 0.02); l.trimStart = o.trimStart + d; l.length = len0 - d; l.start = o.start + d / k; }
    else { const d = cl(ds, -o.start, len0 / k - 0.02); l.start = o.start + d; l.length = len0 - d * k; }
  } else if (h === "fadeIn") l.fadeIn = o.fadeIn + ds * 1000;
  else if (h === "fadeOut") l.fadeOut = o.fadeOut - ds * 1000;
  else if (h === "gain") l.gain = o.gain + dGainDb;
  const c = clampLayer(l);
  const span = (c.length ?? len0) / Math.pow(2, c.pitch / 12) * 1000;
  if (c.fadeIn + c.fadeOut > span) { if (h === "fadeIn") c.fadeIn = Math.max(0, Math.round(span - c.fadeOut)); else c.fadeOut = Math.max(0, Math.round(span - c.fadeIn)); }
  return c;
}

/** Which handle is under (x, y) for the selected layer. `px` maps seconds to pixels; `topY` = the fade-handle row. */
export function hitHandle(span: ReturnType<typeof layerSpan>, px: (s: number) => number, x: number, y: number, o: { fadeRowY: number; gainY: number; tol?: number }): Handle | null {
  const t = o.tol ?? 7;
  const x0 = px(span.start), x1 = px(span.end), fi = px(span.start + span.fadeIn), fo = px(span.end - span.fadeOut);
  if (Math.abs(y - o.gainY) < 9) { if (Math.abs(x - fi) < t + 2) return "fadeIn"; if (Math.abs(x - fo) < t + 2) return "fadeOut"; }
  if (Math.abs(x - x0) < t) return "trimStart";
  if (Math.abs(x - x1) < t) return "end";
  if (x > fi + t && x < fo - t && Math.abs(y - o.gainY) < 6) return "gain";
  if (x > x0 && x < x1) return "move";
  return null;
}

// ---------------------------------------------------------------------------- immutable spec edits

type At = { e: number; v?: number; l?: number };
function at(spec: SoundSpec, a: At) {
  const s = clone(spec);
  const e = s.events[a.e];
  if (!e) throw new Error("no such event");
  return { s, e, v: a.v != null ? e.variants[a.v] : undefined };
}
export type EditResult = { ok: true; spec: SoundSpec; index?: number } | { ok: false; error: string };

export function addLayer(spec: SoundSpec, ei: number, vi: number, layer: SoundLayer): EditResult {
  const { s, e } = at(spec, { e: ei });
  if (!e.variants.length) e.variants.push({ weight: 1, layers: [], processing: { lowpass: null, highpass: null, reverb: 0, echo: null } });
  const v = e.variants[Math.min(vi, e.variants.length - 1)];
  if (v.layers.length >= MAX_LAYERS) return { ok: false, error: `Four layers per variant is the limit.` };
  v.layers.push(clampLayer(layer));
  return { ok: true, spec: s, index: v.layers.length - 1 };
}
export function setLayer(spec: SoundSpec, ei: number, vi: number, li: number, patch: Partial<SoundLayer>): SoundSpec {
  const { s, v } = at(spec, { e: ei, v: vi });
  if (!v || !v.layers[li]) return spec;
  v.layers[li] = clampLayer({ ...v.layers[li], ...patch, params: patch.params ? { ...v.layers[li].params, ...patch.params } : v.layers[li].params });
  return s;
}
export function removeLayer(spec: SoundSpec, ei: number, vi: number, li: number): SoundSpec {
  const { s, v } = at(spec, { e: ei, v: vi });
  if (!v) return spec;
  v.layers.splice(li, 1);
  return s;
}
export function setProcessing(spec: SoundSpec, ei: number, vi: number, patch: Partial<SoundProcessing>): SoundSpec {
  const { s, v } = at(spec, { e: ei, v: vi });
  if (!v) return spec;
  const p = { ...v.processing, ...patch };
  v.processing = {
    lowpass: p.lowpass == null || p.lowpass >= 20000 ? null : Math.round(cl(p.lowpass, 200, 19999)),
    highpass: p.highpass == null || p.highpass <= 20 ? null : Math.round(cl(p.highpass, 21, 5000)),
    reverb: Math.round(cl(p.reverb, 0, 1) * 100) / 100,
    echo: p.echo == null || p.echo.delay < 20 ? null : { delay: Math.round(cl(p.echo.delay, 20, 1000)), feedback: Math.round(cl(p.echo.feedback, 0, 0.7) * 100) / 100, mix: Math.round(cl(p.echo.mix, 0, 1) * 100) / 100 },
  };
  return s;
}
/** A copy of variant `from` with new synth seeds, so players hear a different take. */
export function addVariant(spec: SoundSpec, ei: number, from: number): EditResult {
  const { s, e } = at(spec, { e: ei });
  if (e.variants.length >= MAX_VARIANTS) return { ok: false, error: "Four variants per event is the limit." };
  const src = e.variants[from] ?? e.variants[0];
  const copy: SoundVariant = src ? clone(src) : { weight: 1, layers: [], processing: { lowpass: null, highpass: null, reverb: 0, echo: null } };
  copy.weight = 1;
  for (const l of copy.layers) if (layerKind(l) === "synth") l.seed = (l.seed + 13) % 2147483647;
  e.variants.push(copy);
  return { ok: true, spec: s, index: e.variants.length - 1 };
}
export function removeVariant(spec: SoundSpec, ei: number, vi: number): SoundSpec {
  const { s, e } = at(spec, { e: ei });
  e.variants.splice(vi, 1);
  return s;
}
export function setWeight(spec: SoundSpec, ei: number, vi: number, weight: number): SoundSpec {
  const { s, v } = at(spec, { e: ei, v: vi });
  if (v) v.weight = Math.round(cl(weight, 1, 10));
  return s;
}
export function setSubtitle(spec: SoundSpec, ei: number, subtitle: string): SoundSpec {
  const { s, e } = at(spec, { e: ei });
  e.subtitle = subtitle.slice(0, 80);
  return s;
}
export function setCategory(spec: SoundSpec, ei: number, category: SoundCategory): SoundSpec {
  const { s, e } = at(spec, { e: ei });
  if ((SOUND_CATEGORIES as readonly string[]).includes(category)) e.category = category;
  return s;
}
const DEFAULT_CATEGORY: Record<SoundRole, SoundCategory> = { ambient: "hostile", hurt: "hostile", death: "hostile", attack: "hostile", step: "hostile", ability: "player", fire: "player", reload: "player", spawn: "hostile", ui: "master", other: "neutral" };
/** A new (still empty) event for an unused slot; it needs a sound and a subtitle before it can be saved. */
export function addEvent(spec: SoundSpec, event: string, role: SoundRole, category?: SoundCategory): EditResult {
  if (spec.events.length >= MAX_EVENTS_PER_SET) return { ok: false, error: `A sound set has at most ${MAX_EVENTS_PER_SET} events.` };
  if (spec.events.some((e) => e.event === event)) return { ok: false, error: `${event} is already in this set.` };
  if (!/^[a-z][a-z0-9_]{0,23}$/.test(event)) return { ok: false, error: "Event names are 1-24 lowercase letters, digits and underscores." };
  const s = clone(spec);
  s.events.push({ event, role, category: category ?? DEFAULT_CATEGORY[role], subtitle: "", variants: [] });
  return { ok: true, spec: s, index: s.events.length - 1 };
}
export function removeEvent(spec: SoundSpec, ei: number): SoundSpec {
  const s = clone(spec);
  s.events.splice(ei, 1);
  return s;
}

/** "players hear V1 67% · V2 33%" */
export const odds = (e: Pick<SoundEvent, "variants">) => {
  const tot = e.variants.reduce((a, v) => a + v.weight, 0) || 1;
  return e.variants.map((v) => Math.round((v.weight / tot) * 100));
};

/** Apply a Cyrus candidate (the candidate's version of the event) in one of the A/B panel's ways. */
export function applyCandidate(spec: SoundSpec, ei: number, cand: SoundEvent, mode: "replace_event" | "replace_variant" | "add_variant", variant = 0): EditResult {
  const { s, e } = at(spec, { e: ei });
  const first = cand.variants[0];
  if (!first) return { ok: false, error: "The candidate has no sound." };
  if (mode === "replace_event") { e.variants = clone(cand.variants).slice(0, MAX_VARIANTS); if (cand.subtitle && !e.subtitle.trim()) e.subtitle = cand.subtitle; }
  else if (mode === "replace_variant") { const w = e.variants[variant]?.weight ?? 1; e.variants[Math.min(variant, Math.max(0, e.variants.length - 1))] = { ...clone(first), weight: w }; if (!e.variants.length) e.variants.push({ ...clone(first), weight: w }); }
  else { if (e.variants.length >= MAX_VARIANTS) return { ok: false, error: "Four variants per event is the limit." }; e.variants.push({ ...clone(first), weight: 1 }); }
  return { ok: true, spec: s };
}

// ---------------------------------------------------------------------------- audition (preview) helpers

/** The short processed preview the render host makes for one library layer (layer chain minus gain and offset). */
export type PreviewRequest = { libraryId: string; trimStart: number; length: number; pitch: number; fadeIn: number; fadeOut: number };
export const PREVIEW_SECONDS = 6;
export function previewRequestOf(l: SoundLayer, libDuration: number | null): PreviewRequest | null {
  const id = libIdOf(l);
  if (!id) return null;
  return { libraryId: id, trimStart: r3(l.trimStart), length: r3(Math.min(PREVIEW_SECONDS, layerSourceSeconds(l, libDuration))), pitch: l.pitch, fadeIn: l.fadeIn, fadeOut: l.fadeOut };
}
/** Plain audition of a library item from the list: its first seconds, unpitched, with a short fade-out. */
export const auditionRequest = (libraryId: string, duration: number): PreviewRequest => ({ libraryId, trimStart: 0, length: r3(Math.min(4, Math.max(0.05, duration))), pitch: 0, fadeIn: 0, fadeOut: 40 });
/** Canonical key of a preview request (client cache key; the server hashes it with the file's sha256 and versions). */
export const previewKey = (r: PreviewRequest) => `${r.libraryId}|${r.trimStart}|${r.length}|${r.pitch}|${r.fadeIn}|${r.fadeOut}`;

/**
 * The variant the BROWSER renders: each library layer is replaced by its processed preview buffer (`lib:__p<i>`, no
 * trim/pitch/fades left to apply: the host did them), or by silence of the same length when no preview is available
 * (library audition off). Gain and offset stay, so the mix lines up with the render host's.
 */
export function browserVariant(v: SoundVariant, hasPreview: (li: number) => boolean, durOf: (id: string) => number | null): { variant: SoundVariant; silenced: number } {
  let silenced = 0;
  const layers = v.layers.map((l, i) => {
    const id = libIdOf(l);
    if (!id) return l;
    if (hasPreview(i)) return { ...l, source: `lib:__p${i}`, trimStart: 0, length: null, pitch: 0, fadeIn: 0, fadeOut: 0 };
    silenced++;
    return { ...l, source: "silence", trimStart: 0, pitch: 0, length: r3(layerSpan(l, durOf(id)).dur) };
  });
  return { variant: { ...v, layers }, silenced };
}

export type AuditionDecision = { library: boolean; synth: true; reason: string | null };
/**
 * Who hears what (the server applies the same rule to the preview route): synth layers always play in the browser
 * (pure DSP, original); LIBRARY audio only when the owner cleared the licence (CYRUS_SOUND_LIBRARY_CLEARED=1) AND the
 * plan may use the sound library (Saka and up). Unknown plan = no library audio.
 */
export function auditionDecision(o: { cleared: boolean; plan: unknown }): AuditionDecision {
  if (!o.cleared) return { library: false, synth: true, reason: "Library audition is off until the owner confirms the sound licence. Synth layers play; library layers are drawn from their outline only." };
  const d = canAsset(o.plan, "sound", "create");
  if (!d.ok) return { library: false, synth: true, reason: d.reason };
  return { library: true, synth: true, reason: null };
}

/** The role's band for the meters. */
export const roleBand = (role: SoundRole) => ROLE_PROFILE[role];

