}
const DEFAULT_CATEGORY: Record<SoundRole, SoundCategory> = { ambient: "hostile", hurt: "hostile", death: "hostile", attack: "hostile", step: "hostile", ability: "player", fire: "player", reload: "player", spawn: "hostile", ui: "master", other: "neutral" };
/** A new (still empty) event for an unused slot; it needs a sound and a subtitle before it can be saved. */
export function addEvent(spec: SoundSpec, event: string, role: SoundRole, category?: SoundCategory): EditResult {
  if (spec.events.length >= MAX_EVENTS_PER_SET) return { ok: false, error: `A sound set has at most ${MAX_EVENTS_PER_SET} events.` };
  if (spec.events.some((e) => e.event === event)) return { ok: false, error: `${event} is already in this set.` };
  if (!/^[a-z][a-z0-9_]{0,23}$/.test(event)) return { ok: false, error: "Event names are 1-24 lowercase letters, digits and underscores." };
  const s = clone(spec);
