}
export function removeEvent(spec: SoundSpec, ei: number): SoundSpec {
  const s = clone(spec);
  s.events.splice(ei, 1);
  return s;
}

/** "players hear V1 67% · V2 33%" */
export const odds = (e: Pick<SoundEvent, "variants">) => {
  const tot = e.variants.reduce((a, v) => a + v.weight, 0) || 1;
  return e.variants.map((v) => Math.round((v.weight / tot) * 100));
};

/** Apply a Cyrus candidate (the candidate's version of the event) in one of the A/B panel's ways. */
export function applyCandidate(spec: SoundSpec, ei: number, cand: SoundEvent, mode: "replace_event" | "replace_variant" | "add_variant", variant = 0): EditResult {
  const { s, e } = at(spec, { e: ei });
  const first = cand.variants[0];
  if (!first) return { ok: false, error: "The candidate has no sound." };
  if (mode === "replace_event") { e.variants = clone(cand.variants).slice(0, MAX_VARIANTS); if (cand.subtitle && !e.subtitle.trim()) e.subtitle = cand.subtitle; }
  else if (mode === "replace_variant") { const w = e.variants[variant]?.weight ?? 1; e.variants[Math.min(variant, Math.max(0, e.variants.length - 1))] = { ...clone(first), weight: w }; if (!e.variants.length) e.variants.push({ ...clone(first), weight: w }); }
  else { if (e.variants.length >= MAX_VARIANTS) return { ok: false, error: "Four variants per event is the limit." }; e.variants.push({ ...clone(first), weight: 1 }); }
  return { ok: true, spec: s };
}

// ---------------------------------------------------------------------------- audition (preview) helpers

/** The short processed preview the render host makes for one library layer (layer chain minus gain and offset). */
export type PreviewRequest = { libraryId: string; trimStart: number; length: number; pitch: number; fadeIn: number; fadeOut: number };
export const PREVIEW_SECONDS = 6;
export function previewRequestOf(l: SoundLayer, libDuration: number | null): PreviewRequest | null {
  const id = libIdOf(l);
  if (!id) return null;
  return { libraryId: id, trimStart: r3(l.trimStart), length: r3(Math.min(PREVIEW_SECONDS, layerSourceSeconds(l, libDuration))), pitch: l.pitch, fadeIn: l.fadeIn, fadeOut: l.fadeOut };
}
/** Plain audition of a library item from the list: its first seconds, unpitched, with a short fade-out. */
export const auditionRequest = (libraryId: string, duration: number): PreviewRequest => ({ libraryId, trimStart: 0, length: r3(Math.min(4, Math.max(0.05, duration))), pitch: 0, fadeIn: 0, fadeOut: 40 });
/** Canonical key of a preview request (client cache key; the server hashes it with the file's sha256 and versions). */
export const previewKey = (r: PreviewRequest) => `${r.libraryId}|${r.trimStart}|${r.length}|${r.pitch}|${r.fadeIn}|${r.fadeOut}`;

/**
 * The variant the BROWSER renders: each library layer is replaced by its processed preview buffer (`lib:__p<i>`, no
 * trim/pitch/fades left to apply: the host did them), or by silence of the same length when no preview is available
 * (library audition off). Gain and offset stay, so the mix lines up with the render host's.
 */
export function browserVariant(v: SoundVariant, hasPreview: (li: number) => boolean, durOf: (id: string) => number | null): { variant: SoundVariant; silenced: number } {
  let silenced = 0;
  const layers = v.layers.map((l, i) => {
    const id = libIdOf(l);
    if (!id) return l;
    if (hasPreview(i)) return { ...l, source: `lib:__p${i}`, trimStart: 0, length: null, pitch: 0, fadeIn: 0, fadeOut: 0 };
    silenced++;
    return { ...l, source: "silence", trimStart: 0, pitch: 0, length: r3(layerSpan(l, durOf(id)).dur) };
  });
  return { variant: { ...v, layers }, silenced };
}

export type AuditionDecision = { library: boolean; synth: true; reason: string | null };
/**
 * Who hears what (the server applies the same rule to the preview route): synth layers always play in the browser
 * (pure DSP, original); LIBRARY audio only when the owner cleared the licence (CYRUS_SOUND_LIBRARY_CLEARED=1) AND the
 * plan may use the sound library (Saka and up). Unknown plan = no library audio.
 */
export function auditionDecision(o: { cleared: boolean; plan: unknown }): AuditionDecision {
  if (!o.cleared) return { library: false, synth: true, reason: "Library audition is off until the owner confirms the sound licence. Synth layers play; library layers are drawn from their outline only." };
  const d = canAsset(o.plan, "sound", "create");
  if (!d.ok) return { library: false, synth: true, reason: d.reason };
  return { library: true, synth: true, reason: null };
}

/** The role's band for the meters. */
export const roleBand = (role: SoundRole) => ROLE_PROFILE[role];

