// Cyrus Sound Studio (R1b): how a project's sound sets are read from its asset rows. SERVER side (it validates with
// the library catalog), no I/O. A set = the newest CyrusProjectAsset row (kind "sound") for its key that is not an
// undecided Cyrus candidate. Build rows hold the generated spec (mime sound-spec); studio rows hold a SoundDoc (spec +
// supersedes + decision, mime sound-doc). Rows are append-only: a save is a NEW revision + a new row.
import { checkSoundSpec, type SoundSpec } from "../sound/spec";
import { libraryCatalogDurations } from "../sound/library";
import { canonicalJson, sha256Hex } from "../assets/textures";
import { SOUND_DOC_MIME, type SoundDecision, type SoundDoc } from "./sound-edit";
import type { AssetRow } from "./service";

let CATALOG: Record<string, number> | null = null;
export const soundCatalog = () => (CATALOG ??= libraryCatalogDurations());
const ts = (d: Date | string) => new Date(d).getTime();
const obj = (v: unknown): Record<string, unknown> => (v && typeof v === "object" && !Array.isArray(v) ? (v as Record<string, unknown>) : {});

/** Normalise a stored spec (library allowed here: what is IN a project is always viewable; saving re-checks the licence). */
export function storedSpec(raw: unknown): SoundSpec | null {
  const c = checkSoundSpec(raw, { catalog: soundCatalog(), library: true });
  return c.ok ? c.spec : null;
}
export const specSha = (spec: SoundSpec) => sha256Hex(canonicalJson(spec));
export const soundDocSha = (doc: SoundDoc) => { const canonical = canonicalJson(doc); return { canonical, sha256: sha256Hex(canonical) }; };

export function docOfSoundRow(row: AssetRow): SoundDoc | null {
  if (row.kind !== "sound") return null;
  const p = obj(row.provenance);
  if (row.mime === SOUND_DOC_MIME) {
    const d = obj(p.doc);
    const spec = storedSpec(d.spec);
    if (!spec) return null;
    const sup = Array.isArray(d.supersedes) ? d.supersedes.filter((x): x is string => typeof x === "string" && /^[0-9a-f]{64}$/.test(x)) : [];
    const dec = obj(d.decision);
    const decision: SoundDecision | undefined = typeof dec.candidate === "string" && typeof dec.event === "string" ? { candidate: dec.candidate, event: dec.event, accepted: dec.accepted === true, mode: (["replace_event", "replace_variant", "add_variant", "reject"].includes(String(dec.mode)) ? dec.mode : "reject") as SoundDecision["mode"] } : undefined;
    return { v: 1, spec, ...(sup.length ? { supersedes: sup } : {}), ...(decision ? { decision } : {}) };
  }
  const spec = storedSpec(p.spec);
  // a generated spec supersedes itself: a later build that returns it unchanged keeps any studio edit on top
  return spec ? { v: 1, spec, supersedes: [row.sha256] } : null;
}

/** What the render host reported for a build row (per event: files with their measurements). */
export type RenderSummary = { status: string | null; host: string | null; events: { event: string; files: { index: number; weight: number; durationS: number; measure: unknown; quality: unknown }[] }[] };
function renderOf(row: AssetRow): RenderSummary | null {
  const p = obj(row.provenance);
  if (!Array.isArray(p.events) && !p.render) return null;
  const events = (Array.isArray(p.events) ? p.events : []).map((e) => {
    const x = obj(e);
    return { event: String(x.event ?? ""), files: (Array.isArray(x.files) ? x.files : []).slice(0, 4).map((f) => { const y = obj(f); return { index: Number(y.index) || 0, weight: Number(y.weight) || 1, durationS: Number(y.durationS) || 0, measure: y.measure ?? null, quality: y.quality ?? null }; }) };
  });
  return { status: typeof p.render === "string" ? p.render : null, host: typeof p.renderHost === "string" ? p.renderHost : null, events };
}

const ORIGIN_LABEL: Record<string, string> = { generated: "Generated by Cyrus", edited: "Edited in Sound Studio", library: "From the Sound Library", imported: "Imported" };
function labelOf(row: AssetRow, doc: SoundDoc): string {
  const p = obj(row.provenance);
  if (doc.decision && !doc.decision.accepted) return `Kept ${doc.decision.event} (Cyrus candidate rejected)`;
  if (doc.decision?.accepted) return doc.decision.mode === "add_variant" ? `Added a Cyrus variant to ${doc.decision.event}` : doc.decision.mode === "replace_variant" ? `Replaced a ${doc.decision.event} variant with Cyrus's` : `Accepted Cyrus's ${doc.decision.event}`;
  if (p.keptStudioEdit) return "Studio edits kept by a build";
  if (row.origin === "generated" && p.kept) return "Kept unchanged by a build";
  return ORIGIN_LABEL[row.origin] ?? row.origin;
}

export type SoundSetEntry = {
  set: string; assetId: string; origin: string; revisionId: string; createdAt: string;
  spec: SoundSpec; specSha256: string; render: RenderSummary | null;
  history: { assetId: string; origin: string; revisionId: string; createdAt: string; spec: SoundSpec; label: string; decision: SoundDecision | null; render: RenderSummary | null }[];
  /** open Cyrus candidates for this set: the candidate build's version of ONE event */
  candidates: { buildId: string; assetId: string; createdAt: string; event: string; spec: SoundSpec; specSha256: string }[];
};

/**
 * Pure: each set's current spec, its history and its open candidates. `cands` = Sound Studio candidate builds of the
 * chain (id -> the set.event it was asked for); rows from texture candidate builds (`ignore`) are skipped.
 */
export function resolveSoundSets(rows: readonly AssetRow[], cands: ReadonlyMap<string, { set: string; event: string }>, ignore: ReadonlySet<string> = new Set()): SoundSetEntry[] {
  const bySet = new Map<string, AssetRow[]>();
  for (const r of rows) {
    if (r.kind !== "sound") continue;
    const b = String(obj(r.provenance).modBuildId ?? "");
    if (ignore.has(b)) continue;
    const c = cands.get(b);
    if (c && c.set !== r.assetKey) continue; // a candidate build's untouched other sets are not news
    bySet.set(r.assetKey, [...(bySet.get(r.assetKey) ?? []), r]);
  }
  const out: SoundSetEntry[] = [];
  for (const [set, list] of bySet) {
    list.sort((a, b) => ts(a.createdAt) - ts(b.createdAt) || (a.id < b.id ? -1 : 1));
    const docs = list.map((r) => ({ r, doc: docOfSoundRow(r) })).filter((x): x is { r: AssetRow; doc: SoundDoc } => !!x.doc);
    const candOf = (r: AssetRow) => (r.origin === "generated" ? cands.get(String(obj(r.provenance).modBuildId ?? "")) ?? null : null);
    const decided = new Set(docs.flatMap((x) => (x.doc.decision ? [x.doc.decision.candidate] : [])));
    const cur = [...docs].reverse().find((x) => !candOf(x.r));
    if (!cur) continue;
    out.push({
      set, assetId: cur.r.id, origin: cur.r.origin, revisionId: cur.r.revisionId, createdAt: new Date(cur.r.createdAt).toISOString(),
      spec: cur.doc.spec, specSha256: specSha(cur.doc.spec), render: renderOf(cur.r),
      history: docs.filter((x) => !candOf(x.r)).reverse().slice(0, 20).map((x) => ({ assetId: x.r.id, origin: x.r.origin, revisionId: x.r.revisionId, createdAt: new Date(x.r.createdAt).toISOString(), spec: x.doc.spec, label: labelOf(x.r, x.doc), decision: x.doc.decision ?? null, render: renderOf(x.r) })),
      candidates: docs.flatMap((x) => {
        const c = candOf(x.r);
        const id = String(obj(x.r.provenance).modBuildId ?? "");
        return c && !decided.has(id) ? [{ buildId: id, assetId: x.r.id, createdAt: new Date(x.r.createdAt).toISOString(), event: c.event, spec: x.doc.spec, specSha256: x.r.sha256 }] : [];
      }),
    });
  }
  const first = (s: SoundSetEntry) => ts(s.history[s.history.length - 1]?.createdAt ?? s.createdAt);
  return out.sort((a, b) => first(a) - first(b) || (a.set < b.set ? -1 : 1));
}
