// Cyrus Sound Studio (R1b): the server-side service behind /api/cyrus/assets/v1/projects/:p/sounds/** and
// /api/cyrus/assets/v1/sound/preview. Every dependency is injected (host seam): Cyrus tables through StudioStore, the
// plan through planOf, the render host through `renderHost` (node-2 over ssh, or a FAKE in dev/tests), the library
// licence flag through `libraryCleared`. No Nxeon internals here.
//
//   save      a NEW revision (kind "asset") + a new sound-doc row; never overwrites. Packs that carry sounds are rebuilt
//             by the next build (the render runs there), so a studio save reaches servers with the next build.
//   render    "Render and preview": the render host mixes the chosen event (real DSP, encoded Ogg on node-2) and
//             returns the files + measurements. Nothing is stored.
//   preview   library audition: ONE layer, processed on the render host, cached by a hash of the request + the
//             file's sha256, size-capped. Only when the library is cleared AND the plan may use it.
import { createHash } from "node:crypto";
import { canAsset, type AssetDecision } from "../engine-core/asset-gate";
import type { ManifestEntry } from "../engine-core/revisions";
