export type SoundDeps = {
  /** CYRUS_SOUND_LIBRARY_CLEARED=1: the owner confirmed the library licence */
  libraryCleared: () => boolean;
  /** the render host (OFF unless configured; a fake in dev/tests) */
  renderHost: () => RenderHostSelection;
};
export type SoundServiceDeps = StudioServiceDeps & { sound: SoundDeps };

const gateOrThrow = (d: AssetDecision) => { if (!d.ok) throw new StudioError(d.code === "bad_request" ? 400 : 403, d.code, d.reason, d.needs ? { needs: d.needs } : {}); };
const planOf = async (deps: StudioServiceDeps, userId: string) => deps.planOf(userId).catch(() => null);

export const soundCandMap = (chain: ChainInfo | null) => new Map((chain?.soundCandidateBuilds ?? []).map((b) => [b.id, { set: b.set, event: b.event }]));
export async function soundSetsOf(deps: StudioServiceDeps, projectId: string, chain: ChainInfo | null): Promise<SoundSetEntry[]> {
  return resolveSoundSets(await deps.store.assets(projectId), soundCandMap(chain), textureCandidateIds(chain));
}

async function owned(deps: StudioServiceDeps, userId: string, projectId: string): Promise<ProjectRow> {
  const p = await deps.store.project(projectId);
  if (!p || p.userId !== userId) throw new StudioError(404, "not_found", "Project not found.");
  return p;
}

/** The ledger rows of the library sounds a spec uses (who provided them, licence status: never "original"). */
export const soundLedger = (spec: SoundSpec) => libraryIdsOf(spec).map((id) => { const s = librarySound(id); return { libraryId: id, sha256: s?.sha256 ?? null, provenance: s?.ledger.provenance ?? LEDGER_PROVENANCE, licenceStatus: s?.ledger.licenceStatus ?? LEDGER_LICENCE_STATUS }; });

/** Validate a studio spec exactly like a build would (library only when cleared); errors in the studio's words. */
export function checkStudioSpec(raw: unknown, cleared: boolean): { ok: true; spec: SoundSpec; seconds: number } | { ok: false; error: string; code: string } {
  const c = checkSoundSpec(raw, { catalog: soundCatalog(), library: cleared });
  if (c.ok) return c;
  const ev = raw && typeof raw === "object" && Array.isArray((raw as SoundSpec).events) ? (raw as SoundSpec) : { events: [] };
  if (/the sound library is not available/.test(c.error)) return { ok: false, code: "library_not_cleared", error: "This sound uses a library layer, and the sound library is off until the owner confirms its licence. Replace it with a synth layer to save." };
  return { ok: false, code: /subtitle/.test(c.error) ? "subtitle_required" : "bad_spec", error: humanSpecError(c.error, ev) };
}

export type SoundSaveInput = {
  userId: string; projectId: string; set: string; spec: unknown;
  baseAssetId: string | null; expectedHeadId: string | null;
  origin?: "edited" | "library"; decision?: SoundDecision | null; alsoSupersedes?: string[]; message?: string | null;
};
export type SoundSaveResult = { revisionId: string; seq: number; assetId: string; specSha256: string; pack: { skipped: string } };

export async function saveSoundSet(deps: SoundServiceDeps, input: SoundSaveInput): Promise<SoundSaveResult> {
  gateOrThrow(canAsset(await planOf(deps, input.userId), "sound", input.origin === "library" ? "create" : "edit"));
  const project = await owned(deps, input.userId, input.projectId);
  const c = checkStudioSpec(input.spec, deps.sound.libraryCleared());
  if (!c.ok) throw new StudioError(422, c.code, c.error);
  if (c.spec.name !== input.set) throw new StudioError(400, "bad_spec", "The sound set's name must match its key.");
  const chain = project.rootBuildId ? await deps.chain(input.userId, project.rootBuildId) : null;
  const sets = await soundSetsOf(deps, project.id, chain);
  const rows = await deps.store.assets(project.id);
  const base = input.baseAssetId ? rows.find((r) => r.id === input.baseAssetId && r.kind === "sound") : null;
  if (input.baseAssetId && !base) throw new StudioError(404, "not_found", "The sound set this edit started from is not in this project.");
  if (!input.baseAssetId && sets.some((s) => s.set === input.set)) throw new StudioError(409, "exists", `This mod already has a sound set called ${input.set}.`);
  // the per-mod budgets (sets, events, seconds) over every set as it would be after this save
  const all = [...sets.filter((s) => s.set !== input.set).map((s) => s.spec), c.spec].map((spec) => checkReturnedSound({ key: spec.name, spec }, { library: true })).filter((x): x is Extract<typeof x, { ok: true }> => x.ok);
  const budget = withinBudget(all);
  if (budget.over.some((o) => o.set === input.set)) throw new StudioError(422, "budget", `Can't save: ${budget.over.find((o) => o.set === input.set)!.reason}.`);
  const baseDoc = base ? sets.find((s) => s.assetId === base.id) ?? null : null;
  const prevSup = base ? ((): string[] => { const h = sets.find((s) => s.set === input.set); return h ? [h.specSha256, ...(h.history.flatMap((x) => (x.origin === "generated" ? [specSha(x.spec)] : [])))] : []; })() : [];
  const sup = new Set<string>([...prevSup, ...(input.alsoSupersedes ?? [])]);
  if (baseDoc && base!.origin === "generated") sup.add(base!.sha256);
  const doc: SoundDoc = { v: 1, spec: c.spec, ...(sup.size ? { supersedes: [...sup].sort() } : {}), ...(input.decision ? { decision: input.decision } : {}) };
  const { canonical, sha256 } = soundDocSha(doc);
  const revs = await deps.store.revisions(project.id);
  const head = revs.length ? revs[revs.length - 1] : null;
  if (input.expectedHeadId !== undefined && (head?.id ?? null) !== input.expectedHeadId) throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
  const path = `assets/sounds/${input.set}.json`;
  const manifest: ManifestEntry[] = [...(head?.manifest ?? []).filter((e) => e.path !== path), { path, sha256, role: "asset" }];
  const d = input.decision;
  let rev: { id: string; seq: number };
  try {
    rev = await deps.store.addRevision(project.id, {
      kind: "asset", manifest, status: "passed", expectedHeadId: head?.id ?? null,
      engine: { toolchain: `cyrus-sound-studio ${RENDER_VERSION}/${SOUND_QUALITY_VERSION}` },
      message: (input.message ?? (d ? (d.accepted ? `Applied a Cyrus candidate to ${input.set}.${d.event}` : `Kept ${input.set}.${d.event} (rejected a Cyrus candidate)`) : input.origin === "library" ? `Added a library sound to ${input.set}` : `Edited ${input.set} in Sound Studio`)).slice(0, 200),
    });
  } catch (e) {
    if ((e as { code?: string }).code === "stale_head") throw new StudioError(409, "stale_head", "This mod changed since you opened it. Reload to see the latest version, then save again.");
    throw e;
  }
  const asset = await deps.store.recordAsset(project.id, {
    revisionId: rev.id, assetKey: input.set, kind: "sound", sha256, size: Buffer.byteLength(canonical), origin: input.origin ?? "edited", mime: SOUND_DOC_MIME, path,
    provenance: { generator: "cyrus-sound-studio", doc, specSha256: specSha(c.spec), basedOn: base?.id ?? null, ledger: soundLedger(c.spec), render: "next_build" },
  });
  return { revisionId: rev.id, seq: rev.seq, assetId: asset.id, specSha256: specSha(c.spec), pack: { skipped: "the next build renders the sounds and rebuilds the resource pack with them" } };
}

/** The current studio doc of one set, for lib/cyrus/assets/sync.ts (a build keeps studio edits it did not replace). */
export async function currentStudioSound(store: Pick<StudioServiceDeps["store"], "assets">, projectId: string, set: string, cands: ReadonlyMap<string, { set: string; event: string }> = new Map()) {
  const rows = await store.assets(projectId);
  const s = resolveSoundSets(rows, cands).find((x) => x.set === set);
  if (!s || (s.origin !== "edited" && s.origin !== "library")) return null;
  const row = rows.find((r) => r.id === s.assetId);
  const doc = row ? (row.provenance as { doc?: SoundDoc } | null)?.doc ?? null : null;
  if (!doc) return null;
  const full: SoundDoc = { v: 1, spec: s.spec, ...(doc.supersedes?.length ? { supersedes: doc.supersedes } : {}) };
  return { doc: full, ...soundDocSha(full) };
}

// ---------------------------------------------------------------------------- render and preview

export type RenderedVariantView = { index: number; weight: number; audio: string; mime: string; bytes: number; measure: unknown; quality: unknown; render: unknown };
export type SoundRenderView = { host: string; tool: Record<string, string>; event: string; files: RenderedVariantView[]; fake: boolean };

/** "Render and preview": the render host mixes ONE event of the draft (authoritative numbers on the encoded audio). */
export async function renderSoundEvent(deps: SoundServiceDeps, i: { userId: string; projectId: string; set: string; spec: unknown; event: string }): Promise<SoundRenderView> {
  gateOrThrow(canAsset(await planOf(deps, i.userId), "sound", "edit"));
  await owned(deps, i.userId, i.projectId);
  const c = checkStudioSpec(i.spec, deps.sound.libraryCleared());
  if (!c.ok) throw new StudioError(422, c.code, c.error);
  const ev = c.spec.events.find((e) => e.event === i.event);
  if (!ev) throw new StudioError(400, "bad_request", `No event called ${i.event} in this set.`);
  const sel = deps.sound.renderHost();
  if (!sel.ok) throw new StudioError(503, "render_off", "Sound rendering isn't switched on here yet, so the studio plays its in-browser preview only. The next build renders the real files.", { reason: sel.reason });
  const one = checkReturnedSound({ key: i.set, spec: { version: 1, name: i.set, events: [ev] } }, { library: deps.sound.libraryCleared() });
  if (!one.ok) throw new StudioError(422, "bad_spec", one.reason);
  const res: RenderResult = await sel.host.render(renderJobFor([one])).catch((e) => ({ ok: false as const, code: "transport" as const, error: (e as Error).message }));
  if (!res.ok) throw new StudioError(res.code === "busy" ? 503 : 502, `render_${res.code}`, res.code === "busy" ? "The render host is busy with another render. Try again in a few seconds." : `The render host couldn't render this (${res.code}). Nothing was changed.`);
  const files = res.sets.find((s) => s.name === i.set)?.events.find((e) => e.event === i.event)?.files ?? [];
  if (!files.length) throw new StudioError(502, "render_failed", res.errors[0]?.error ? `The render host refused it: ${res.errors[0].error}` : "The render host returned nothing for this event.");
  const fake = res.tool.runner.startsWith("fake");
  return {
    host: sel.host.id, tool: res.tool, event: i.event, fake,
    files: files.slice(0, 4).map((f) => ({ index: f.index, weight: f.weight, audio: f.ogg, mime: fake ? "audio/wav" : "audio/ogg", bytes: f.bytes, measure: f.measure, quality: f.quality, render: f.render })),
  };
}

export const PREVIEW_VERSION = "pv-1";
export const PREVIEW_MAX_BYTES = 44 + PREVIEW_MAX_SECONDS * SAMPLE_RATE * 2;
export type PreviewCache = { get(k: string): Buffer | undefined; set(k: string, v: Buffer): void; size(): number };
/** A small in-process LRU (per server process): at most `maxEntries` previews and `maxBytes` in total. */
export function lruCache(maxEntries = 96, maxBytes = 32 * 1024 * 1024): PreviewCache {
  const m = new Map<string, Buffer>();
  let bytes = 0;
  return {
    get(k) { const v = m.get(k); if (v) { m.delete(k); m.set(k, v); } return v; },
    set(k, v) {
      if (m.has(k)) { bytes -= m.get(k)!.length; m.delete(k); }
      m.set(k, v); bytes += v.length;
      while (m.size > maxEntries || bytes > maxBytes) { const first = m.keys().next().value as string; bytes -= m.get(first)!.length; m.delete(first); }
    },
    size: () => m.size,
  };
}

/** Clamp a client preview request; null when it is not a library sound we know. */
export function normalisePreview(raw: Record<string, unknown>): { req: PreviewRequest; sound: LibrarySound } | null {
  const id = typeof raw.libraryId === "string" ? raw.libraryId : "";
  if (!/^[a-z][a-z0-9_]{1,52}$/.test(id)) return null;
  const sound = librarySound(id);
  if (!sound) return null;
  const n = (v: unknown, lo: number, hi: number, d: number, step = 1000) => (typeof v === "number" && Number.isFinite(v) ? Math.round(Math.min(hi, Math.max(lo, v)) * step) / step : d);
  const trimStart = n(raw.trimStart, 0, Math.max(0, sound.duration - 0.01), 0);
  const req: PreviewRequest = {
    libraryId: id, trimStart, length: n(raw.length, 0.01, Math.min(PREVIEW_MAX_SECONDS, Math.max(0.01, sound.duration - trimStart)), Math.min(PREVIEW_MAX_SECONDS, sound.duration)),
    pitch: n(raw.pitch, -24, 24, 0, 1), fadeIn: n(raw.fadeIn, 0, 2000, 0, 1), fadeOut: n(raw.fadeOut, 0, 4000, 0, 1),
  };
  return { req, sound };
}
/** The cache key: the request, the FILE's sha256 (a replaced file never serves an old preview) and the code versions. */
export const previewCacheKey = (req: PreviewRequest, fileSha256: string) =>
  createHash("sha256").update(JSON.stringify([PREVIEW_VERSION, RENDER_VERSION, fileSha256, req.libraryId, req.trimStart, req.length, req.pitch, req.fadeIn, req.fadeOut])).digest("hex");

const isWav = (b: Buffer) => b.length > 44 && b.toString("ascii", 0, 4) === "RIFF" && b.toString("ascii", 8, 12) === "WAVE";

export async function libraryPreview(deps: SoundServiceDeps, cache: PreviewCache, i: { userId: string; raw: Record<string, unknown> }): Promise<{ wav: Buffer; key: string; cached: boolean; host: string }> {
  // the licence gate first (fail closed), then the plan gate (Sound Library = Saka and up; unknown plan = no)
  if (!deps.sound.libraryCleared()) throw new StudioError(403, "library_not_cleared", "Library audition is off until the owner confirms the sound licence. Synth layers still play in the browser.");
  gateOrThrow(canAsset(await planOf(deps, i.userId), "sound", "create"));
  const n = normalisePreview(i.raw);
  if (!n) throw new StudioError(400, "bad_request", "That isn't a sound in the library.");
  const key = previewCacheKey(n.req, n.sound.sha256);
  const hit = cache.get(key);
  if (hit) return { wav: hit, key, cached: true, host: "cache" };
  const sel = deps.sound.renderHost();
  if (!sel.ok || !sel.host.preview) throw new StudioError(503, "render_off", "Library audition needs the render host, which isn't switched on here.");
  const job: PreviewJob = { v: 1, kind: "preview", library: { id: n.sound.id, file: n.sound.file, sha256: n.sound.sha256, channels: n.sound.channels, duration: n.sound.duration }, ...n.req };
  const r: PreviewResult = await sel.host.preview(job).catch((e) => ({ ok: false as const, code: "transport" as const, error: (e as Error).message }));
  if (!r.ok) throw new StudioError(r.code === "busy" ? 503 : 502, `preview_${r.code}`, r.code === "busy" ? "The render host is busy. Try again in a moment." : "The preview couldn't be made right now.");
  const wavBytes = Buffer.from(r.wav, "base64");
  if (!isWav(wavBytes) || wavBytes.length > PREVIEW_MAX_BYTES) throw new StudioError(502, "preview_bad", "The render host sent a preview that isn't a short WAV; it was not passed on.");
  cache.set(key, wavBytes);
  return { wav: wavBytes, key, cached: false, host: sel.host.id };
}

// ---------------------------------------------------------------------------- the FAKE render host (dev / tests)

/**
 * Deterministic stand-in audio for a library id: a synth preset chosen by the sound's category, at the manifest's
 * length and loudness. It never reads a library file (dev servers and tests have none, and the licence is open).
 */
export function fakeLibraryAudio(id: string): Mono {
  const s = librarySound(id);
  const cat = s?.category ?? "other";
  const preset = cat === "weapons" ? "gunshot" : cat === "impacts_destruction" || cat === "doors_mechanisms" ? "impact" : cat === "creatures_voices" || cat === "crowd_reactions" ? "wail" : cat === "ui_alerts" ? "confirm" : cat === "magic_energy" || cat === "music_stingers" ? "magic" : "whoosh";
  const seed = [...id].reduce((a, ch) => (a * 31 + ch.charCodeAt(0)) % 9973, 7) + 1;
  const x = synth(preset, Math.min(8, Math.max(0.05, s?.duration ?? 1)), seed, preset === "wail" ? { start: 1300, end: 820, breath: 0.6, harmonics: 0.7 } : {});
  const m = measure(x);
  return m.lufs > -998 ? gainDb(x, (s?.lufs ?? -20) - m.lufs) : x;
}

/** In-process render host with the fake library: real DSP + real measurements, WAV instead of Ogg (no ffmpeg). */
export function fakeRenderHost(): RenderHost {
  return {
    id: "fake",
    async render(job) {
      const sets = job.sets.map((s) => ({
        name: s.name,
        events: s.spec.events.map((e) => ({
          event: e.event,
          files: e.variants.map((v, i) => {
            const r = renderVariant(v, e.role, fakeLibraryAudio);
            const w = wav(r.pcm);
            const m = measure(r.pcm);
            const enc = { codec: "vorbis", channels: 1, sampleRate: SAMPLE_RATE, durationS: m.durationS };
            return { index: i + 1, weight: v.weight, ogg: w.toString("base64"), oggSha256: createHash("sha256").update(w).digest("hex"), pcmSha256: "", bytes: w.length, encoded: enc, measure: m, quality: soundQuality(m, enc, e.role), render: { gainDb: r.gainDb, peakLimited: r.peakLimited, truncated: r.truncated, ceilingDb: -1.5, passes: 1 } };
          }),
        })),
      }));
      return { ok: true, tool: { runner: "fake-render-host", render: RENDER_VERSION, quality: SOUND_QUALITY_VERSION, ffmpeg: "none (fake host: WAV, not Ogg)" }, sets, errors: [] };
    },
    async preview(job) {
      let x = trim(fakeLibraryAudio(job.library.id), job.trimStart, job.length);
      x = fade(repitch(x, job.pitch), job.fadeIn, job.fadeOut);
      const w = wav(x.slice(0, PREVIEW_MAX_SECONDS * SAMPLE_RATE));
      return { ok: true, tool: { runner: "fake-render-host", render: RENDER_VERSION }, wav: w.toString("base64"), bytes: w.length, durationS: Math.round((x.length / SAMPLE_RATE) * 1000) / 1000, samplePeakDb: 0 };
    },
  };
}

// ---------------------------------------------------------------------------- candidates (the AI edit interface)

/**
 * Same shape as the Texture Studio's CandidateBackend: the real one (./sound-candidates.ts) creates a CHANGE BUILD
 * for one event; its sound row (recorded by the normal asset sync) is the candidate. A candidate is never applied by
 * the backend: the customer accepts it (all, one variant, or as a new variant) by saving, or rejects it.
 */
export type SoundCandidateRequest = { userId: string; user: unknown; project: ProjectRow; chain: ChainInfo; set: string; event: string; prompt: string; current: SoundSetEntry };
export type SoundCandidatePoll =
  | { status: "pending"; note?: string }
  | { status: "ready"; spec: SoundSpec; specSha256: string; event: string; summary: string }
  | { status: "failed"; error: string };
export interface SoundCandidateBackend {
  readonly id: string;
  request(r: SoundCandidateRequest): Promise<{ ok: true; requestId: string } | { ok: false; status: number; code: string; error: string }>;
  poll(r: { userId: string; project: ProjectRow; chain: ChainInfo; set: string; requestId: string }): Promise<SoundCandidatePoll>;
}

export async function soundForEdit(deps: StudioServiceDeps, userId: string, projectId: string, set: string) {
  gateOrThrow(canAsset(await planOf(deps, userId), "sound", "edit"));
  const project = await owned(deps, userId, projectId);
  if (!project.rootBuildId) throw new StudioError(409, "no_build", "Build the mod once before asking Cyrus to edit its sounds.");
  const chain = await deps.chain(userId, project.rootBuildId);
  if (!chain) throw new StudioError(404, "not_found", "Mod not found.");
  const entry = (await soundSetsOf(deps, project.id, chain)).find((s) => s.set === set);
  if (!entry) throw new StudioError(404, "not_found", `No sound set called ${set} in this mod.`);
  return { project, chain, entry };
}

/** The candidate's spec sha256, read on the SERVER (a persisted candidate row first, else the backend's poll). */
export async function soundCandidateSha(backend: SoundCandidateBackend, r: { userId: string; project: ProjectRow; chain: ChainInfo; entry: SoundSetEntry; set: string; requestId: string }): Promise<{ sha: string; event: string } | null> {
  const persisted = r.entry.candidates.find((c) => c.buildId === r.requestId);
  if (persisted) return { sha: persisted.specSha256, event: persisted.event };
  const p = await backend.poll({ userId: r.userId, project: r.project, chain: r.chain, set: r.set, requestId: r.requestId });
  return p.status === "ready" ? { sha: p.specSha256, event: p.event } : null;
}

export async function rejectSoundCandidate(deps: SoundServiceDeps, backend: SoundCandidateBackend, i: { userId: string; projectId: string; set: string; requestId: string; expectedHeadId: string | null }) {
  const { project, chain, entry } = await soundForEdit(deps, i.userId, i.projectId, i.set);
  const c = await soundCandidateSha(backend, { userId: i.userId, project, chain, entry, set: i.set, requestId: i.requestId });
  if (!c) throw new StudioError(409, "candidate_not_ready", "That candidate isn't ready.");
  return saveSoundSet(deps, {
    userId: i.userId, projectId: project.id, set: i.set, spec: entry.spec, baseAssetId: entry.assetId, expectedHeadId: i.expectedHeadId,
    decision: { candidate: i.requestId, event: c.event, accepted: false, mode: "reject" }, alsoSupersedes: [c.sha],
  });
}

/**
 * A deterministic fake: "sharper and shorter" (pitch +2, 15 % shorter, tighter fades, less reverb, a brighter
 * low-pass, new synth seeds) applied to the event's first variant. Library layers stay library layers.
 */
export function fakeSoundCandidates(opts: { readyAfter?: number } = {}): SoundCandidateBackend & { requests: Map<string, { set: string; event: string; prompt: string; base: SoundSpec; polls: number }> } {
  const requests = new Map<string, { set: string; event: string; prompt: string; base: SoundSpec; polls: number }>();
  let n = 0;
  return {
    id: "fake", requests,
    async request(r) {
      if (!r.current.spec.events.some((e) => e.event === r.event)) return { ok: false, status: 400, code: "bad_request", error: `${r.event} has no sound yet. Add a first layer, then ask Cyrus to refine it.` };
      const requestId = `fakes${(++n).toString().padStart(4, "0")}${r.set.slice(0, 8)}`;
      requests.set(requestId, { set: r.set, event: r.event, prompt: r.prompt, base: r.current.spec, polls: 0 });
      return { ok: true, requestId };
    },
    async poll(r) {
      const q = requests.get(r.requestId);
      if (!q || q.set !== r.set) return { status: "failed", error: "unknown candidate" };
      if (++q.polls <= (opts.readyAfter ?? 1)) return { status: "pending", note: "Cyrus is designing a candidate" };
      const spec: SoundSpec = JSON.parse(JSON.stringify(q.base));
      const e = spec.events.find((x) => x.event === q.event)!;
      const v = e.variants[0];
      v.layers = v.layers.map((l) => ({
        ...l, pitch: Math.min(24, l.pitch + 2), length: l.length == null ? null : Math.max(0.05, Math.round(l.length * 0.85 * 1000) / 1000),
        fadeOut: Math.round(l.fadeOut * 0.8), seed: l.source.startsWith("synth:") ? (l.seed + 5) % 2147483647 : l.seed,
      }));
      v.processing = { ...v.processing, reverb: Math.max(0, Math.round((v.processing.reverb - 0.05) * 100) / 100), lowpass: v.processing.lowpass ? Math.min(19999, v.processing.lowpass + 1000) : null };
      e.variants = [v];
