// Cyrus Sound Studio (R1b): the REAL candidate backend. SERVER ONLY. A sound edit is a CHANGE BUILD through the
// existing flow (lib/modbuilder/create.ts createModBuild: plan + token gates, asset request ["sound"], model Saka:
// the cheapest model whose plan has the Sound Studio); its change request starts with SOUND_CANDIDATE_MARK. When the
// build succeeds, the portal's normal asset sync records its sound row for the set; poll() returns it. Never applied
// on its own. NOT RUN against the real build service in R1b (no paid model calls): tests and devhost use the fake.
import type { User } from "@prisma/client";
import { db } from "../../db";
import { createModBuild } from "../../modbuilder/create";
import { syncBuild } from "../../modbuilder/store";
import { isTerminal } from "../../modbuilder/types";
import { candidateSummaryOf, soundCandidateOf, soundCandidateRequestText } from "./marker";
import { docOfSoundRow } from "./sound-model";
import type { SoundCandidateBackend } from "./sound-service";
import type { StudioStore } from "./service";

export function changeBuildSoundCandidates(store: StudioStore): SoundCandidateBackend {
  return {
    id: "change-build",
    async request(r) {
      const base = r.chain.baseBuildId ?? r.chain.latestBuildId;
      if (!base) return { ok: false, status: 409, code: "no_build", error: "Build the mod once before asking Cyrus to edit its sounds." };
      const res = await createModBuild(r.user as User, { changeRequest: soundCandidateRequestText(r.set, r.event, r.prompt), baseBuildId: base, mcVersion: r.chain.mcVersion, model: "saka", assets: ["sound"] });
      if (!res.ok) return { ok: false, status: res.status, code: String(res.json.code ?? "build_refused"), error: String(res.json.error ?? "Cyrus couldn't start that edit.") };
      return { ok: true, requestId: res.build.id };
    },
    async poll(r) {
      let row = await db.modBuild.findUnique({ where: { id: r.requestId } });
      const c = soundCandidateOf(row?.changeRequest);
      if (!row || row.userId !== r.userId || !c || c.set !== r.set) return { status: "failed", error: "unknown candidate" };
      if (!isTerminal(row.status)) { row = await syncBuild(row).catch(() => row!); if (!isTerminal(row.status)) return { status: "pending", note: "Cyrus is building the edit" }; }
      if (row.status !== "succeeded") return { status: "failed", error: row.error || "The edit didn't build. Nothing changed." };
      const asset = (await store.assets(r.project.id)).filter((a) => a.kind === "sound" && a.assetKey === r.set && (a.provenance as { modBuildId?: string } | null)?.modBuildId === row!.id).pop();
      const doc = asset ? docOfSoundRow(asset) : null;
      if (!asset || !doc) return { status: "failed", error: "The edit built, but it did not change this sound set (or its sounds could not be rendered)." };
      return { status: "ready", spec: doc.spec, specSha256: asset.sha256, event: c.event, summary: candidateSummaryOf(row.changeRequest) };
    },
  };
}
EOF
