// Cyrus Sound Studio (R1b): HTTP handlers of the sound endpoints of /api/cyrus/assets/v1 (framework-free; the route
// files are one-line wrappers with apiDeps()). Same pipeline as ./http.ts: viewer (404 for anyone outside the studios)
// -> per-user rate limit -> input validation -> the plan gate (server side, fail closed) -> the service.
import { canBrowse } from "../library/gate";
import type { LibraryAsset } from "../library/types";
import { librarySound } from "../sound/library";
import { MAX_PROMPT, StudioError } from "./service";
import { json, need, readJson, RE, run, NO_STORE, type Ctx, type StudioApiDeps } from "./http";
import { libraryLayer, type SoundDecision } from "./sound-edit";
import {
  libraryPreview, lruCache, rejectSoundCandidate, renderSoundEvent, saveSoundSet, soundCandidateSha, soundForEdit, soundSetsOf,
  type SoundServiceDeps,
} from "./sound-service";

type P = { projectId?: string; set?: string; requestId?: string };
const SET = /^[a-z][a-z0-9_]{1,31}$/, EVENT = /^[a-z][a-z0-9_]{0,23}$/;
function ps(p: P, ...names: (keyof P)[]) {
  for (const n of names) need((n === "projectId" ? RE.project : n === "set" ? SET : RE.id).test(p[n] ?? ""), `${n} is not valid`);
  return p as Required<P>;
}
function soundDeps(deps: StudioApiDeps): SoundServiceDeps {
  if (!deps.sound) throw new StudioError(503, "sound_off", "The Sound Studio isn't wired on this server.");
  return { ...deps.service, sound: deps.sound };
}
const headOk = (v: unknown) => v === null || (typeof v === "string" && RE.id.test(v));

/** GET .../projects/:projectId/sounds/:set/revisions: the set's history (every revision keeps its spec). */
export const handleSoundHistory = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "read", max: 120 }, async ({ viewer }) => {
  const { projectId, set } = ps(p, "projectId", "set");
  const proj = await deps.service.store.project(projectId);
  if (!proj || proj.userId !== viewer.userId) throw new StudioError(404, "not_found", "Project not found.");
  const chain = proj.rootBuildId ? await deps.service.chain(viewer.userId, proj.rootBuildId) : null;
  const s = (await soundSetsOf(deps.service, projectId, chain)).find((x) => x.set === set);
  if (!s) throw new StudioError(404, "not_found", `No sound set called ${set} in this mod.`);
  const seq = new Map((await deps.service.store.revisions(projectId)).map((r) => [r.id, r.seq]));
  return json(200, { set, history: s.history.map((h) => ({ ...h, revisionSeq: seq.get(h.revisionId) ?? null })) });
});

/** POST .../sounds/:set/revisions { spec, baseAssetId, expectedHeadId, acceptCandidate?, mode? }: a NEW revision. */
export const handleSoundSave = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "save", max: 30 }, async ({ viewer }) => {
  const { projectId, set } = ps(p, "projectId", "set");
  const sd = soundDeps(deps);
  const b = await readJson(req);
  need(b.baseAssetId === null || (typeof b.baseAssetId === "string" && RE.id.test(b.baseAssetId)), "baseAssetId must be an asset id or null");
  need(headOk(b.expectedHeadId), "expectedHeadId must be a revision id or null");
  let decision: SoundDecision | null = null;
  let also: string[] = [];
  if (b.acceptCandidate !== undefined) {
    // accepting: the server re-reads the candidate (never trusts a client copy) and records the decision
    need(typeof b.acceptCandidate === "string" && RE.id.test(b.acceptCandidate), "acceptCandidate must be a candidate id");
    const mode = String(b.mode ?? "replace_event");
    need(["replace_event", "replace_variant", "add_variant"].includes(mode), "mode must be replace_event, replace_variant or add_variant");
    if (!deps.soundCandidates) throw new StudioError(503, "sound_off", "Cyrus sound candidates aren't wired on this server.");
    const { project, chain, entry } = await soundForEdit(deps.service, viewer.userId, projectId, set);
    const c = await soundCandidateSha(deps.soundCandidates, { userId: viewer.userId, project, chain, entry, set, requestId: b.acceptCandidate as string });
    if (!c) throw new StudioError(409, "candidate_not_ready", "That candidate isn't ready.");
    decision = { candidate: b.acceptCandidate as string, event: c.event, accepted: true, mode: mode as SoundDecision["mode"] };
    also = [c.sha];
  }
  const r = await saveSoundSet(sd, { userId: viewer.userId, projectId, set, spec: b.spec, baseAssetId: (b.baseAssetId as string | null) ?? null, expectedHeadId: (b.expectedHeadId as string | null) ?? null, decision, alsoSupersedes: also });
  return json(201, r);
});

/** POST .../sounds/:set/render { spec, event }: the render host mixes the event (files + measurements; nothing saved). */
export const handleSoundRender = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "render", max: 12 }, async ({ viewer }) => {
  const { projectId, set } = ps(p, "projectId", "set");
  const b = await readJson(req);
  need(typeof b.event === "string" && EVENT.test(b.event), "event is not valid");
  return json(200, await renderSoundEvent(soundDeps(deps), { userId: viewer.userId, projectId, set, spec: b.spec, event: b.event as string }));
});

/** POST .../sounds/:set/candidates { event, prompt }: ask Cyrus for an edit of one event (a candidate, never applied). */
export const handleSoundCandidate = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "candidate", max: 6 }, async ({ viewer }) => {
  const { projectId, set } = ps(p, "projectId", "set");
  if (!deps.soundCandidates) throw new StudioError(503, "sound_off", "Cyrus sound candidates aren't wired on this server.");
  const b = await readJson(req);
  const prompt = typeof b.prompt === "string" ? b.prompt.trim() : "";
  need(typeof b.event === "string" && EVENT.test(b.event), "event is not valid");
  need(prompt.length >= 4 && prompt.length <= MAX_PROMPT, `Describe the change in 4 to ${MAX_PROMPT} characters.`);
  const { project, chain, entry } = await soundForEdit(deps.service, viewer.userId, projectId, set);
  const r = await deps.soundCandidates.request({ userId: viewer.userId, user: viewer.user, project, chain, set, event: b.event as string, prompt, current: entry });
  if (!r.ok) return json(r.status, { error: r.error, code: r.code });
  return json(202, { requestId: r.requestId, backend: deps.soundCandidates.id });
});

/** GET .../sounds/:set/candidates/:requestId: pending | ready (the candidate spec) | failed. */
export const handleSoundCandidatePoll = (_req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "poll", max: 120 }, async ({ viewer }) => {
  const { projectId, set, requestId } = ps(p, "projectId", "set", "requestId");
  if (!deps.soundCandidates) throw new StudioError(503, "sound_off", "Cyrus sound candidates aren't wired on this server.");
  const { project, chain } = await soundForEdit(deps.service, viewer.userId, projectId, set);
  return json(200, await deps.soundCandidates.poll({ userId: viewer.userId, project, chain, set, requestId }));
});

/** POST .../sounds/:set/candidates/:requestId/reject { expectedHeadId }: keep the set as it is, record the decision. */
export const handleSoundCandidateReject = (req: Request, p: P, deps: StudioApiDeps) => run(deps, { key: "save", max: 30 }, async ({ viewer }) => {
  const { projectId, set, requestId } = ps(p, "projectId", "set", "requestId");
  if (!deps.soundCandidates) throw new StudioError(503, "sound_off", "Cyrus sound candidates aren't wired on this server.");
  const b = await readJson(req);
  need(headOk(b.expectedHeadId), "expectedHeadId must be a revision id or null");
  return json(201, await rejectSoundCandidate(soundDeps(deps), deps.soundCandidates, { userId: viewer.userId, projectId, set, requestId, expectedHeadId: (b.expectedHeadId as string | null) ?? null }));
});

/**
 * POST /api/cyrus/assets/v1/sound/preview { libraryId, trimStart, length, pitch, fadeIn, fadeOut } -> audio/wav.
 * A SHORT processed preview of one library sound (never the raw file), only when the library is cleared and the
 * plan may use the Sound Library. Cached per process by request + file sha256.
 */
const G = globalThis as { __cyrusPreviewCache?: ReturnType<typeof lruCache> };
export const handleSoundPreview = (req: Request, deps: StudioApiDeps) => run(deps, { key: "preview", max: 90 }, async ({ viewer }) => {
  const b = await readJson(req);
  const r = await libraryPreview(soundDeps(deps), deps.previewCache ?? (G.__cyrusPreviewCache ??= lruCache()), { userId: viewer.userId, raw: b });
  return new Response(new Uint8Array(r.wav), { status: 200, headers: { ...NO_STORE, "content-type": "audio/wav", "x-content-type-options": "nosniff", "x-cyrus-preview": r.cached ? "cache" : "render", "content-disposition": "inline" } });
});

/**
 * POST library/use for a SOUND (called from ./http.ts handleUse): checks the plan + licence gates, reserves
 * `<ns>:<set>.<event>` in the project's namespace and returns the library LAYER (pitch -1: the licence rule) to add
 * to the open variant. Nothing is saved here: the studio's draft may hold other edits; the save makes the revision.
 */
export async function useSoundLayer(b: Record<string, unknown>, { deps, viewer }: Ctx, source: string, id: string): Promise<Response> {
  const projectId = String(b.projectId ?? ""), set = String(b.key ?? ""), event = String(b.event ?? "");
  need(EVENT.test(event), "event is not valid");
  need(source === "builtin", "Only the built-in sound library can be used here.");
  const plan = await deps.service.planOf(viewer.userId).catch(() => null);
  const g = canBrowse({ signedIn: true, plan }, "sound", source as LibraryAsset["source"]);
  if (!g.ok) throw new StudioError(403, g.code, g.reason, g.needs ? { needs: g.needs } : {});
  if (!deps.sound?.libraryCleared()) throw new StudioError(403, "library_not_cleared", "Library sounds can't be added to mods until the owner confirms the sound licence. Use a synth preset for now.");
  const s = librarySound(id);
  if (!s) throw new StudioError(404, "not_found", "That sound isn't in the library.");
  const project = await deps.service.store.project(projectId);
  if (!project || project.userId !== viewer.userId) throw new StudioError(404, "not_found", "Project not found.");
  const r = await deps.service.store.reserve(project.id, "sound", `${set}.${event}`);
  const layer = libraryLayer(s.id, { length: Math.round(Math.min(s.duration, 1.5) * 1000) / 1000, fadeOut: 60 });
  return json(200, { layer, identifier: r.fullId, ledger: { libraryId: s.id, provenance: s.ledger.provenance, licenceStatus: s.ledger.licenceStatus, original: false } });
}

