import { PeaksCanvas } from "./sound-canvas";''')
s=s.replace('''const label = (s: string) => s.replace(/_/g, " ");''','''const label = (s: string) => s.replace(/_/g, " ");
/** Sound tag chips (the library's most common tags, lib/cyrus/sound/taxonomy.json) */
const SOUND_TAGS = ["mob", "weapon", "whoosh", "hit", "gunshot", "scream", "door", "magic", "explosion", "water", "alert", "ui"];
const LENGTHS: { v: string; l: string; min?: number; max?: number }[] = [{ v: "", l: "Any length" }, { v: "s", l: "Under 0.5 s", max: 0.5 }, { v: "m", l: "0.5 to 2 s", min: 0.5, max: 2 }, { v: "l", l: "2 to 6 s", min: 2, max: 6 }, { v: "x", l: "Over 6 s", min: 6 }];
const LOUDNESS: { v: string; l: string; min?: number; max?: number }[] = [{ v: "", l: "Any loudness" }, { v: "q", l: "Quiet, below -24 LUFS", max: -24 }, { v: "m", l: "Medium, -24 to -16", min: -24, max: -16 }, { v: "l", l: "Loud, above -16 LUFS", min: -16 }];
const catLabel = (c: string) => ({ ui_alerts: "UI & alerts", creatures_voices: "Creatures & voices", music_stingers: "Music & stingers", environment_ambience: "Environment", movement: "Movement", doors_mechanisms: "Doors & mechanisms", impacts_destruction: "Impacts", weapons: "Weapons", crowd_reactions: "Crowds", magic_energy: "Magic & energy" } as Record<string, string>)[c] ?? label(c);''')
s=s.replace('''  placeholder?: string;
};''','''  placeholder?: string;
  /** sound: the "Add" button label (e.g. "Add to hurt V1") and a footer note (licence state) */
  useLabel?: string;
  note?: ReactNode;
};''')
s=s.replace('''export function LibraryBrowser({ kind, projectId, uploadsOn, onUse, renderLead, placeholder }: LibraryBrowserProps) {''','''export function LibraryBrowser(props: LibraryBrowserProps) {
  return props.kind === "sound" ? <SoundLibrary {...props} /> : <TextureLibrary {...props} />;
}

function TextureLibrary({ kind, projectId, uploadsOn, onUse, renderLead, placeholder }: LibraryBrowserProps) {''')
s+='''
/** The Sound Library (Sound Studio): tag chips, categories, length + loudness ranges, "similar to", peaks outlines. */
function SoundLibrary({ projectId, onUse, renderLead, placeholder, useLabel, note }: LibraryBrowserProps) {
  const toast = useToast();
  const [q, setQ] = useState("");
  const [tag, setTag] = useState("");
  const [cat, setCat] = useState("");
  const [len, setLen] = useState("");
  const [loud, setLoud] = useState("");
  const [similar, setSimilar] = useState<LibraryItem | null>(null);
  const [res, setRes] = useState<Result | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [selRef, setSelRef] = useState<string | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const [cats, setCats] = useState<Record<string, number>>({});
  const [all, setAll] = useState<number | null>(null);
  useEffect(() => {
    const t = window.setTimeout(async () => {
      const L = LENGTHS.find((x) => x.v === len)!, V = LOUDNESS.find((x) => x.v === loud)!;
      try {
        const r = await studioApi.browse({ kind: "sound", q: similar ? undefined : q, category: similar ? undefined : cat || undefined, tags: similar ? undefined : tag || undefined, similar: similar?.ref, minDur: L.min, maxDur: L.max, minLufs: V.min, maxLufs: V.max, projectId, limit: 40 });
        setRes(r); setErr(null);
        if (!q && !cat && !tag && !len && !loud && !similar) { setCats(r.facets.category); setAll(r.total); }
      } catch (e) { setErr((e as Error).message); }
    }, 180);
    return () => window.clearTimeout(t);
  }, [q, tag, cat, len, loud, similar, projectId]);
  const items = res?.items ?? [];
  const sel = items.find((i) => i.ref === selRef) ?? null;
  const denied = res?.denied.find((d) => d.source === "builtin");
  const use = async (i: LibraryItem) => {
    setBusy(i.ref);
    try { await onUse(i, i.id); }
    catch (e) { toast(e instanceof ApiError ? e.message : "Couldn't add it. Nothing was changed.", true); }
    finally { setBusy(null); }
  };
  const nm = (i: LibraryItem) => i.sound?.prefix || i.name;
  return (
    <div className="lib" data-kind="sound">
      <div className="lib-q">
        <div className="lib-srch"><SI n="search" /><input className="cys-field" value={q} onChange={(e) => { setQ(e.target.value); setSimilar(null); }} placeholder={placeholder ?? `Search ${all ?? ""} sounds: scream, door, 9mm…`.replace("  ", " ")} aria-label="Search the sound library" /></div>
        {similar ? (
          <div className="cys-chiprow"><button type="button" className="cys-fchip on" onClick={() => setSimilar(null)} aria-label="Stop showing similar sounds">Similar to {nm(similar)}<SI n="close" /></button></div>
        ) : (
          <div className="cys-chiprow" role="group" aria-label="Tags">
            <button type="button" className={`cys-fchip ${!tag ? "on" : ""}`} onClick={() => setTag("")}>All</button>
            {SOUND_TAGS.map((t) => <button key={t} type="button" className={`cys-fchip ${tag === t ? "on" : ""}`} onClick={() => setTag(tag === t ? "" : t)} aria-pressed={tag === t}>{t}</button>)}
          </div>
        )}
        <select className="cys-field" value={cat} onChange={(e) => setCat(e.target.value)} aria-label="Category" disabled={!!similar}>
          <option value="">All categories ({Object.keys(cats).length || "…"})</option>
          {Object.entries(cats).sort((a, b) => b[1] - a[1]).map(([c, nn]) => <option key={c} value={c}>{catLabel(c)} · {nn}</option>)}
        </select>
        <div className="lib-facets">
          <select className="cys-field" value={len} onChange={(e) => setLen(e.target.value)} aria-label="Length">{LENGTHS.map((x) => <option key={x.v} value={x.v}>{x.l}</option>)}</select>
          <select className="cys-field" value={loud} onChange={(e) => setLoud(e.target.value)} aria-label="Loudness">{LOUDNESS.map((x) => <option key={x.v} value={x.v}>{x.l}</option>)}</select>
        </div>
      </div>
      {denied && <div className="lib-lock"><SI n="lock" /><span style={{ flex: 1 }}>{denied.reason}</span></div>}
      {err && <div className="cys-empty">{err}</div>}
      <div role="list">
        {items.map((i) => (
          <div key={i.ref} role="listitem" className={`lib-srow ${i.ref === selRef ? "on" : ""}`} data-testid="sound-lib-row">
            {renderLead ? renderLead(i) : <span />}
            <button type="button" className="nm" onClick={() => setSelRef(i.ref === selRef ? null : i.ref)} aria-expanded={i.ref === selRef}>
              <b>{nm(i)}</b><small>{catLabel(i.category)} · {i.sound?.lufs != null && i.sound.lufs > -60 ? `${i.sound.lufs} LUFS` : "very quiet"}</small>
            </button>
            <span className="d">{(i.sound?.duration ?? Number(i.descriptors.duration ?? 0)).toFixed(2)}s</span>
            <button type="button" className="cys-btn xs" onClick={() => void use(i)} disabled={busy === i.ref} title={useLabel ?? "Add as a layer"}><SI n="plus" />Add</button>
            {i.ref === selRef && (
              <div className="lib-sdetail" data-testid="library-detail">
                {i.sound?.peaks && <PeaksCanvas peaks={i.sound.peaks} label={`Loudness outline of ${nm(i)}`} />}
                <div className="cys-chiprow">{i.tags.slice(0, 6).map((t) => <button key={t} type="button" className="cys-fchip" onClick={() => { setTag(SOUND_TAGS.includes(t) ? t : ""); if (!SOUND_TAGS.includes(t)) setQ(t); setSimilar(null); }}>{t}</button>)}</div>
                <span className="cys-hint">{label(String(i.descriptors.durationClass ?? ""))} · {label(String(i.descriptors.intensity ?? ""))} · {label(String(i.descriptors.pitchBand ?? ""))} pitch{i.descriptors.loopable ? " · loopable" : ""}</span>
                <span className="cys-hint" title={i.ledger.licenceStatus}>{i.ledger.provenance} · licence: {i.ledger.licenceStatus}</span>
                <div style={{ display: "flex", gap: 6 }}>
                  <button type="button" className="cys-btn xs" onClick={() => { setSimilar(i); setSelRef(null); }}><SI n="search" />Similar sounds</button>
                  <button type="button" className="cys-btn xs primary" onClick={() => void use(i)} disabled={busy === i.ref} data-testid="use-in-project"><SI n="plus" />{useLabel ?? "Use in project"}</button>
                </div>
              </div>
            )}
          </div>
        ))}
        {res && !items.length && !err && <div className="cys-empty">No sounds match. Try a broader word, or a synth preset.</div>}
      </div>
      {res && <p className="cys-hint lib-foot">Showing {items.length} of {res.total}. Names, categories, lengths, loudness and outlines come from the library manifest; the audio itself stays on the render host.{note ? <> {note}</> : null}</p>}
    </div>
  );
}
'''
open(p,'w').write(s)
EOF
