"use client";
// Cyrus Sound Studio canvases: the waveform editor (ruler, mix, selected-layer region with trim / fade / gain / move
// handles, -1 dBTP ceiling, playhead, zoom + scroll) and the small waveforms (layer lanes, presets, history, library
// outlines). Drawing only: the geometry is lib/cyrus/studios/sound-edit.ts (unit-tested), the audio is sound-audio.ts.
import { useCallback, useEffect, useRef, useState } from "react";
import { SAMPLE_RATE } from "@/lib/cyrus/sound/dsp";
import { decodePeaks, peakDiff, peaksOf } from "@/lib/cyrus/sound/peaks";
import { dragLayer, hitHandle, layerSpan, type Handle } from "@/lib/cyrus/studios/sound-edit";
import type { SoundLayer } from "@/lib/cyrus/sound/spec";

const css = (el: Element, v: string, d: string) => getComputedStyle(el).getPropertyValue(v).trim() || d;
function useThemeTick() {
  const [t, setT] = useState(0);
  useEffect(() => { const mo = new MutationObserver(() => setT((x) => x + 1)); mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] }); return () => mo.disconnect(); }, []);
  return t;
}
function fit(c: HTMLCanvasElement) {
  const dpr = Math.min(2, window.devicePixelRatio || 1), r = c.getBoundingClientRect();
  const W = Math.max(1, r.width), H = Math.max(1, r.height);
  if (c.width !== Math.round(W * dpr) || c.height !== Math.round(H * dpr)) { c.width = Math.round(W * dpr); c.height = Math.round(H * dpr); }
  const x = c.getContext("2d")!; x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, W, H);
  return { x, W, H };
}
function useResize(ref: React.RefObject<HTMLElement | null>, cb: () => void) {
  useEffect(() => { const el = ref.current; if (!el) return; const ro = new ResizeObserver(() => cb()); ro.observe(el); return () => ro.disconnect(); }, [ref, cb]);
}

/** A mirrored loudness outline from 64 peaks (library items; no audio involved). */
export function PeaksCanvas({ peaks, label, height = 34 }: { peaks: string | number[]; label: string; height?: number }) {
  const ref = useRef<HTMLCanvasElement>(null);
  const tick = useThemeTick();
  const draw = useCallback(() => {
    const c = ref.current; if (!c) return;
    const { x, W, H } = fit(c);
    const p = typeof peaks === "string" ? decodePeaks(peaks) : peaks;
    const mid = H / 2, bw = W / p.length;
    x.fillStyle = css(c, "--accent", "#a78bfa"); x.globalAlpha = 0.7;
    p.forEach((v, i) => { const h = Math.max(1, v * (H / 2 - 1)); x.fillRect(i * bw + 0.5, mid - h, Math.max(1, bw - 1), h * 2); });
  }, [peaks]);
  useEffect(() => { draw(); }, [draw, tick]);
  useResize(ref, draw);
  return <canvas ref={ref} className="sd-peaks" style={{ height }} role="img" aria-label={label} />;
}

/** A small waveform: PCM (min/max per column) placed at [start, start+dur] of `total` seconds, or silence as a bar. */
export function MiniWave({ pcm, start = 0, total, tone = "accent", silence = false, outline, diff, label }: {
  pcm: Float64Array | null; start?: number; total?: number; tone?: "accent" | "cyan" | "muted"; silence?: boolean; outline?: number[] | null; diff?: number[] | null; label?: string;
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const tick = useThemeTick();
  const draw = useCallback(() => {
    const c = ref.current; if (!c) return;
    const { x, W, H } = fit(c);
    x.fillStyle = css(c, "--well", "rgba(7,4,18,.55)"); x.fillRect(0, 0, W, H);
    const col = tone === "cyan" ? css(c, "--cyan", "#67e8f9") : tone === "muted" ? css(c, "--faint", "#666") : css(c, "--accent", "#a78bfa");
    const dur = pcm ? pcm.length / SAMPLE_RATE : 0;
    const T = Math.max(0.05, total ?? dur);
    const x0 = (start / T) * W, w = Math.max(2, ((silence || !pcm ? 0 : dur) / T) * W);
    const mid = H / 2, amp = H / 2 - 2;
    if (silence) { x.fillStyle = css(c, "--line-3", "#555"); x.fillRect(x0, mid - 1, Math.max(4, ((total ?? 1) > 0 ? w : 4)), 2); return; }
    if (outline && !pcm) {
      // library layer without audio: its loudness outline, hatched
      x.strokeStyle = col; x.globalAlpha = 0.6; x.setLineDash([2, 2]); x.beginPath();
      outline.forEach((v, i) => { const px = x0 + (i / outline.length) * W * 0.999, py = mid - v * amp; if (i) x.lineTo(px, py); else x.moveTo(px, py); });
      outline.slice().reverse().forEach((v, i) => { const px = x0 + ((outline.length - 1 - i) / outline.length) * W * 0.999; x.lineTo(px, mid + v * amp); });
      x.closePath(); x.stroke(); x.setLineDash([]); return;
    }
    if (!pcm || !pcm.length) return;
    let pk = 1e-9; for (let i = 0; i < pcm.length; i += 4) pk = Math.max(pk, Math.abs(pcm[i]));
    const sc = 0.95 / pk;
    x.fillStyle = col; x.globalAlpha = tone === "accent" ? 0.75 : 1;
    for (let i = 0; i < w; i++) {
      const a = Math.floor((i / w) * pcm.length), b = Math.floor(((i + 1) / w) * pcm.length);
      let m = 0; for (let k = a; k < Math.max(b, a + 1) && k < pcm.length; k++) m = Math.max(m, Math.abs(pcm[k]));
      x.fillRect(x0 + i, mid - m * sc * amp, 1, Math.max(1, m * sc * amp * 2));
    }
    if (diff) { // History: buckets that changed against the current version
      x.globalAlpha = 1; x.fillStyle = css(c, "--warn", "#ffb44f");
      diff.forEach((d, i) => { if (d) x.fillRect((i / diff.length) * W, H - 3, Math.max(1, W / diff.length - 0.5), 3); });
    }
  }, [pcm, start, total, tone, silence, outline, diff]);
  useEffect(() => { draw(); }, [draw, tick]);
  useResize(ref, draw);
  return <canvas ref={ref} className="sd-mini" role="img" aria-label={label ?? "Waveform"} />;
}

/** Buckets that differ (> 3 dB) between two renders, for the History tab. */
export const changedBuckets = (a: Float64Array | null, b: Float64Array | null, n = 48) => (a && b ? peakDiff(peaksOf(a, n), peaksOf(b, n)).map((d) => (d.changed ? 1 : 0)) : null);

export type WaveLayer = { layer: SoundLayer; libDuration: number | null; name: string; outline: number[] | null };
export type WaveProps = {
  pcm: Float64Array | null;
  sel: WaveLayer | null;
  others: { start: number; end: number }[];
  zoom: number; setZoom: (z: number) => void;
  playhead: () => number | null;
  onLayer: (l: SoundLayer, done: boolean) => void;
  onClickPlay: (fromS: number) => void;
  label: string;
};

/** The waveform editor. Drag the selected layer's edges to trim, its top corners to fade, its top line for gain, its body to move it. */
export function WaveformEditor({ pcm, sel, others, zoom, setZoom, playhead, onLayer, onClickPlay, label }: WaveProps) {
  const ref = useRef<HTMLCanvasElement>(null);
  const box = useRef<HTMLDivElement>(null);
  const tick = useThemeTick();
  const [scroll, setScroll] = useState(0);
  const [hover, setHover] = useState<number | null>(null);
  const drag = useRef<{ h: Handle; x: number; y: number; l: SoundLayer } | null>(null);
  const [cursor, setCursor] = useState("pointer");
  const selSpan = sel ? layerSpan(sel.layer, sel.libDuration) : null;
  const T = Math.max(0.4, selSpan?.end ?? 0, ...others.map((o) => o.end), pcm ? pcm.length / SAMPLE_RATE : 0) + 0.15;
  const geom = useCallback(() => {
    const r = ref.current!.getBoundingClientRect();
    const W = r.width, H = r.height, pps = ((W - 24) / T) * zoom, top = 26, bottom = H - 26;
    const mid = top + (bottom - top) / 2, amp = (bottom - top) / 2 - 4;
    return { W, H, pps, top, bottom, mid, amp, x: (s: number) => 12 + (s - scroll) * pps, s: (x: number) => (x - 12) / pps + scroll, gainY: (g: number) => mid - amp * Math.min(1, Math.pow(10, g / 20)) * 0.95 };
  }, [T, zoom, scroll]);
  useEffect(() => { if (zoom <= 1 && scroll) setScroll(0); }, [zoom, scroll]);

  const draw = useCallback(() => {
    const c = ref.current; if (!c) return;
    const { x } = fit(c);
    const g = geom(), { W, H, top, bottom, mid, amp } = g;
    const faint = css(c, "--faint", "#777"), line = css(c, "--line", "rgba(255,255,255,.08)"), line2 = css(c, "--line-2", "rgba(255,255,255,.14)");
    const cyan = css(c, "--cyan", "#67e8f9"), accent = css(c, "--accent", "#a78bfa"), accentInk = css(c, "--accent-ink", "#c4b5fd"), bad = css(c, "--bad", "#ff6b8a"), solid = css(c, "--solid", "#140f26");
    // ruler + grid
    x.font = "500 10px JetBrains Mono, ui-monospace, monospace"; x.textBaseline = "alphabetic";
    const step = g.pps > 900 ? 0.025 : g.pps > 420 ? 0.05 : g.pps > 170 ? 0.1 : g.pps > 70 ? 0.25 : 0.5;
    const near = (a: number, b: number) => Math.abs(a / b - Math.round(a / b)) < 1e-6;
    for (let s = Math.ceil(scroll / step) * step; g.x(s) < W; s += step) {
      const px = Math.round(g.x(s)) + 0.5;
      x.strokeStyle = line; x.globalAlpha = near(s, step * 2) ? 1 : 0.5; x.beginPath(); x.moveTo(px, top - 6); x.lineTo(px, bottom); x.stroke(); x.globalAlpha = 1;
      if (near(s, step * 2) || g.pps * step > 60) { x.fillStyle = faint; x.fillText(`${s.toFixed(step < 0.1 ? 3 : 2)}s`, px + 3, 14); }
    }
    x.strokeStyle = line2; x.beginPath(); x.moveTo(0, mid + 0.5); x.lineTo(W, mid + 0.5); x.stroke();
    // the selected layer: region, trim edges, fade + gain envelope
    if (sel && selSpan) {
      const x0 = g.x(selSpan.start), x1 = g.x(selSpan.end), fi = g.x(selSpan.start + selSpan.fadeIn), fo = g.x(selSpan.end - selSpan.fadeOut), gy = g.gainY(sel.layer.gain);
      x.fillStyle = "rgba(103,232,249,.075)"; x.fillRect(x0, top - 4, x1 - x0, bottom - top + 4);
      if (sel.outline && !pcm?.length) { /* no mix at all: still show the library outline */ }
      if (sel.outline) {
        x.strokeStyle = cyan; x.globalAlpha = 0.45; x.setLineDash([2, 3]); x.beginPath();
        const o = sel.outline, k = Math.min(1, Math.pow(10, sel.layer.gain / 20));
        o.forEach((v, i) => { const px = x0 + (i / (o.length - 1)) * (x1 - x0); const py = mid - v * amp * k; if (i) x.lineTo(px, py); else x.moveTo(px, py); });
        for (let i = o.length - 1; i >= 0; i--) x.lineTo(x0 + (i / (o.length - 1)) * (x1 - x0), mid + o[i] * amp * k);
        x.closePath(); x.stroke(); x.setLineDash([]); x.globalAlpha = 1;
      }
      x.strokeStyle = cyan; x.lineWidth = 1.5;
      x.beginPath(); x.moveTo(x0, top - 4); x.lineTo(x0, bottom); x.moveTo(x1, top - 4); x.lineTo(x1, bottom); x.stroke();
      x.setLineDash([4, 3]); x.beginPath(); x.moveTo(x0, mid + amp * 0.98); x.lineTo(fi, gy); x.lineTo(fo, gy); x.lineTo(x1, mid + amp * 0.98); x.stroke(); x.setLineDash([]);
      for (const hx of [fi, fo]) { x.fillStyle = solid; x.beginPath(); x.arc(hx, gy, 5, 0, Math.PI * 2); x.fill(); x.stroke(); }
      x.fillStyle = cyan; for (const hx of [x0, x1]) x.fillRect(hx - 3, mid - 14, 6, 28);
      x.font = "600 10px JetBrains Mono, ui-monospace, monospace"; x.fillText(`${sel.name}  ${sel.layer.gain > 0 ? "+" : ""}${sel.layer.gain} dB`, Math.max(4, x0 + 6), top + 8);
