    // playhead / hover
    const ph = playhead();
    if (ph != null) { const px = g.x(ph); x.strokeStyle = cyan; x.lineWidth = 2; x.shadowColor = cyan; x.shadowBlur = 8; x.beginPath(); x.moveTo(px, top - 8); x.lineTo(px, bottom + 2); x.stroke(); x.shadowBlur = 0; x.lineWidth = 1; }
    else if (hover != null) { x.strokeStyle = css(c, "--line-3", "rgba(167,139,250,.4)"); x.beginPath(); x.moveTo(hover, top - 6); x.lineTo(hover, bottom); x.stroke(); }
    void H;
  }, [geom, sel, selSpan, pcm, scroll, hover, playhead]);
  useEffect(() => { draw(); }, [draw, tick]);
  useResize(box, draw);
  // repaint while playing (the playhead moves)
  useEffect(() => { let raf = 0; const loop = () => { if (playhead() != null) draw(); raf = requestAnimationFrame(loop); }; raf = requestAnimationFrame(loop); return () => cancelAnimationFrame(raf); }, [draw, playhead]);
  useEffect(() => {
    const el = box.current; if (!el) return;
    const wheel = (e: WheelEvent) => {
      if (e.ctrlKey || e.metaKey) { e.preventDefault(); setZoom(Math.max(1, Math.min(8, zoom * (e.deltaY < 0 ? 1.25 : 0.8)))); return; }
      if (zoom > 1) { e.preventDefault(); setScroll((s) => Math.max(0, Math.min(T - T / zoom, s + (e.deltaY + e.deltaX) / geom().pps))); }
    };
    el.addEventListener("wheel", wheel, { passive: false });
    return () => el.removeEventListener("wheel", wheel);
  }, [zoom, setZoom, T, geom]);

  const handleAt = (e: React.PointerEvent): Handle | null => {
    if (!sel || !selSpan) return null;
    const r = ref.current!.getBoundingClientRect(), g = geom();
    return hitHandle(selSpan, g.x, e.clientX - r.left, e.clientY - r.top, { fadeRowY: g.gainY(sel.layer.gain), gainY: g.gainY(sel.layer.gain) });
  };
  const onDown = (e: React.PointerEvent) => {
    const h = handleAt(e);
    const r = ref.current!.getBoundingClientRect();
    if (!h || !sel) { onClickPlay(Math.max(0, geom().s(e.clientX - r.left))); return; }
    ref.current!.setPointerCapture(e.pointerId);
    drag.current = { h, x: e.clientX, y: e.clientY, l: sel.layer };
  };
  const onMove = (e: React.PointerEvent) => {
    const r = ref.current!.getBoundingClientRect();
    setHover(e.clientX - r.left);
    const d = drag.current;
    if (!d) { const h = handleAt(e); setCursor(h === "move" ? "grab" : h === "gain" ? "ns-resize" : h ? "ew-resize" : "pointer"); return; }
    if (!sel) return;
    const g = geom();
    let dg = 0;
    if (d.h === "gain") { const lin = Math.max(0.01, (g.mid - (e.clientY - r.top)) / (g.amp * 0.95)); dg = Math.round(Math.min(0, 20 * Math.log10(lin)) * 2) / 2 - d.l.gain; }
    onLayer(dragLayer(d.l, d.h, (e.clientX - d.x) / g.pps, sel.libDuration, dg), false);
  };
  const onUp = () => { if (drag.current && sel) onLayer(sel.layer, true); drag.current = null; };
  const onKey = (e: React.KeyboardEvent) => {
    if (!sel) return;
    const step = e.shiftKey ? 0.1 : 0.01;
    const k = e.key;
    let h: Handle | null = null, ds = 0;
    if (k === "ArrowLeft" || k === "ArrowRight") { h = e.altKey ? "end" : "move"; ds = k === "ArrowLeft" ? -step : step; }
    else if (k === "[" || k === "]") { h = "fadeIn"; ds = k === "[" ? -step : step; }
    else if (k === "{" || k === "}") { h = "fadeOut"; ds = k === "{" ? step : -step; }
    else if (k === "ArrowUp" || k === "ArrowDown") { e.preventDefault(); onLayer({ ...sel.layer, gain: Math.max(-40, Math.min(12, sel.layer.gain + (k === "ArrowUp" ? 0.5 : -0.5))) }, true); return; }
    if (!h) return;
    e.preventDefault();
    onLayer(dragLayer(sel.layer, h, ds, sel.libDuration), true);
  };
  return (
    <div className="sd-wbox" ref={box}>
      <canvas ref={ref} className="sd-wv" style={{ cursor }} tabIndex={0} role="application" aria-label={label} data-testid="waveform"
        aria-roledescription="waveform editor" aria-keyshortcuts="ArrowLeft ArrowRight Alt+ArrowLeft Alt+ArrowRight ArrowUp ArrowDown [ ] { }"
        onPointerDown={onDown} onPointerMove={onMove} onPointerUp={onUp} onPointerCancel={onUp} onPointerLeave={() => setHover(null)} onKeyDown={onKey} />
      {zoom > 1 && (
        <input type="range" className="sd-scroll" min={0} max={Math.max(0.001, T - T / zoom)} step={0.001} value={scroll} onChange={(e) => setScroll(Number(e.target.value))} aria-label="Scroll the waveform" />
      )}
    </div>
  );
}

