"use client";
// Cyrus SOUND STUDIO (R1b), full page. Layout and anatomy from the approved mockup
// (/root/agent-notes/cyrus-designs/sound-studio.html): left = the mod's sound sets and their event slots (+ the save
// bar); centre = event header (subtitle, volume slider), weighted variants, the Cyrus candidate bar, the waveform
// editor, the layer stack + variant FX and the prompt dock; right = loudness meters and the Library / Synth / Checks /
// History tabs. Narrow screens get the listen + approve view.
// The editing model is lib/cyrus/studios/sound-edit.ts (pure, unit-tested); audio is rendered in the browser with the
// same pure DSP as the render host (synth layers always; library layers only as gated previews when the licence is
// cleared), and "Render and preview" asks the render host for the authoritative file + numbers.
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { CyrusGlyph } from "@/components/cyrus/icons/CyrusLogo";
import { CyrusTokenEstimate } from "@/components/cyrus-tokens";
import { measure, soundQuality, type SoundMeasure, type SoundQualityReport } from "@/lib/cyrus/sound/measure";
import { SAMPLE_RATE, type Mono } from "@/lib/cyrus/sound/dsp";
import { synth } from "@/lib/cyrus/sound/synth";
import { SYNTH_PARAMS } from "@/lib/cyrus/sound/synth-params";
import { decodePeaks } from "@/lib/cyrus/sound/peaks";
import { MAX_LAYERS, MAX_VARIANTS, ROLE_PROFILE, SOUND_CATEGORIES, SYNTH_PRESETS, type SoundCategory, type SoundEvent, type SoundLayer, type SoundSpec, type SoundVariant, type SynthPreset } from "@/lib/cyrus/sound/spec";
import { canRedo, canUndo, historyInit, historyJump, historyPush, type History } from "@/lib/cyrus/studios/editor";
import {
  addEvent, addLayer, addVariant, applyCandidate, auditionRequest, browserVariant, layerKind, layerSpan, libIdOf, odds, previewKey, previewRequestOf, removeLayer, removeVariant,
  saveBlockers, setCategory, setKindOf, setLayer, setProcessing, setSubtitle, setWeight, silenceLayer, slotsFor, subtitleProblem, synthLayer, type SetKind,
} from "@/lib/cyrus/studios/sound-edit";
import { STUDIO_DEFAULTS } from "@/lib/cyrus/studios/access";
import { ApiError, studioApi, type AssetsView, type LibMeta, type LibraryItem, type SoundRenderView, type SoundSetEntry } from "./api";
import { SI, CREATURES_PATH } from "./icons";
import { LibraryBrowser } from "./LibraryBrowser";
import { StudioShell, useToast, type StudioMod } from "./StudioShell";
import { changedBuckets, MiniWave, WaveformEditor, type WaveLayer } from "./sound-canvas";
import { renderInBrowser, useAudio } from "./sound-audio";

type Cand = { requestId: string; status: "pending" | "ready" | "failed"; spec?: SoundSpec; event: string; summary: string; error?: string };
type Ed = { entry: SoundSetEntry; hist: History<SoundSpec>; dirty: boolean; accepted: { requestId: string; mode: "replace_event" | "replace_variant" | "add_variant" } | null; cand: Cand | null; coalesce: string | null };
type Sel = { set: string; event: string; vi: number; li: number; cand: boolean };
type HostRender = { key: string; view: SoundRenderView; pcm: (Mono | null)[] };

const ENC = { codec: "vorbis", channels: 1, sampleRate: SAMPLE_RATE };
const vClass = (v: string) => (v === "pass" ? "ok" : v === "warn" ? "warn" : v === "fail" ? "bad" : "dim");
const human = (id: string) => { const w = id.replace(/_[0-9a-f]{4}$/, "").split("_"); const s = w.join(" "); return s.charAt(0).toUpperCase() + s.slice(1); };
const fmtK = (k: string, x: number) => (k === "gain" ? `${x > 0 ? "+" : ""}${x} dB` : k === "pitch" ? `${x > 0 ? "+" : ""}${x} st` : k === "start" ? `${Math.round(x * 1000)} ms` : `${x}s`);
const rangeStyle = (v: number, lo: number, hi: number) => ({ ["--p" as string]: `${Math.max(0, Math.min(100, ((v - lo) / (hi - lo)) * 100))}%` });
const CAT_LABEL: Record<string, string> = { ui_alerts: "UI", creatures_voices: "Creature", music_stingers: "Music", environment_ambience: "Ambience", movement: "Movement", doors_mechanisms: "Door", impacts_destruction: "Impact", weapons: "Weapon", crowd_reactions: "Crowd", magic_energy: "Magic" };

function edFor(entry: SoundSetEntry, label: string, summaries: Record<string, string>): Ed {
  const c = entry.candidates[entry.candidates.length - 1];
  return { entry, hist: historyInit(label, entry.spec), dirty: false, accepted: null, coalesce: null, cand: c ? { requestId: c.buildId, status: "ready", spec: c.spec, event: c.event, summary: summaries[c.buildId] ?? "Cyrus edit from a change build" } : null };
}

export function SoundStudio({ mod, initialSet, initialEvent }: { mod: StudioMod; initialSet: string | null; initialEvent: string | null }) {
  return (
    <StudioShell mod={mod} current="Sound Studio" studio="sound">
      <Body mod={mod} initialSet={initialSet} initialEvent={initialEvent} />
    </StudioShell>
  );
}

function Body({ mod, initialSet, initialEvent }: { mod: StudioMod; initialSet: string | null; initialEvent: string | null }) {
  const [view, setView] = useState<AssetsView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [eds, setEds] = useState<Record<string, Ed>>({});
  const [sel, setSel] = useState<Sel | null>(null);
  const load = useCallback(async (keep?: { set: string; label: string }) => {
    try {
      const v = await studioApi.assets(mod.rootId);
      setView(v);
      setEds((prev) => {
        const next: Record<string, Ed> = {};
        for (const s of v.soundSets) next[s.set] = keep && keep.set === s.set ? edFor(s, keep.label, v.candidateSummaries) : prev[s.set]?.dirty ? { ...prev[s.set], entry: s } : edFor(s, `Opened revision ${v.revisionSeq[s.revisionId] ?? ""}`.trim(), v.candidateSummaries);
        return next;
      });
      setSel((cur) => {
        if (cur && v.soundSets.some((s) => s.set === cur.set)) return cur;
        const s = v.soundSets.find((x) => x.set === initialSet) ?? v.soundSets[0];
        if (!s) return null;
        const e = s.spec.events.find((x) => x.event === initialEvent) ?? s.spec.events.find((x) => s.candidates.some((c) => c.event === x.event)) ?? s.spec.events[0];
        return { set: s.set, event: e?.event ?? "", vi: 0, li: 0, cand: false };
      });
    } catch (e) { setErr((e as Error).message); }
  }, [mod.rootId, initialSet, initialEvent]);
  useEffect(() => { void load(); }, [load]);
  if (err) return <div className="cys-empty" style={{ margin: "auto" }}><SI n="warn" /><p>{err}</p></div>;
  if (!view) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Loading this mod&apos;s sounds…</div>;
  if (!view.project || !view.soundSets.length || !sel || !eds[sel.set]) {
    return (
      <main className="sd-ws" style={{ gridTemplateColumns: "minmax(0,1fr) 340px" }}>
        <section className="sd-col"><div className="cys-panel cys-glass" style={{ flex: 1, display: "grid", placeItems: "center" }}>
          <div className="cys-empty" style={{ maxWidth: 440 }}><SI n="wave" /><p><b>This mod has no custom sounds yet.</b></p><p className="cys-hint">Ask Cyrus for them in your next change (for example “give the banshee its own hurt and death sounds”). Each sound set then opens here with its events, variants and layers.</p></div>
        </div></section>
        <section className="sd-col"><div className="cys-panel cys-glass" style={{ flex: 1 }}>{view.project && <LibraryBrowser kind="sound" projectId={view.project.id} onUse={async () => { throw new ApiError(409, "no_set", "Library sounds are added to an event of a sound set. This mod has none yet.", {}); }} />}</div></section>
      </main>
    );
  }
  return <Editor mod={mod} view={view} eds={eds} setEds={setEds} sel={sel} setSel={setSel} reload={load} />;
}

function Editor({ mod, view, eds, setEds, sel, setSel, reload }: {
  mod: StudioMod; view: AssetsView; eds: Record<string, Ed>; setEds: React.Dispatch<React.SetStateAction<Record<string, Ed>>>;
  sel: Sel; setSel: React.Dispatch<React.SetStateAction<Sel | null>>; reload: (keep?: { set: string; label: string }) => Promise<void>;
}) {
  const toast = useToast();
  const audio = useAudio();
  const project = view.project!;
  const caps = view.sound ?? { libraryCleared: false, audition: { library: false, synth: true as const, reason: "Library audition is off until the owner confirms the sound licence." }, render: null, renderOff: "not wired", candidates: null };
  const ed = eds[sel.set];
  const spec = ed.hist.steps[ed.hist.at].snap;
  const ei = spec.events.findIndex((e) => e.event === sel.event);
  const ev: SoundEvent | null = ei >= 0 ? spec.events[ei] : null;
  const kinds = useMemo(() => Object.fromEntries(view.soundSets.map((s) => [s.set, setKindOf(eds[s.set]?.hist.steps[eds[s.set].hist.at].snap ?? s.spec, view.textures.map((t) => t.key))])) as Record<string, SetKind>, [view, eds]);
  const slot = slotsFor(spec, kinds[sel.set] ?? "other").find((s) => s.event === sel.event) ?? null;
  const role = ev?.role ?? slot?.role ?? "other";
  const cand = ed.cand;
  const candEv = cand?.status === "ready" && cand.spec ? cand.spec.events.find((e) => e.event === cand.event) ?? null : null;
  const showCand = sel.cand && !!candEv && cand?.event === sel.event;
  const variant: SoundVariant | null = showCand ? candEv!.variants[0] : ev?.variants[Math.min(sel.vi, (ev?.variants.length ?? 1) - 1)] ?? null;
  const vi = Math.min(sel.vi, Math.max(0, (ev?.variants.length ?? 1) - 1));
  const li = variant ? Math.min(sel.li, Math.max(0, variant.layers.length - 1)) : 0;
  const pick = (p: Partial<Sel>) => setSel((s) => (s ? { ...s, ...p } : s));

  // ---------------------------------------------------------------- library metadata + gated previews
  const [libMeta, setLibMeta] = useState<Record<string, LibMeta>>(view.soundLibrary ?? {});
  useEffect(() => { setLibMeta((m) => ({ ...m, ...(view.soundLibrary ?? {}) })); }, [view.soundLibrary]);
  const durOf = useCallback((id: string) => libMeta[id]?.duration ?? null, [libMeta]);
  const [previews, setPreviews] = useState<Map<string, Mono>>(new Map());
  const [previewErr, setPreviewErr] = useState<string | null>(null);
  const inflight = useRef(new Set<string>());
  const wanted = useMemo(() => (variant ? variant.layers.map((l) => previewRequestOf(l, libIdOf(l) ? durOf(libIdOf(l)!) : null)) : []), [variant, durOf]);
  useEffect(() => {
    if (!caps.audition.library) return;
    const t = window.setTimeout(() => {
      for (const r of wanted) {
        if (!r) continue;
        const k = previewKey(r);
        if (previews.has(k) || inflight.current.has(k)) continue;
        inflight.current.add(k);
        studioApi.preview(r).then((b) => audio.decode(b)).then((pcm) => setPreviews((m) => new Map(m).set(k, pcm))).catch((e) => setPreviewErr(e instanceof ApiError ? e.message : "A library preview didn't load.")).finally(() => inflight.current.delete(k));
      }
    }, 260);
    return () => window.clearTimeout(t);
  }, [wanted, caps.audition.library, previews, audio]);
  const buffersFor = useCallback((v: SoundVariant) => {
    const m = new Map<string, Mono>();
    v.layers.forEach((l, i) => { const r = previewRequestOf(l, libIdOf(l) ? durOf(libIdOf(l)!) : null); const pcm = r ? previews.get(previewKey(r)) : undefined; if (pcm) m.set(`__p${i}`, pcm); });
    return m;
  }, [previews, durOf]);
  const renderV = useCallback((v: SoundVariant, r: typeof role) => {
    const bufs = buffersFor(v);
    const bv = browserVariant(v, (i) => bufs.has(`__p${i}`), durOf);
    return { ...renderInBrowser(bv.variant, r, bufs, [...bufs.keys()].join(",") + "|" + [...previews.keys()].length), silenced: bv.silenced };
  }, [buffersFor, durOf, previews]);
  const R = useMemo(() => (variant && variant.layers.length ? renderV(variant, role) : null), [variant, role, renderV]);
  const layerPcm = useCallback((v: SoundVariant, i: number) => renderV({ ...v, layers: [{ ...v.layers[i], start: 0 }], processing: { lowpass: null, highpass: null, reverb: 0, echo: null } }, role).pcm, [renderV, role]);

  // ---------------------------------------------------------------- the render host ("Render and preview")
  const [host, setHost] = useState<HostRender | null>(null);
  const [rendering, setRendering] = useState(false);
  const evKey = ev ? JSON.stringify(ev) : "";
  const hostNow = host && host.key === `${sel.set}|${evKey}` && !showCand ? host : null;
  const renderOnHost = async () => {
    if (!ev) return;
    const blockers = saveBlockers({ ...spec, events: [ev] });
    if (blockers.length) { toast(blockers[0].message, true); return; }
    setRendering(true);
    try {
      const r = await studioApi.renderSound(project.id, sel.set, spec, ev.event);
      const pcm = await Promise.all(r.files.map(async (f) => { try { return await audio.decode(Uint8Array.from(atob(f.audio), (ch) => ch.charCodeAt(0)).buffer); } catch { return null; } }));
      setHost({ key: `${sel.set}|${evKey}`, view: r, pcm });
      toast(r.fake ? "Rendered by the development stand-in host (real DSP, WAV instead of Ogg)." : `Rendered on ${r.host}: numbers below are measured on the encoded Ogg.`);
    } catch (e) { toast(e instanceof ApiError ? e.message : "The render didn't come through.", true); }
    finally { setRendering(false); }
  };
  const hostFile = hostNow?.view.files[vi] ?? null;
  const M: SoundMeasure | null = hostFile ? (hostFile.measure as SoundMeasure) : R && R.pcm.length ? measure(R.pcm) : null;
  const Q: SoundQualityReport | null = hostFile ? (hostFile.quality as SoundQualityReport) : M ? soundQuality(M, ENC, role) : null;
  const gainInfo = hostFile ? (hostFile.render as { gainDb: number; peakLimited: boolean }) : R ? { gainDb: R.gainDb, peakLimited: R.peakLimited } : null;

  // ---------------------------------------------------------------- edits + undo
  const gesture = useRef<string | null>(null);
  const commit = useCallback((label: string, next: SoundSpec, coalesce?: string, extra: Partial<Ed> = {}) => {
    setEds((p) => {
      const e = p[sel.set];
      let hist: History<SoundSpec>;
      if (coalesce && e.coalesce === coalesce && e.hist.at > 0) hist = { ...e.hist, steps: [...e.hist.steps.slice(0, e.hist.at), { label, snap: next }] };
      else hist = historyPush(e.hist, label, next);
      return { ...p, [sel.set]: { ...e, hist, dirty: true, coalesce: coalesce ?? null, ...extra } };
    });
  }, [sel.set]);
  const endGesture = () => { gesture.current = null; setEds((p) => ({ ...p, [sel.set]: { ...p[sel.set], coalesce: null } })); };
  const undo = () => setEds((p) => { const e = p[sel.set]; return canUndo(e.hist) ? { ...p, [sel.set]: { ...e, hist: historyJump(e.hist, e.hist.at - 1), dirty: true, coalesce: null } } : p; });
  const redo = () => setEds((p) => { const e = p[sel.set]; return canRedo(e.hist) ? { ...p, [sel.set]: { ...e, hist: historyJump(e.hist, e.hist.at + 1), dirty: true, coalesce: null } } : p; });
  /** the current event index, adding the slot's event first when it isn't used yet */
  const ensureEvent = (): { s: SoundSpec; e: number } | null => {
    if (ev) return { s: spec, e: ei };
    if (!slot) return null;
    const r = addEvent(spec, slot.event, slot.role);
    if (!r.ok) { toast(r.error, true); return null; }
    return { s: r.spec, e: r.index! };
  };
  const addL = (layer: SoundLayer, label: string) => {
    if (showCand) { toast("Accept the candidate (or stop comparing) before adding layers.", true); return; }
    const t = ensureEvent(); if (!t) return;
    const r = addLayer(t.s, t.e, vi, layer);
    if (!r.ok) { toast(r.error, true); return; }
    commit(label, r.spec);
    pick({ li: r.index!, vi: Math.min(vi, Math.max(0, r.spec.events[t.e].variants.length - 1)) });
  };
  const onLayer = (l: SoundLayer, done: boolean) => {
    if (showCand || !ev || !variant) return;
    const before = variant.layers[li];
    const what = l.gain !== before.gain ? "Gain" : l.fadeIn !== before.fadeIn || l.fadeOut !== before.fadeOut ? "Fade" : l.trimStart !== before.trimStart || l.length !== before.length ? "Trim" : "Move";
    if (!gesture.current) gesture.current = `drag${Date.now()}`;
    commit(`${what} ${nameOf(before)}`, setLayer(spec, ei, vi, li, l), gesture.current);
    if (done) endGesture();
  };
  const nameOf = (l: SoundLayer) => (l.source === "silence" ? "silence" : l.source.startsWith("synth:") ? `synth · ${l.source.slice(6)}` : human(libIdOf(l)!));

  // ---------------------------------------------------------------- playback + keys
  const playMix = useCallback((fromS = 0) => {
    if (audio.playing === "mix") { audio.stop(); return; }
    const pcm = hostNow?.pcm[vi] ?? R?.pcm;
    if (!pcm || !pcm.length) { toast("Nothing to play yet: add a layer.", true); return; }
    audio.play(pcm, "mix", { offsetS: fromS });
  }, [audio, R, hostNow, vi, toast]);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const t = e.target as HTMLElement | null;
      if (t && (t.tagName === "INPUT" || t.tagName === "TEXTAREA" || t.tagName === "SELECT" || t.isContentEditable)) return;
      const k = e.key.toLowerCase();
      if ((e.ctrlKey || e.metaKey) && k === "z") { e.preventDefault(); if (e.shiftKey) redo(); else undo(); return; }
      if ((e.ctrlKey || e.metaKey) && k === "y") { e.preventDefault(); redo(); return; }
      if (e.ctrlKey || e.metaKey || e.altKey) return;
      if (e.code === "Space" && t?.tagName !== "BUTTON") { e.preventDefault(); playMix(); }
      else if (k === "l") audio.setLoop(!audio.loop);
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });
  useEffect(() => { audio.stop(); /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [sel.set, sel.event, sel.vi, sel.cand]);

  // ---------------------------------------------------------------- save, candidates
  const [saving, setSaving] = useState(false);
  const blockers = useMemo(() => saveBlockers(spec), [spec]);
  const save = async (o: { spec?: SoundSpec; accept?: { requestId: string; mode: "replace_event" | "replace_variant" | "add_variant" } } = {}) => {
    const sp = o.spec ?? spec;
    const b = saveBlockers(sp);
    if (b.length) { toast(`Can't save yet. ${b[0].message}`, true); const ix = sp.events.findIndex((e) => e.event === b[0].event); if (ix >= 0) pick({ event: sp.events[ix].event, cand: false }); window.setTimeout(() => document.getElementById("sd-sub")?.focus(), 60); return; }
    setSaving(true);
    try {
      const acc = o.accept ?? ed.accepted;
      const r = await studioApi.saveSound(project.id, sel.set, { spec: sp, baseAssetId: ed.entry.assetId, expectedHeadId: view.headRevisionId, ...(acc ? { acceptCandidate: acc.requestId, mode: acc.mode } : {}) });
      toast(`Saved as revision ${r.seq}. Servers get it with the next build: the build renders these sounds and rebuilds the resource pack.`);
      await reload({ set: sel.set, label: `Saved revision ${r.seq}` });
    } catch (e) { toast(e instanceof ApiError ? e.message : "Couldn't save. Nothing was changed.", true); }
    finally { setSaving(false); }
  };
  const [prompt, setPrompt] = useState("");
  const [busy, setBusy] = useState(false);
  const pollRef = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(pollRef.current), []);
  const poll = useCallback((set: string, requestId: string, tries = 0) => {
    pollRef.current = window.setTimeout(async () => {
      try {
        const r = await studioApi.pollSoundCandidate(project.id, set, requestId);
        if (r.status === "pending" && tries < 400) return poll(set, requestId, tries + 1);
        setBusy(false);
        setEds((p) => { const e = p[set]; if (!e?.cand || e.cand.requestId !== requestId) return p; return { ...p, [set]: { ...e, cand: r.status === "ready" ? { ...e.cand, status: "ready", spec: r.spec, event: r.event } : { ...e.cand, status: "failed", error: r.status === "failed" ? r.error : "Cyrus took too long. Try again." } } }; });
        if (r.status === "ready") { setSel((s) => (s && s.set === set ? { ...s, event: r.event, cand: true, li: 0 } : s)); toast("Cyrus made a candidate. Audition it against your version, then keep part of it or reject it."); }
      } catch (e) { setBusy(false); toast((e as Error).message, true); }
    }, tries ? 1500 : 900);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [project.id]);
  const ask = async () => {
    const p = prompt.trim();
    if (p.length < 4) { toast("Describe the change in a few words.", true); return; }
    if (!ev || !ev.variants.length) { toast(`${sel.event} has no sound yet. Add a first layer, then ask Cyrus to refine it.`, true); return; }
    if (ed.dirty) { toast("Save your edits first: Cyrus works from the saved version of this set.", true); return; }
    setBusy(true); setPrompt("");
    try {
      const r = await studioApi.requestSoundCandidate(project.id, sel.set, ev.event, p);
      setEds((x) => ({ ...x, [sel.set]: { ...x[sel.set], cand: { requestId: r.requestId, status: "pending", event: ev.event, summary: p } } }));
      poll(sel.set, r.requestId);
    } catch (e) { setBusy(false); toast(e instanceof ApiError ? e.message : "Cyrus couldn't start that edit.", true); }
  };
  const applyCand = (mode: "replace_event" | "replace_variant" | "add_variant") => {
    if (!cand || !candEv || !ev) return;
    const r = applyCandidate(spec, ei, candEv, mode, vi);
    if (!r.ok) { toast(r.error, true); return; }
    commit(mode === "add_variant" ? `Added Cyrus's take as V${ev.variants.length + 1}` : mode === "replace_variant" ? `Replaced V${vi + 1} with Cyrus's take` : "Accepted Cyrus's version", r.spec, undefined, { cand: null, accepted: { requestId: cand.requestId, mode } });
    pick({ cand: false, vi: mode === "add_variant" ? ev.variants.length : vi, li: 0 });
    toast("Applied as one edit step. Save to keep it; undo brings your version back.");
  };
  const reject = async () => {
    if (!cand) return;
    if (!ed.dirty && cand.status === "ready") {
      try { await studioApi.rejectSoundCandidate(project.id, sel.set, cand.requestId, view.headRevisionId); toast("Candidate rejected. Your sound stays as it is (recorded in History)."); pick({ cand: false }); await reload({ set: sel.set, label: "Rejected a Cyrus candidate" }); }
      catch (e) { toast((e as Error).message, true); }
      return;
    }
    setEds((x) => ({ ...x, [sel.set]: { ...x[sel.set], cand: null } }));
    pick({ cand: false });
    toast(cand.status === "ready" ? "Candidate discarded here. Save your edits to record decisions." : "Candidate dismissed");
  };
  const ab = () => {
    if (!ev || !candEv) return;
    const a = renderV(ev.variants[vi] ?? ev.variants[0], role).pcm, b = renderV(candEv.variants[0], role).pcm;
    audio.play(a, "ab-a", { loop: false, onEnd: () => window.setTimeout(() => audio.play(b, "ab-b", { loop: false }), 250) });
    toast(`Playing V${vi + 1}, then the candidate`);
  };

  // ---------------------------------------------------------------- side data
  const [tab, setTab] = useState<"lib" | "syn" | "qc" | "hist">("lib");
  const verdicts = useMemo(() => {
    const out: Record<string, string> = {};
    for (const s of view.soundSets) {
      const sp = eds[s.set]?.hist.steps[eds[s.set].hist.at].snap ?? s.spec;
      for (const e of sp.events) {
        if (subtitleProblem(e.subtitle)) { out[`${s.set}.${e.event}`] = "bad"; continue; }
        let worst = "ok";
        for (const v of e.variants) { const r = renderV(v, e.role); const q = r.pcm.length ? soundQuality(measure(r.pcm), ENC, e.role) : null; if (!q || q.verdict === "fail") worst = "bad"; else if (q.verdict === "warn" && worst === "ok") worst = "warn"; }
        out[`${s.set}.${e.event}`] = e.variants.length ? worst : "";
      }
    }
    return out;
  }, [view.soundSets, eds, renderV]);
  const dirtySets = Object.entries(eds).filter(([, e]) => e.dirty).map(([k]) => k);
  const est = STUDIO_DEFAULTS.showEditEstimate ? <CyrusTokenEstimate text={prompt} model="saka" change /> : null;
  const prof = ROLE_PROFILE[role];
  const libSilenced = R?.silenced ?? 0;
  const seqOf = (rev: string) => view.revisionSeq[rev] ?? null;

  const curLayer = variant?.layers[li] ?? null;
  const waveSel: WaveLayer | null = curLayer ? { layer: curLayer, libDuration: libIdOf(curLayer) ? durOf(libIdOf(curLayer)!) : null, name: nameOf(curLayer), outline: libIdOf(curLayer) && libMeta[libIdOf(curLayer)!]?.peaks && !buffersFor(variant!).has(`__p${li}`) ? decodePeaks(libMeta[libIdOf(curLayer)!]!.peaks!) : null } : null;

  return (
    <>
      <main className="sd-ws" aria-label="Sound Studio">
        {/* LEFT: events */}
        <section className="sd-col">
          <div className="cys-panel cys-glass sd-events">
            <div className="cys-ph"><span className="cys-eyebrow">Sound events</span><span className="cys-tag">{view.soundSets.reduce((a, s) => a + (eds[s.set]?.hist.steps[eds[s.set].hist.at].snap ?? s.spec).events.filter((e) => e.variants.length).length, 0)}</span></div>
            <div className="sd-evscroll">
              {view.soundSets.map((s) => {
                const sp = eds[s.set]?.hist.steps[eds[s.set].hist.at].snap ?? s.spec;
                const k = kinds[s.set];
                return (
                  <div className="sd-set" key={s.set}>
                    <div className="sd-set-h">{k === "mob" ? <svg className="cys-i" viewBox="0 0 24 24" aria-hidden dangerouslySetInnerHTML={{ __html: CREATURES_PATH }} /> : <SI n="cube" />}<b>{s.set}</b><small>{k === "mob" ? "mob" : k === "item" ? "item" : "sound set"}{eds[s.set]?.dirty ? " · unsaved" : ""}</small></div>
                    {slotsFor(sp, k).map((sl) => {
                      const e = sl.index != null ? sp.events[sl.index] : null;
                      const empty = !e || !e.variants.length, missing = !!e && !!subtitleProblem(e.subtitle);
                      const on = s.set === sel.set && sl.event === sel.event;
                      const hasCand = eds[s.set]?.cand?.event === sl.event && eds[s.set]?.cand?.status !== "failed";
                      return (
                        <button key={sl.event} type="button" className={`sd-slot ${on ? "on" : ""} ${empty ? "empty" : ""}`} onClick={() => setSel({ set: s.set, event: sl.event, vi: 0, li: 0, cand: false })} aria-current={on} data-testid={`slot-${s.set}-${sl.event}`}>
                          <span><b>{sl.event}{sl.role !== sl.event && <span className="cys-tag dim">{sl.role}</span>}{hasCand && <SI n="sparkle" className="ai" />}</b>
                            <small className={missing ? "err" : ""}>{!e ? "Not used · add a sound" : missing ? "Subtitle required" : e.subtitle}{e && empty && !missing ? " · no sound yet" : ""}</small></span>
                          <span className="vc">{e && e.variants.length ? `${e.variants.length}×` : ""}</span>
                          <span className={`cys-dot ${missing ? "bad" : verdicts[`${s.set}.${sl.event}`] ?? ""}`} title={missing ? "Subtitle required" : e?.variants.length ? `Quality ${verdicts[`${s.set}.${sl.event}`] === "ok" ? "pass" : verdicts[`${s.set}.${sl.event}`]}` : "Not used"} />
                        </button>
                      );
                    })}
                  </div>
                );
              })}
              <p className="cys-hint" style={{ padding: "4px 16px 12px", margin: 0 }}>Each event becomes <span className="mono">{project.namespace}:&lt;set&gt;.&lt;event&gt;</span> with 1-4 weighted variants and a subtitle. Mods play their own keys, so vanilla sounds never overlap.</p>
            </div>
            <div className="sd-savebar">
              <div className="row"><span className="st">{ed.dirty ? <><b>{sel.set}</b> · {ed.hist.at} unsaved edit{ed.hist.at === 1 ? "" : "s"}</> : <>All saved · revision {seqOf(ed.entry.revisionId) ?? "?"}</>}</span>
                <button type="button" className="cys-ib sm" onClick={undo} disabled={!canUndo(ed.hist)} title="Undo (Ctrl Z)" aria-label="Undo"><SI n="undo" /></button>
                <button type="button" className="cys-ib sm" onClick={redo} disabled={!canRedo(ed.hist)} title="Redo (Ctrl Shift Z)" aria-label="Redo"><SI n="redo" /></button>
              </div>
              {ed.dirty && blockers.length > 0 && <p className="err" role="alert">{blockers[0].message}{blockers.length > 1 ? ` (+${blockers.length - 1} more)` : ""}</p>}
              {dirtySets.filter((x) => x !== sel.set).length > 0 && <p className="cys-hint" style={{ margin: 0 }}>Also unsaved: {dirtySets.filter((x) => x !== sel.set).join(", ")}</p>}
              <button type="button" className={`cys-btn sm ${ed.dirty ? "primary" : ""}`} disabled={!ed.dirty || saving} onClick={() => void save()} data-testid="save-revision">{saving ? "Saving…" : "Save revision"}</button>
            </div>
          </div>
        </section>

        {/* CENTRE */}
        <section className="sd-col">
          <div className="sd-evh cys-glass">
            <div className="key"><b>{sel.set}.{sel.event}<span className="cys-tag acc">{role}</span></b><code>{project.namespace}:{sel.set}.{sel.event}</code></div>
            <div className="sub">
              <label className="sd-lbl" htmlFor="sd-sub">Subtitle<span className="req">*</span> <span className="cys-hint" style={{ fontWeight: 400 }}>what players with subtitles on read</span></label>
              <div className="rowf">
                <input id="sd-sub" className={`cys-field ${ev && subtitleProblem(ev.subtitle) ? "err" : ""}`} value={ev?.subtitle ?? ""} placeholder={`e.g. ${sel.set.charAt(0).toUpperCase() + sel.set.slice(1).replace(/_/g, " ")} ${role === "death" ? "collapses" : role === "hurt" ? "shrieks" : "sounds"}`} maxLength={60} aria-required="true"
                  aria-invalid={!!ev && !!subtitleProblem(ev.subtitle)} aria-describedby="sd-sub-err" data-testid="subtitle"
                  onChange={(e) => { const t = ensureEvent(); if (!t) return; commit(`Subtitle of ${sel.event}`, setSubtitle(t.s, t.e, e.target.value), `sub:${sel.set}.${sel.event}`); }} onBlur={() => setEds((p) => ({ ...p, [sel.set]: { ...p[sel.set], coalesce: null } }))} />
                <span className="langkey">subtitles.{project.namespace}.{sel.set}.{sel.event}</span>
              </div>
              {ev && subtitleProblem(ev.subtitle) && <div id="sd-sub-err" className="cys-hint err" role="alert" style={{ marginTop: 5 }}>{subtitleProblem(ev.subtitle)}</div>}
            </div>
            <div><label className="sd-lbl" htmlFor="sd-cat">Volume slider</label>
              <select id="sd-cat" className="cys-field sd-catf" value={ev?.category ?? "hostile"} disabled={!ev} onChange={(e) => commit(`Volume slider ${e.target.value}`, setCategory(spec, ei, e.target.value as SoundCategory))}>
                {SOUND_CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
              </select></div>
          </div>

          {ev && ev.variants.length > 0 && (
            <div className="sd-vars">
              {ev.variants.map((v, i) => <button key={i} type="button" className={`sd-var ${!showCand && i === vi ? "on" : ""}`} onClick={() => pick({ vi: i, li: 0, cand: false })} aria-pressed={!showCand && i === vi}>V{i + 1}<span className="w">w {v.weight}</span></button>)}
              {cand && cand.event === sel.event && (cand.status === "ready" ? <button type="button" className={`sd-var cand ${showCand ? "on" : ""}`} onClick={() => pick({ cand: true, li: 0 })} data-testid="candidate-chip"><SI n="sparkle" />Candidate</button> : cand.status === "pending" ? <span className="sd-var cand pend"><SI n="sparkle" />Cyrus is working…</span> : null)}
              {!showCand && ev.variants.length < MAX_VARIANTS && <button type="button" className="cys-btn sm ghost" onClick={() => { const r = addVariant(spec, ei, vi); if (!r.ok) return toast(r.error, true); commit(`Added V${r.index! + 1}`, r.spec); pick({ vi: r.index!, li: 0 }); toast("Variant added: a copy with new synth seeds. Tweak it so players hear a difference."); }}><SI n="plus" />Variant</button>}
              {!showCand && <span className="sd-wstep"><button type="button" className="cys-ib sm" aria-label="Lower weight" onClick={() => commit(`Weight V${vi + 1}`, setWeight(spec, ei, vi, ev.variants[vi].weight - 1), `w:${ei}:${vi}`)}><SI n="minus" /></button><span>weight {ev.variants[vi].weight}</span><button type="button" className="cys-ib sm" aria-label="Raise weight" onClick={() => commit(`Weight V${vi + 1}`, setWeight(spec, ei, vi, ev.variants[vi].weight + 1), `w:${ei}:${vi}`)}><SI n="plus" /></button></span>}
              {!showCand && ev.variants.length > 1 && <button type="button" className="cys-ib sm" title={`Remove V${vi + 1}`} aria-label={`Remove V${vi + 1}`} onClick={() => { commit(`Removed V${vi + 1}`, removeVariant(spec, ei, vi)); pick({ vi: Math.max(0, vi - 1), li: 0 }); }}><SI n="trash" /></button>}
              <span className="odds">players hear {odds(ev).map((p, i) => `V${i + 1} ${p}%`).join(" · ")}</span>
            </div>
          )}
          {showCand && cand && (
            <div className="sd-candbar" data-testid="candidate">
              <SI n="sparkle" /><span><b>Cyrus candidate</b> for {sel.set}.{sel.event} · “{cand.summary}”. Not applied: audition it against V{vi + 1}.</span><span className="sp" />
              <button type="button" className="cys-btn xs" onClick={ab}><SI n="play" />A / B with V{vi + 1}</button>
              <button type="button" className="cys-btn xs primary" onClick={() => applyCand("replace_variant")} data-testid="accept-candidate">Replace V{vi + 1}</button>
              {ev && ev.variants.length < MAX_VARIANTS && <button type="button" className="cys-btn xs" onClick={() => applyCand("add_variant")}>Add as V{ev.variants.length + 1}</button>}
              {candEv && candEv.variants.length > 1 && <button type="button" className="cys-btn xs" onClick={() => applyCand("replace_event")}>Use all {candEv.variants.length}</button>}
              <button type="button" className="cys-btn xs ghost" onClick={() => void reject()} data-testid="reject-candidate">Reject</button>
            </div>
          )}

          <div className="cys-panel cys-glass sd-wave">
            <div className="sd-wtools">
              <button type="button" className="sd-play" onClick={() => playMix()} aria-label={audio.playing === "mix" ? "Pause (Space)" : "Play (Space)"} data-testid="play"><SI n={audio.playing === "mix" ? "pause" : "play"} /></button>
              <button type="button" className={`cys-ib ${audio.loop ? "on" : ""}`} onClick={() => audio.setLoop(!audio.loop)} aria-label="Loop (L)" aria-pressed={audio.loop} title="Loop (L)"><SI n="loop" /></button>
              <Clock audio={audio} total={(hostNow?.pcm[vi] ?? R?.pcm)?.length ?? 0} />
              <span className="sp" />
              {curLayer && <span className="lbl2"><span className="cys-dot live" />{nameOf(curLayer)} · trim {curLayer.trimStart.toFixed(2)}s · fade {curLayer.fadeIn}/{curLayer.fadeOut} ms</span>}
              <ZoomCtl zoom={zoom} setZoom={setZoom} />
            </div>
            {variant && variant.layers.length ? (
              <WaveformEditor pcm={hostNow?.pcm[vi] ?? R?.pcm ?? null} sel={waveSel} others={variant.layers.map((l) => { const sp = layerSpan(l, libIdOf(l) ? durOf(libIdOf(l)!) : null); return { start: sp.start, end: sp.end }; })} zoom={zoom} setZoom={setZoom}
                playhead={() => audio.position("mix")} onLayer={onLayer} onClickPlay={(s) => { if (audio.playing === "mix") audio.stop(); else playMix(s); }} label={`Waveform of ${sel.set}.${sel.event} ${showCand ? "candidate" : `V${vi + 1}`}. Arrow keys move the selected layer, Alt+arrows trim its end, [ ] fade in, { } fade out, up and down change its gain.`} />
            ) : (
              <div className="sd-wempty"><SI n="wave" /><p><b>{sel.event}</b> {ev ? "has no sound yet." : "isn't used yet."} Add a synth preset or a library sound below, or ask Cyrus.</p></div>
            )}
            <div className="sd-wlegend"><span><i style={{ background: "var(--accent)" }} />mix players hear{hostNow ? " (render host)" : ""}</span><span><i style={{ background: "var(--cyan)" }} />selected layer: drag edges to trim, top corners to fade, the top line for gain</span>{libSilenced > 0 && <span><i style={{ background: "var(--faint)" }} />library layer: outline only</span>}</div>
          </div>

          <div className="cys-panel cys-glass sd-lstack">
            <div className="sd-lhead"><span className="cys-eyebrow">Layers · mixed, then normalised to the role</span>
              <button type="button" className="cys-btn xs" disabled={showCand} onClick={() => { setTab("lib"); toast(caps.libraryCleared ? "Pick a sound in the Library and press Add." : "The sound library is off until the owner confirms its licence. Synth presets work now.", !caps.libraryCleared); }}><SI n="library" />Library sound</button>
              <button type="button" className="cys-btn xs" disabled={showCand} onClick={() => setTab("syn")}><SI n="synth" />Synth preset</button>
              <button type="button" className="cys-btn xs" disabled={showCand} onClick={() => addL(silenceLayer(0.2, variant ? Math.min(5, Math.round(layerSpanEnd(variant, durOf) * 1000) / 1000) : 0), "Added silence")} data-testid="add-silence"><SI n="silence" />Silence</button>
            </div>
            {variant && variant.layers.length ? variant.layers.map((l, i) => {
              const k = layerKind(l), id = libIdOf(l), meta = id ? libMeta[id] : null;
              const total = Math.max(0.4, layerSpanEnd(variant, durOf)) + 0.15;
              const lp = k === "lib" && !buffersFor(variant).has(`__p${i}`) ? null : layerPcm(variant, i);
              const ro = showCand;
              const set = (patch: Partial<SoundLayer>, f: string) => commit(`${f} ${nameOf(l)}`, setLayer(spec, ei, vi, i, patch), `k:${ei}:${vi}:${i}:${f}`);
              return (
                <div key={i} className={`sd-lane ${i === li ? "on" : ""}`} onClick={(e) => { if ((e.target as HTMLElement).closest("input,button")) return; pick({ li: i }); }} data-testid="layer-lane">
                  <button type="button" className="cys-ib sm" aria-label={`Play ${nameOf(l)} alone`} title="Play this layer alone" onClick={() => { const pcm = layerPcm(variant, i); if (!pcm.length) { toast(k === "lib" ? caps.audition.reason ?? "No preview." : "Nothing to play.", true); return; } audio.play(pcm, `layer${i}`, { loop: false }); }}><SI n={audio.playing === `layer${i}` ? "stop" : "play"} /></button>
                  <div className="src"><span className={`k ${k}`}><SI n={k === "lib" ? "library" : k === "synth" ? "synth" : "silence"} /></span>
                    <span style={{ minWidth: 0 }}><b title={l.source}>{nameOf(l)}</b><small>{k === "lib" ? `${CAT_LABEL[meta?.category ?? ""] ?? "Library"} · library` : k === "synth" ? `synth preset · seed ${l.seed}` : "spacer"}{l.start ? ` · at ${l.start.toFixed(2)}s` : ""}</small></span></div>
                  <MiniWave pcm={lp} start={l.start} total={total} tone={i === li ? "cyan" : "accent"} silence={k === "silence"} outline={k === "lib" && !lp && meta?.peaks ? decodePeaks(meta.peaks) : null} label={`${nameOf(l)} waveform`} />
                  <div className="knobs">
                    {k === "silence" ? (
                      <><Knob label="length" v={l.length ?? 0.2} lo={0.01} hi={2} step={0.01} fmt={(x) => `${x}s`} dis={ro} on={(x) => set({ length: x }, "Length")} /><Knob label="offset" v={l.start} lo={0} hi={5} step={0.01} fmt={(x) => fmtK("start", x)} dis={ro} on={(x) => set({ start: x }, "Offset")} /><span /></>
                    ) : (
                      <><Knob label="gain" v={l.gain} lo={-40} hi={12} step={0.5} fmt={(x) => fmtK("gain", x)} dis={ro} on={(x) => set({ gain: x }, "Gain")} />
                        <Knob label="pitch" v={l.pitch} lo={-24} hi={24} step={1} fmt={(x) => fmtK("pitch", x)} dis={ro} on={(x) => set({ pitch: x }, "Pitch")} />
                        <Knob label="offset" v={l.start} lo={0} hi={2} step={0.01} fmt={(x) => fmtK("start", x)} dis={ro} on={(x) => set({ start: x }, "Offset")} /></>
                    )}
                  </div>
                  {!ro && <button type="button" className="cys-ib sm del" aria-label={`Remove ${nameOf(l)}`} title="Remove layer" onClick={() => { commit(`Removed ${nameOf(l)}`, removeLayer(spec, ei, vi, i)); pick({ li: Math.max(0, i - 1) }); }}><SI n="close" /></button>}
                </div>
              );
            }) : <div className="cys-empty" style={{ padding: "14px 18px" }}>No layers yet. Up to {MAX_LAYERS} per variant: library sounds, synth presets or silence.</div>}
            {variant && (
              <div className="sd-proc">
                <span className="cys-eyebrow">Variant FX</span>
                <Knob label="low-pass" v={variant.processing.lowpass ?? 20000} lo={1000} hi={20000} step={500} fmt={(x) => (x >= 20000 ? "off" : `${(x / 1000).toFixed(1)} kHz`)} dis={showCand} on={(x) => commit("Low-pass", setProcessing(spec, ei, vi, { lowpass: x >= 20000 ? null : x }), `fx:${ei}:${vi}:lp`)} />
                <Knob label="high-pass" v={variant.processing.highpass ?? 20} lo={20} hi={2000} step={10} fmt={(x) => (x <= 20 ? "off" : `${x} Hz`)} dis={showCand} on={(x) => commit("High-pass", setProcessing(spec, ei, vi, { highpass: x <= 20 ? null : x }), `fx:${ei}:${vi}:hp`)} />
                <Knob label="reverb" v={variant.processing.reverb} lo={0} hi={1} step={0.05} fmt={(x) => `${Math.round(x * 100)}%`} dis={showCand} on={(x) => commit("Reverb", setProcessing(spec, ei, vi, { reverb: x }), `fx:${ei}:${vi}:rv`)} />
                <Knob label="echo" v={variant.processing.echo?.delay ?? 0} lo={0} hi={600} step={20} fmt={(x) => (x < 20 ? "off" : `${x} ms`)} dis={showCand} on={(x) => commit("Echo", setProcessing(spec, ei, vi, { echo: x < 20 ? null : { delay: x, feedback: variant.processing.echo?.feedback ?? 0.3, mix: variant.processing.echo?.mix ?? 0.25 } }), `fx:${ei}:${vi}:ec`)} />
                <span className="cys-hint fmt">mono · 44.1 kHz · Ogg Vorbis on export</span>
              </div>
            )}
          </div>

          <div className="cys-dock cys-glass" data-busy={busy}>
            <span className="route"><SI n="wave" />Edit {sel.set}.{sel.event}</span>
            <input value={prompt} onChange={(e) => setPrompt(e.target.value)} onKeyDown={(e) => { if (e.key === "Enter") void ask(); }} placeholder={busy ? "Cyrus is building a candidate…" : "Ask Cyrus to change this sound…"} aria-label="Ask Cyrus to change this sound" maxLength={600} disabled={busy} data-testid="dock-input" />
            {est && <span className="est">{est}</span>}
            <span className="model"><CyrusGlyph id="sd-dock-y" style={{ fontSize: 13 }} />Saka</span>
            <button type="button" className="send" aria-label="Send" onMouseDown={(e) => e.preventDefault()} onClick={() => void ask()} disabled={busy || prompt.trim().length < 4}><SI n="send" /></button>
          </div>
        </section>

        {/* RIGHT */}
        <section className="sd-col">
          <div className="cys-panel cys-glass sd-meters" data-testid="meters">
            <div className="cys-ph"><span className="cys-eyebrow">Loudness · {role}</span>{Q && <span className={`cys-tag ${vClass(Q.verdict)}`}>{Q.verdict}</span>}</div>
            {M && Q ? (
              <>
                <Meter label="Integrated loudness" value={M.lufs} unit="LUFS" lo={-40} hi={0} band={[prof.min, prof.max]} scale={["-40", `${role} band ${prof.min} to ${prof.max}`, "0"]} />
                <Meter label="True peak" value={M.truePeakDb} unit="dBTP" lo={-24} hi={0} ceil={-1} scale={["-24", "ceiling -1", "0"]} />
                <div className="sd-m3">
                  <div><span>Silence</span><b>{Math.round(M.silenceRatio * 100)}<small>%</small></b></div>
                  <div><span>Length</span><b>{M.durationS.toFixed(2)}<small> / {prof.maxSeconds}s</small></b></div>
                  <div><span>Auto gain</span><b>{gainInfo ? `${gainInfo.gainDb > 0 ? "+" : ""}${gainInfo.gainDb.toFixed(1)}` : "–"}<small> dB</small></b></div>
                </div>
                <div className="sd-mnote"><p className="cys-hint">{gainInfo?.peakLimited ? "Limited by the true-peak ceiling before it reached the target." : `Normalised to ${prof.target} LUFS, the ${role} target.`} {hostNow ? (hostNow.view.fake ? "Measured by the development stand-in host." : "Measured on the encoded Ogg from the render host.") : libSilenced ? `Browser estimate without ${libSilenced} library layer${libSilenced > 1 ? "s" : ""} (audition off).` : "Browser estimate; the final numbers are measured on the encoded Ogg."}</p>
                  <button type="button" className="cys-btn xs" onClick={() => void renderOnHost()} disabled={rendering || !ev || showCand} title={caps.render ? `Render on ${caps.render}` : caps.renderOff ?? ""} data-testid="render-host">{rendering ? "Rendering…" : "Render and preview"}</button></div>
              </>
            ) : <p className="cys-hint" style={{ padding: "0 14px 12px" }}>Nothing to measure yet.</p>}
          </div>
          <div className="cys-panel cys-glass sd-side">
            <div className="cys-tabs" role="tablist">
              <button type="button" role="tab" aria-selected={tab === "lib"} className={`cys-tab ${tab === "lib" ? "on" : ""}`} onClick={() => setTab("lib")}>Library <span className="n">514</span></button>
              <button type="button" role="tab" aria-selected={tab === "syn"} className={`cys-tab ${tab === "syn" ? "on" : ""}`} onClick={() => setTab("syn")}>Synth</button>
              <button type="button" role="tab" aria-selected={tab === "qc"} className={`cys-tab ${tab === "qc" ? "on" : ""}`} onClick={() => setTab("qc")}>Checks {Q && <span className="n" style={{ color: `var(--${vClass(Q.verdict) === "dim" ? "muted" : vClass(Q.verdict)})` }}>{Q.verdict}</span>}</button>
              <button type="button" role="tab" aria-selected={tab === "hist"} className={`cys-tab ${tab === "hist" ? "on" : ""}`} onClick={() => setTab("hist")}>History <span className="n">{ed.entry.history.length}</span></button>
            </div>
            <div className="sd-pane" role="tabpanel">
              {tab === "lib" && (
                <LibraryBrowser kind="sound" projectId={project.id} useLabel={`Add to ${sel.event} V${vi + 1}`}
                  note={caps.audition.library ? <>Audition plays a short processed preview made on the render host.</> : <><b>{caps.audition.reason}</b></>}
                  renderLead={(i) => <LibPlay item={i} audio={audio} caps={caps} toast={toast} />}
                  onUse={async (item: LibraryItem) => {
                    const r = await studioApi.useSound({ projectId: project.id, ref: item.ref, key: sel.set, event: sel.event });
                    if (item.sound) setLibMeta((m) => ({ ...m, [item.id]: { duration: item.sound!.duration, lufs: item.sound!.lufs, prefix: item.sound!.prefix, category: item.category, peaks: item.sound!.peaks } }));
                    addL(r.layer, `Added ${human(item.id)}`);
                    toast(`Added ${human(item.id)} as a layer (pitch -1: library sounds never ship unchanged). Trim it on the waveform.`);
                  }} />
              )}
              {tab === "syn" && <SynthPane layer={curLayer && layerKind(curLayer) === "synth" && !showCand ? curLayer : null} audio={audio}
                onEdit={(patch, f) => commit(`${f} ${nameOf(curLayer!)}`, setLayer(spec, ei, vi, li, patch), `syn:${ei}:${vi}:${li}:${f}`)}
                onAdd={(preset, params) => addL(synthLayer(preset, { params, start: variant ? Math.min(5, Math.round(layerSpanEnd(variant, durOf) * 1000) / 1000) * 0 : 0 }), `Added synth · ${preset}`)} />}
              {tab === "qc" && <ChecksPane q={Q} ev={ev} label={showCand ? "Candidate" : `V${vi + 1}`} keyName={`${sel.set}.${sel.event}`} host={hostNow ? (hostNow.view.fake ? "stand-in host" : hostNow.view.host) : null} />}
              {tab === "hist" && <HistoryPane ed={ed} ev={ev} vi={vi} seqOf={seqOf} renderV={renderV} current={R?.pcm ?? null} saving={saving} onSave={() => void save()} onRestore={(h) => { commit(`Restored revision ${seqOf(h.revisionId) ?? ""}`.trim(), h.spec); toast("Restored as an edit step. Save to make it a new revision."); }} />}
            </div>
          </div>
        </section>
      </main>
      <Narrow view={view} eds={eds} kinds={kinds} verdicts={verdicts} renderV={renderV} audio={audio}
        onApprove={(set) => { const e = eds[set]; const c = e.cand; const sp = e.hist.steps[e.hist.at].snap; if (!c?.spec) return; const ce = c.spec.events.find((x) => x.event === c.event); const ix = sp.events.findIndex((x) => x.event === c.event); if (!ce || ix < 0) return; const r = applyCandidate(sp, ix, ce, "add_variant"); if (!r.ok) { toast(`${r.error} Approve on a larger screen to replace one.`, true); return; } setSel({ set, event: c.event, vi: 0, li: 0, cand: false }); void save({ spec: r.spec, accept: { requestId: c.requestId, mode: "add_variant" } }); }}
        onReject={(set) => { setSel({ set, event: eds[set].cand?.event ?? sel.event, vi: 0, li: 0, cand: true }); window.setTimeout(() => void reject(), 0); }} />
    </>
  );
  // eslint-disable-next-line no-unreachable
  function setZoom(z: number) { setZoomState(z); }
}

// zoom lives outside Editor's render so the waveform keeps its own scroll; a tiny store
let zoomListeners: ((z: number) => void)[] = [];
let zoomValue = 1;
function setZoomState(z: number) { zoomValue = Math.max(1, Math.min(8, z)); zoomListeners.forEach((f) => f(zoomValue)); }
function useZoom() { const [z, set] = useState(zoomValue); useEffect(() => { zoomListeners.push(set); return () => { zoomListeners = zoomListeners.filter((f) => f !== set); }; }, []); return z; }
// eslint-disable-next-line @typescript-eslint/no-unused-vars
const zoom = 1;

const layerSpanEnd = (v: SoundVariant, durOf: (id: string) => number | null) => v.layers.reduce((m, l) => Math.max(m, layerSpan(l, libIdOf(l) ? durOf(libIdOf(l)!) : null).end), 0);

function ZoomCtl({ setZoom }: { zoom: number; setZoom: (z: number) => void }) {
  const z = useZoom();
  return (
    <>
      <button type="button" className="cys-ib" aria-label="Zoom out" onClick={() => setZoom(z / 1.5)}><SI n="minus" /></button>
      <span className="sd-zv" aria-live="polite">{z < 1.05 ? "1" : z.toFixed(1).replace(".0", "")}×</span>
      <button type="button" className="cys-ib" aria-label="Zoom in" onClick={() => setZoom(z * 1.5)}><SI n="plus" /></button>
    </>
  );
}

function Clock({ audio, total }: { audio: ReturnType<typeof useAudio>; total: number }) {
  const [t, setT] = useState<number | null>(null);
  useEffect(() => { let raf = 0; const f = () => { setT(audio.position("mix")); raf = requestAnimationFrame(f); }; raf = requestAnimationFrame(f); return () => cancelAnimationFrame(raf); }, [audio]);
  return <span className="sd-tc">{(t ?? 0).toFixed(3)} <span>/ {(total / SAMPLE_RATE).toFixed(3)} s</span></span>;
}

function Knob({ label, v, lo, hi, step, fmt, on, dis }: { label: string; v: number; lo: number; hi: number; step: number; fmt: (x: number) => string; on: (x: number) => void; dis?: boolean }) {
  return (
    <label className="sd-knob"><span>{label} <b>{fmt(v)}</b></span>
      <input type="range" className="sd-range" min={lo} max={hi} step={step} value={Math.max(lo, Math.min(hi, v))} style={rangeStyle(v, lo, hi)} disabled={dis} onChange={(e) => on(Number(e.target.value))} aria-label={label} />
    </label>
  );
}

function Meter({ label, value, unit, lo, hi, band, ceil, scale }: { label: string; value: number; unit: string; lo: number; hi: number; band?: [number, number]; ceil?: number; scale: [string, string, string] }) {
  const pct = (x: number) => Math.max(0, Math.min(100, ((x - lo) / (hi - lo)) * 100));
  return (
    <div className="sd-meter">
      <div className="mh"><span>{label}</span><b>{value <= -998 ? "–" : value} <small>{unit}</small></b></div>
      <div className="mbar">
        {band && <span className="band" style={{ left: `${pct(band[0])}%`, right: `${100 - pct(band[1])}%` }} />}
        {band ? <span className="mark" style={{ left: `calc(${pct(value)}% - 1px)` }} /> : <span className="fillb" style={{ width: `${pct(value)}%`, background: ceil != null && value > ceil ? "var(--bad)" : "var(--accent)" }} />}
        {ceil != null && <span className="ceil" style={{ left: `${pct(ceil)}%` }} />}
      </div>
      <div className="mscale"><span>{scale[0]}</span><span>{scale[1]}</span><span>{scale[2]}</span></div>
    </div>
  );
}

function LibPlay({ item, audio, caps, toast }: { item: LibraryItem; audio: ReturnType<typeof useAudio>; caps: NonNullable<AssetsView["sound"]> | { audition: { library: boolean; reason: string | null } }; toast: (m: string, e?: boolean) => void }) {
  const id = `lib:${item.id}`;
  const [loading, setLoading] = useState(false);
  const on = audio.playing === id;
  const go = async () => {
    if (on) { audio.stop(); return; }
    if (!caps.audition.library) { toast(caps.audition.reason ?? "Library audition is off.", true); return; }
    setLoading(true);
    try {
      const pcm = await audio.decode(await studioApi.preview(auditionRequest(item.id, item.sound?.duration ?? 1)));
      audio.play(pcm, id, { loop: false });
    } catch (e) { toast(e instanceof ApiError ? e.message : "No preview.", true); }
    finally { setLoading(false); }
  };
  return <button type="button" className={`sd-pb ${on ? "on" : ""} ${caps.audition.library ? "" : "off"}`} onClick={() => void go()} aria-label={caps.audition.library ? `Audition ${item.sound?.prefix ?? item.name}` : "Library audition is off (licence)"} title={caps.audition.library ? "Audition a short preview" : caps.audition.reason ?? ""} data-testid="lib-audition" aria-disabled={!caps.audition.library}><SI n={loading ? "minus" : on ? "stop" : caps.audition.library ? "play" : "lock"} /></button>;
}

function SynthPane({ layer, audio, onEdit, onAdd }: { layer: SoundLayer | null; audio: ReturnType<typeof useAudio>; onEdit: (patch: Partial<SoundLayer>, f: string) => void; onAdd: (p: SynthPreset, params: Record<string, number>) => void }) {
  const editing = !!layer;
  const [preset, setPreset] = useState<SynthPreset>((layer?.source.slice(6) as SynthPreset) ?? "wail");
  const [params, setParams] = useState<Record<string, number>>({});
  useEffect(() => { if (layer) { setPreset(layer.source.slice(6) as SynthPreset); setParams(layer.params); } }, [layer]);
  const cur = editing ? (layer!.source.slice(6) as SynthPreset) : preset;
  const vals = editing ? layer!.params : params;
  const defs = SYNTH_PARAMS[cur];
  const previews = useMemo(() => Object.fromEntries(SYNTH_PRESETS.map((p) => [p, synth(p, 0.8, 1, {})])), []);
  const play = () => audio.play(synth(cur, editing ? layer!.length ?? 0.6 : 0.8, editing ? layer!.seed : 1, vals), "synth", { loop: false });
  return (
    <div>
      {editing && <p className="cys-hint" style={{ padding: "10px 14px 0", margin: 0 }}>Editing the selected layer <b className="mono">synth · {cur}</b>. Pick another preset to swap it, or add a new layer below.</p>}
      <div className="sd-presets">
        {SYNTH_PRESETS.map((p) => (
          <div key={p} className={`sd-preset ${p === cur ? "on" : ""}`}>
            <button type="button" className="pick" onClick={() => { if (editing) onEdit({ source: `synth:${p}`, params: {} } as Partial<SoundLayer>, "Preset"); else { setPreset(p); setParams({}); } }} aria-pressed={p === cur}>
              <MiniWave pcm={previews[p]} total={0.8} tone={p === cur ? "cyan" : "accent"} label={`${p} preset`} /><b>{p}</b>
            </button>
            <button type="button" className="cys-ib sm" title={`Play ${p}`} aria-label={`Play ${p}`} onClick={() => audio.play(previews[p], `preset:${p}`, { loop: false })}><SI n="play" /></button>
          </div>
        ))}
      </div>
      <div className="sd-params">
        {Object.entries(defs).map(([k, d]) => {
          const v = vals[k] ?? d.def;
          return (
            <label className="sd-param" key={k}><span>{k}<b>{Math.round(v * 1000) / 1000}</b></span>
              <input type="range" className="sd-range" min={d.min} max={d.max} step={(d.max - d.min) / 100} value={v} style={rangeStyle(v, d.min, d.max)} aria-label={`${cur} ${k}`}
                onChange={(e) => { const x = Math.round(Number(e.target.value) * 1000) / 1000; if (editing) onEdit({ params: { ...layer!.params, [k]: x } }, k); else setParams((p) => ({ ...p, [k]: x })); }} />
              <small>{d.doc}</small></label>
          );
        })}
        {editing && <Knob label="seed" v={layer!.seed} lo={0} hi={99} step={1} fmt={(x) => String(x)} on={(x) => onEdit({ seed: x }, "Seed")} />}
        {editing && <Knob label="length" v={layer!.length ?? 0.6} lo={0.05} hi={4} step={0.01} fmt={(x) => `${x}s`} on={(x) => onEdit({ length: x }, "Length")} />}
        <div style={{ display: "flex", gap: 8 }}>
          <button type="button" className="cys-btn sm" onClick={play}><SI n="play" />Preview</button>
          <button type="button" className="cys-btn sm primary" style={{ flex: 1 }} onClick={() => onAdd(cur, editing ? {} : params)} data-testid="add-synth"><SI n="plus" />Add as layer</button>
        </div>
        <p className="cys-hint">Presets are drawn by Nxeon&apos;s own code from a seed: original sound, no licence questions, and the same result every time. They play right here in your browser.</p>
      </div>
    </div>
  );
}

const ICK: Record<string, string> = { pass: "check", warn: "minus", fail: "close" };
function ChecksPane({ q, ev, label, keyName, host }: { q: SoundQualityReport | null; ev: SoundEvent | null; label: string; keyName: string; host: string | null }) {
  const sub = ev ? subtitleProblem(ev.subtitle) : "Required on every event.";
  if (!q) return <div className="cys-empty"><SI n="check" /><p>Add a sound to run the checks.</p></div>;
  const head = { pass: "Ready to ship", warn: "Ships, with warnings", fail: "Will not ship as is" }[q.verdict];
  return (
    <div>
      <div className="cys-verdict"><span className={`cys-dot ${vClass(q.verdict)}`} style={{ width: 10, height: 10 }} /><div><b>{sub ? "Can't be saved yet" : head}</b><div className="cys-hint">{label} of {keyName}</div></div><span className="cys-tag badge">{q.version}</span></div>
      <ul className="cys-checks">
        {q.checks.map((c) => (
          <li key={c.id} className={`cys-check ${c.status}`} data-check={c.id} data-status={c.status}>
            <span className="ic"><SI n={ICK[c.status]} label={c.status} /></span><span className="id">{c.id}</span><span className="val">{String(c.value)}</span><span className="msg">{c.message}</span><span className="lim">limit {c.limit}</span>
          </li>
        ))}
        <li className={`cys-check ${sub ? "fail" : "pass"}`} data-check="subtitle" data-status={sub ? "fail" : "pass"}><span className="ic"><SI n={sub ? "close" : "check"} label={sub ? "fail" : "pass"} /></span><span className="id">subtitle</span><span className="val">{ev?.subtitle.trim() ? `${ev.subtitle.trim().length} chars` : "missing"}</span><span className="msg">{sub ?? "players with subtitles on see it"}</span></li>
      </ul>
      <p className="cys-hint" style={{ padding: "0 16px 16px" }}>{host ? `Measured by the ${host}.` : "Measured in your browser on the same DSP the render host runs; the build measures the encoded Ogg again, and a failing variant is never shipped."} Checks re-run on every edit.</p>
    </div>
  );
}

function HistoryPane({ ed, ev, vi, seqOf, renderV, current, saving, onSave, onRestore }: {
  ed: Ed; ev: SoundEvent | null; vi: number; seqOf: (r: string) => number | null; renderV: (v: SoundVariant, r: SoundEvent["role"]) => { pcm: Mono }; current: Mono | null; saving: boolean; onSave: () => void; onRestore: (h: SoundSetEntry["history"][number]) => void;
}) {
  const rows = useMemo(() => ed.entry.history.map((h) => {
    const e = ev ? h.spec.events.find((x) => x.event === ev.event) : null;
    const v = e ? e.variants[Math.min(vi, e.variants.length - 1)] : null;
    const pcm = v && e ? renderV(v, e.role).pcm : null;
    return { h, pcm, diff: changedBuckets(current, pcm) };
  }), [ed.entry.history, ev, vi, renderV, current]);
  return (
    <div>
      {ed.dirty && <div className="sd-rev"><MiniWave pcm={current} label="Unsaved version" /><div><b>Unsaved edits</b><small>{ed.hist.at} edit step{ed.hist.at === 1 ? "" : "s"} since revision {seqOf(ed.entry.revisionId) ?? "?"}</small></div><button type="button" className="cys-btn xs primary" disabled={saving} onClick={onSave}>Save</button></div>}
      {rows.map(({ h, pcm, diff }, i) => {
        const changed = diff ? diff.filter(Boolean).length : 0;
        return (
          <div className="sd-rev" key={h.assetId} data-testid="sound-revision">
            <MiniWave pcm={pcm} diff={i > 0 || ed.dirty ? diff : null} label={`Revision ${seqOf(h.revisionId) ?? "?"} waveform`} />
            <div><b>Revision {seqOf(h.revisionId) ?? "?"} · {h.label}{i === 0 && !ed.dirty && <span className="cur">Current</span>}</b>
              <small>{new Date(h.createdAt).toLocaleString(undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" })}{(i > 0 || ed.dirty) && pcm ? ` · ${changed ? `${changed} of 48 slices differ from yours` : "sounds the same as yours"}` : ""}{!pcm && ev ? ` · no ${ev.event} in this revision` : ""}</small></div>
            {(i > 0 || ed.dirty) && <button type="button" className="cys-btn xs ghost" onClick={() => onRestore(h)}><SI n="restore" />Restore</button>}
          </div>
        );
      })}
      <p className="cys-hint" style={{ padding: "12px 16px" }}>Each revision keeps its SoundSpec (the recipe); the waveforms are re-rendered from it, and the amber marks show where a revision differs from the version you are editing. Restoring makes a new revision; nothing is deleted.</p>
    </div>
  );
}

function Narrow({ view, eds, kinds, verdicts, renderV, audio, onApprove, onReject }: {
  view: AssetsView; eds: Record<string, Ed>; kinds: Record<string, SetKind>; verdicts: Record<string, string>; renderV: (v: SoundVariant, r: SoundEvent["role"]) => { pcm: Mono }; audio: ReturnType<typeof useAudio>; onApprove: (set: string) => void; onReject: (set: string) => void;
}) {
  return (
    <main className="sd-narrow" aria-label="Sound review">
      {view.soundSets.map((s) => {
        const e0 = eds[s.set];
        const sp = e0.hist.steps[e0.hist.at].snap;
        const c = e0.cand?.status === "ready" ? e0.cand : null;
        return (
          <div className="n-card cys-glass" key={s.set}>
            <div className="n-h">{kinds[s.set] === "mob" ? <svg className="cys-i" viewBox="0 0 24 24" aria-hidden dangerouslySetInnerHTML={{ __html: CREATURES_PATH }} /> : <SI n="cube" />}<div style={{ flex: 1 }}><h1>{s.set}</h1><p>{kinds[s.set] === "mob" ? "Mob" : kinds[s.set] === "item" ? "Item" : "Sound set"} · {sp.events.filter((e) => e.variants.length).length} events</p></div></div>
            {sp.events.filter((e) => e.variants.length).map((e) => {
              const k = `${s.set}.${e.event}`, missing = subtitleProblem(e.subtitle);
              return (
                <div className="n-ev" key={e.event}>
                  <button type="button" className="sd-play n" aria-label={`Play ${k}`} onClick={() => audio.play(renderV(e.variants[0], e.role).pcm, `n:${k}`, { loop: false })}><SI n={audio.playing === `n:${k}` ? "stop" : "play"} /></button>
                  <div><b>{e.event} <span className="cys-tag dim">{e.variants.length}×</span></b><small className={missing ? "err" : ""}>{missing ? "Subtitle required: add it on desktop" : `“${e.subtitle}”`}</small></div>
                  <span className={`cys-dot ${missing ? "bad" : verdicts[k] ?? ""}`} />
                  {c && c.event === e.event && c.spec && (
                    <div className="cys-cand n-cand" data-testid="narrow-candidate">
                      <div className="cys-cand-h"><span className="av"><CyrusGlyph id={`n-sd-${s.set}`} /></span><div><b>Candidate for {e.event}</b><q>{c.summary}</q></div></div>
                      <div className="cys-cand-act">
                        <button type="button" className="cys-btn sm" onClick={() => { const ce = c.spec!.events.find((x) => x.event === c.event); if (ce) audio.play(renderV(ce.variants[0], ce.role).pcm, "n:cand", { loop: false }); }}><SI n="play" />Play</button>
                        {STUDIO_DEFAULTS.mobile === "review_and_approve" && <button type="button" className="cys-btn sm primary" onClick={() => onApprove(s.set)} data-testid="narrow-approve">Approve</button>}
                        <button type="button" className="cys-btn sm ghost" onClick={() => onReject(s.set)}>Reject</button>
                      </div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        );
      })}
      <div className="n-card cys-glass"><div className="n-note"><SI n="info" /><span>Waveform editing and layering need a larger screen. Here you can listen, check subtitles and approve Cyrus candidates; an approval adds the candidate as a new variant and saves a revision.</span></div></div>
    </main>
  );
}

