 * place (the mod's sound events stay listed); the API refuses their edits anyway. ?set=<set>&event=<event> opens one.
 */
export default async function SoundStudioPage({ params, searchParams }: { params: Promise<{ id: string }>; searchParams: Promise<{ set?: string | string[]; event?: string | string[] }> }) {
  await requireModBuilderUser(); // the Cyrus preview gate first (studioContext checks it again + the studios gate)
  const { id } = await params;
  const { mod, plan } = await studioContext(id);
  if (!plan.edit.sound.ok) return <StudioLock mod={mod} studio="sound" />;
  const q = await searchParams;
  const one = (v: string | string[] | undefined, re: RegExp) => (typeof v === "string" && re.test(v) ? v : null);
  return <SoundStudio mod={mod} initialSet={one(q.set, /^[a-z][a-z0-9_]{1,31}$/)} initialEvent={one(q.event, /^[a-z][a-z0-9_]{0,23}$/)} />;
}
