"use client";
// Cyrus studios: the locked / included / plan-unknown states (approved mockup locked-states.html). The decision is the
// server's (GET /api/cyrus/assets/v1/projects -> access, from lib/cyrus/engine-core/asset-gate.ts); this page only
// shows it. The copy is the gate's own reason strings and the router downgrade notices. Assets already in the mod
// are always shown (read only): keeping, installing and exporting are never gated.
import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { cyrusTokens } from "@/components/cyrus-tokens";
import { PLAN_LABEL, type AssetPlan } from "@/lib/cyrus/engine-core/asset-gate";
import { buildNotices, PLAN_MATRIX, PLAN_ORDER, STUDIO_NAME } from "@/lib/cyrus/studios/access";
import { renderDoc } from "@/lib/cyrus/studios/paint";
import { studioApi, type AssetsView } from "./api";
import { SI } from "./icons";
import { RasterCanvas } from "./raster";
import { StudioShell, assetsHref, studioHref, type StudioMod } from "./StudioShell";

export function StudioLock({ mod, studio }: { mod: StudioMod; studio: "texture" | "sound" }) {
  return (
    <StudioShell mod={mod} current={STUDIO_NAME[studio]} studio={null}>
      <LockBody mod={mod} studio={studio} />
    </StudioShell>
  );
}

function LockBody({ mod, studio }: { mod: StudioMod; studio: "texture" | "sound" }) {
  const [view, setView] = useState<AssetsView | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [tick, setTick] = useState(0);
  const [texSel, setTexSel] = useState<string | null>(null);
  useEffect(() => { studioApi.assets(mod.rootId).then(setView, (e) => setErr((e as Error).message)); }, [mod.rootId, tick]);
  const plan = view?.access.plan ?? null;
  const [previewAs, setPreviewAs] = useState<AssetPlan | "unknown" | null>(null);
  const shownPlan = previewAs ?? (view ? plan ?? "unknown" : null);
  if (err) return <div className="cys-empty" style={{ margin: "auto" }}>{err}</div>;
  if (!view || !shownPlan) return <div className="cys-empty" style={{ margin: "auto" }} aria-busy="true">Checking your plan…</div>;
  const d = view.access.edit[studio];
  const name = STUDIO_NAME[studio];
  const tex = view.textures;
  const cur = tex.find((t) => t.key === texSel) ?? tex[0];
  const notes = buildNotices(shownPlan === "unknown" ? null : shownPlan, { sound: view.sounds[0]?.set ?? (view.soundRender ? "sounds" : null), texture: tex[0]?.key ?? null });
  const kindWord = studio === "texture" ? "textures" : "sounds";

  return (
    <main className="lk-ws">
      <section className="lk-col">
        <div className="lk-view cys-glass cys-hairline">
          <div className="lk-vh">
            <span style={{ fontSize: 18, color: "var(--accent-ink)", display: "flex" }}><SI n={studio === "texture" ? "image" : "wave"} /></span>
            <h1>{name}</h1>
            <span className={`cys-tag ${d.ok ? "ok" : "dim"}`}>{d.ok ? "included" : studio === "texture" ? "view only" : "listen only"}</span>
            <span className="sp" />
            <div className="cys-seg sm cys-soft">
              <Link href={studioHref(mod, "plans", "?studio=texture")} className={studio === "texture" ? "on" : ""}>Texture</Link>
              <Link href={studioHref(mod, "plans", "?studio=sound")} className={studio === "sound" ? "on" : ""}>Sound</Link>

