// Generated files of the Cyrus sound slice (all committed, so neither the portal nor the build service needs esbuild
// at runtime; test/cyrus-sounds.test.ts rebuilds them in memory and fails when one is stale):
//   lib/cyrus/sound/runner.bundle.cjs      the render-host runner (runner-cli.ts + the pure DSP), shipped to node-2
//   services/modbuilder/sound-spec.js      the build service's SoundSpec validator, generated from spec.ts
//   services/modbuilder/sound-catalog.txt  the library catalog the model reads (ids, seconds, tags; no audio)
//   services/modbuilder/sound-catalog.json id -> seconds, for the service validator
//   npx tsx scripts/cyrus/build-sound-artifacts.ts [--check]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { libraryCatalogDurations, libraryCatalogText, soundManifest } from "../../lib/cyrus/sound/library";

const ROOT = path.join(__dirname, "../..");
const HEADER = (src: string, where: string) => `// GENERATED by scripts/cyrus/build-sound-artifacts.ts from ${src}. Do not edit. ${where}`;

async function bundle(entry: string, banner: string): Promise<string> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({ entryPoints: [path.join(ROOT, entry)], bundle: true, platform: "node", format: "cjs", target: "node20", write: false, minify: false, legalComments: "none", banner: { js: banner } });
  return r.outputFiles[0].text;
}

export async function soundArtifacts(): Promise<Record<string, string>> {
  return {
    "lib/cyrus/sound/runner.bundle.cjs": await bundle("lib/cyrus/sound/runner-cli.ts", HEADER("lib/cyrus/sound/*.ts", "Runs on the render host (node-2) only.")),
    "services/modbuilder/sound-spec.js": await bundle("lib/cyrus/sound/spec-entry.ts", `"use strict";\n${HEADER("lib/cyrus/sound/spec.ts + synth-params.ts", "The build service's SoundSpec validator.")}`),
    "services/modbuilder/sound-catalog.txt": libraryCatalogText(),
    "services/modbuilder/sound-catalog.json": JSON.stringify({ version: soundManifest().version, generatedAt: soundManifest().generatedAt, durations: libraryCatalogDurations() }) + "\n",
  };
}

if (require.main === module) {
  soundArtifacts().then((files) => {
    let stale = 0;
    for (const [rel, text] of Object.entries(files)) {
      const abs = path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-sound-artifacts.ts"); process.exit(1); }

