// Cyrus Sound Studio (R1b) fixtures: the two sound sets the studio screenshots and tests use, as real SoundSpec v1
// (synth presets only, so they validate with the library OFF). STUDIO_FIXTURE_LIBRARY=1 adds one library layer to
// banshee.hurt V1 (scream_female_2_648f, pitch -5) for the "library cleared" screenshots. Also used by unit tests.
import type { SoundLayer, SoundSpec } from "../../lib/cyrus/sound/spec";

const L = (source: string, o: Partial<SoundLayer> = {}) => ({ source, ...o });
const V = (weight: number, layers: object[], processing: object = {}) => ({ weight, layers, processing });

export function bansheeSpec(withLibrary = false): unknown {
  return {
    version: 1, name: "banshee",
    events: [
      { event: "ambient", role: "ambient", category: "hostile", subtitle: "Banshee moans", variants: [
        V(1, [L("synth:wail", { length: 1.5, seed: 4, params: { start: 620, end: 300, breath: 0.4 }, fadeOut: 300 }), L("synth:whoosh", { gain: -14, length: 1.4, fadeIn: 200, fadeOut: 400, params: { low: 200, high: 900 } })], { reverb: 0.35, lowpass: 4000 }),
        V(1, [L("synth:wail", { length: 1.2, seed: 9, params: { start: 540, end: 280, breath: 0.45 }, fadeOut: 260 })], { reverb: 0.35 }),
        V(1, [L("synth:wail", { length: 1.8, seed: 2, params: { start: 700, end: 330, depth: 0.6 }, fadeOut: 400 })], { reverb: 0.4 })] },
      { event: "hurt", role: "hurt", category: "hostile", subtitle: "Banshee shrieks", variants: [
        V(2, [L("synth:wail", { length: 0.5, seed: 3, params: { start: 1100, end: 700 }, fadeOut: 90 }),
          withLibrary ? L("lib:scream_female_2_648f", { start: 0.02, gain: -8, pitch: -5, trimStart: 0.1, length: 0.42, fadeIn: 5, fadeOut: 80 }) : L("synth:impact", { start: 0.02, gain: -8, length: 0.3, params: { thump: 90, crack: 0.7, decay: 0.12 }, fadeOut: 60 })], { lowpass: 6000, reverb: 0.2 }),
        V(1, [L("synth:wail", { length: 0.45, seed: 7, params: { start: 1250, end: 640 }, fadeOut: 80 }), L("synth:growl", { gain: -6, length: 0.4, params: { pitch: 180, rough: 0.7 }, fadeOut: 60 })], { reverb: 0.2 })] },
      { event: "death", role: "death", category: "hostile", subtitle: "Banshee fades away", variants: [
        V(1, [L("synth:wail", { length: 1.3, seed: 6, params: { start: 900, end: 200, depth: 0.5 }, fadeOut: 600 }), L("synth:wail", { start: 0.2, length: 1.6, seed: 5, params: { start: 700, end: 120 }, fadeOut: 700, gain: -4 })], { reverb: 0.5 })] },
      { event: "attack", role: "attack", category: "hostile", subtitle: "Banshee lunges", variants: [
        V(1, [L("synth:whoosh", { gain: -2, length: 0.5, fadeOut: 120 }), L("synth:growl", { start: 0.08, length: 0.45, params: { pitch: 180, rough: 0.7 }, gain: -6, fadeOut: 120 })])] },
      { event: "step", role: "step", category: "hostile", subtitle: "Banshee drifts", variants: [
        V(1, [L("synth:whoosh", { gain: -10, length: 0.28, fadeIn: 30, fadeOut: 120, params: { low: 150, high: 1200 } })], { lowpass: 2500 }),
        V(1, [L("synth:whoosh", { gain: -10, length: 0.26, seed: 2, fadeIn: 30, fadeOut: 110, params: { low: 180, high: 1000 } })], { lowpass: 2500 })] },
      { event: "wail", role: "ability", category: "hostile", subtitle: "Banshee wails", variants: [
        V(1, [L("synth:wail", { length: 1.1, seed: 11, params: { start: 900, end: 500, depth: 0.5 }, fadeOut: 200 }), L("silence", { start: 1.1, length: 0.15 }), L("synth:wail", { start: 1.25, length: 1.4, seed: 12, params: { start: 1200, end: 260, depth: 0.6 }, fadeOut: 500 })], { reverb: 0.45, echo: { delay: 180, feedback: 0.3, mix: 0.25 } })] },
    ],
  };
}

export function glockSpec(): unknown {
  return {
    version: 1, name: "glock_9mm",
    events: [
      { event: "fire", role: "fire", category: "player", subtitle: "Pistol fires", variants: [
        V(1, [L("synth:gunshot", { length: 0.55, params: { body: 180, crack: 0.9, room: 0.2 }, fadeOut: 150 })]),
        V(1, [L("synth:gunshot", { length: 0.55, seed: 2, params: { body: 170, crack: 0.85 }, fadeOut: 150 })]),
        V(1, [L("synth:gunshot", { length: 0.5, seed: 3, params: { body: 160, crack: 0.8, tail: 0.3 }, fadeOut: 150, gain: 2 })])] },
      { event: "reload", role: "reload", category: "player", subtitle: "Pistol reloads", variants: [
        V(1, [L("synth:click", { length: 0.12, params: { pitch: 1800, body: 0.6 } }), L("synth:click", { start: 0.4, length: 0.12, gain: -4, params: { pitch: 2600, body: 0.6 } }), L("synth:impact", { start: 0.55, length: 0.15, gain: -10, params: { thump: 140, crack: 0.4, decay: 0.05 } })])] },
    ],
  };
}

export type FixtureSpec = SoundSpec;
