        V(1, [L("synth:wail", { length: 0.45, seed: 7, params: { start: 1250, end: 640 }, fadeOut: 80 }), L("synth:growl", { gain: -6, length: 0.4, params: { pitch: 180, rough: 0.7 }, fadeOut: 60 })], { reverb: 0.2 })] },
      { event: "death", role: "death", category: "hostile", subtitle: "Banshee fades away", variants: [
        V(1, [L("synth:wail", { length: 1.3, seed: 6, params: { start: 900, end: 200, depth: 0.5 }, fadeOut: 600 }), L("synth:wail", { start: 0.2, length: 1.6, seed: 5, params: { start: 700, end: 120 }, fadeOut: 700, gain: -4 })], { reverb: 0.5 })] },
      { event: "attack", role: "attack", category: "hostile", subtitle: "Banshee lunges", variants: [
        V(1, [L("synth:whoosh", { gain: -2, length: 0.5, fadeOut: 120 }), L("synth:growl", { start: 0.08, length: 0.45, params: { pitch: 180, rough: 0.7 }, gain: -6, fadeOut: 120 })])] },
      { event: "step", role: "step", category: "hostile", subtitle: "Banshee drifts", variants: [
        V(1, [L("synth:whoosh", { gain: -10, length: 0.28, fadeIn: 30, fadeOut: 120, params: { low: 150, high: 1200 } })], { lowpass: 2500 }),
        V(1, [L("synth:whoosh", { gain: -10, length: 0.26, seed: 2, fadeIn: 30, fadeOut: 110, params: { low: 180, high: 1000 } })], { lowpass: 2500 })] },
      { event: "wail", role: "ability", category: "hostile", subtitle: "Banshee wails", variants: [
        V(1, [L("synth:wail", { length: 1.1, seed: 11, params: { start: 900, end: 500, depth: 0.5 }, fadeOut: 200 }), L("silence", { start: 1.1, length: 0.15 }), L("synth:wail", { start: 1.25, length: 1.4, seed: 12, params: { start: 1200, end: 260, depth: 0.6 }, fadeOut: 500 })], { reverb: 0.45, echo: { delay: 180, feedback: 0.3, mix: 0.25 } })] },
