        V(1, [L("synth:gunshot", { length: 0.55, params: { body: 180, crack: 0.9, room: 0.2 }, fadeOut: 150 })]),
        V(1, [L("synth:gunshot", { length: 0.55, seed: 2, params: { body: 170, crack: 0.85 }, fadeOut: 150 })]),
