    assert.equal((await H.handleSaveRevision(post("/x", { doc: painted(), baseAssetId: null, expectedHeadId: null }), { projectId: PID, key: "Bad Key" }, c.deps)).status, 400);
    assert.equal((await H.handleSaveRevision(new Request(U, { method: "POST", body: "{nope" }), P, c.deps)).status, 400);
    assert.equal((await H.handleProjectAssets(get("/projects?root=mbX"), c.deps)).status, 404);
  });
  it("list -> save -> history: a new revision with the paint layer, plan gate enforced server side", async () => {
