    const v = await (await H.handleProjectAssets(get("/projects?root=mb1"), a.deps)).json();
    assert.equal(v.textures[0].key, "glock_9mm"); assert.equal(v.access.edit.texture.ok, true); assert.equal(v.uploads, false);
    const r = await H.handleSaveRevision(post("/x", { doc: painted(), baseAssetId: v.textures[0].assetId, expectedHeadId: v.headRevisionId }), P, a.deps);
    assert.equal(r.status, 201);
