const LAYER = (o: Partial<SoundLayer> = {}): SoundLayer => ({ source: "synth:wail", start: 0, gain: 0, pitch: 0, trimStart: 0, length: 0.5, fadeIn: 0, fadeOut: 0, seed: 1, params: {}, ...o });

// ------------------------------------------------------------------------------------------------ pure model
describe("sound-edit: layer / variant / event edits (immutable, clamped to the validator)", () => {
  it("fixtures are valid SoundSpecs with the library off (synth only) and on (one library layer)", () => {
    assert.ok(checkSoundSpec(bansheeSpec(), { catalog: CAT, library: false }).ok);
    assert.ok(checkSoundSpec(glockSpec(), { catalog: CAT, library: false }).ok);
    assert.equal(checkSoundSpec(bansheeSpec(true), { catalog: CAT, library: false }).ok, false);
    assert.ok(checkSoundSpec(bansheeSpec(true), { catalog: CAT, library: true }).ok);
  });
  it("clampLayer keeps every field inside the validator's ranges", () => {
    const c = E.clampLayer(LAYER({ start: 9, gain: 30, pitch: -40.6, fadeIn: -5, fadeOut: 9000, length: 20, params: { start: 99999, bogus: 1 } }));
    assert.deepEqual([c.start, c.gain, c.pitch, c.fadeIn, c.fadeOut, c.length], [5, 12, -24, 0, 4000, 8]);
    assert.deepEqual(c.params, { start: 2000 }); // unknown params dropped, known ones clamped to SYNTH_PARAMS
    const lib = E.clampLayer(LAYER({ source: "lib:whoosh_11_21ca", length: null, trimStart: 0.3, seed: 77 }));
    assert.equal(lib.length, null); assert.equal(lib.seed, 1); assert.equal(lib.trimStart, 0.3);
    assert.equal(E.clampLayer(LAYER({ source: "silence", trimStart: 2 })).trimStart, 0);
  });
  it("addLayer: creates variant 1 on an empty event, refuses a fifth layer", () => {
    let s = E.addEvent(BANSHEE, "spawn", "spawn"); assert.ok(s.ok);
    const ei = s.ok ? s.index! : -1;
    let r = E.addLayer((s as { spec: SoundSpec }).spec, ei, 0, E.synthLayer("magic"));
    assert.ok(r.ok && r.spec.events[ei].variants.length === 1 && r.index === 0);
    for (let i = 0; i < 3; i++) r = E.addLayer((r as { spec: SoundSpec }).spec, ei, 0, E.silenceLayer());
    const five = E.addLayer((r as { spec: SoundSpec }).spec, ei, 0, E.silenceLayer());
    assert.equal(five.ok, false);
    assert.equal(BANSHEE.events.length, 6, "the input spec is never mutated");
    s = E.addEvent(BANSHEE, "hurt", "hurt"); assert.equal(s.ok, false);
  });
  it("addVariant copies with new synth seeds (+13) and stops at four; weights clamp 1-10; odds add up", () => {
    const r = E.addVariant(BANSHEE, 1, 0);
    assert.ok(r.ok);
    const sp = (r as { spec: SoundSpec }).spec;
    assert.equal(sp.events[1].variants.length, 3);
    assert.equal(sp.events[1].variants[2].layers[0].seed, BANSHEE.events[1].variants[0].layers[0].seed + 13);
    assert.equal(sp.events[1].variants[2].weight, 1);
    let x = sp; for (let i = 0; i < 2; i++) { const y = E.addVariant(x, 1, 0); if (y.ok) x = y.spec; }
    assert.equal(x.events[1].variants.length, 4);
    assert.equal(E.addVariant(x, 1, 0).ok, false);
    assert.equal(E.setWeight(BANSHEE, 1, 0, 40).events[1].variants[0].weight, 10);
    assert.equal(E.setWeight(BANSHEE, 1, 0, -3).events[1].variants[0].weight, 1);
    assert.deepEqual(E.odds(BANSHEE.events[1]), [67, 33]);
  });
  it("setProcessing: 20 kHz low-pass / 20 Hz high-pass / echo < 20 ms mean off; values clamp", () => {
    const p = E.setProcessing(BANSHEE, 1, 0, { lowpass: 20000, highpass: 20, echo: { delay: 10, feedback: 0.3, mix: 0.2 }, reverb: 3 }).events[1].variants[0].processing;
    assert.deepEqual(p, { lowpass: null, highpass: null, reverb: 1, echo: null });
    const q = E.setProcessing(BANSHEE, 1, 0, { lowpass: 150, echo: { delay: 4000, feedback: 2, mix: 0.25 } }).events[1].variants[0].processing;
    assert.equal(q.lowpass, 200); assert.deepEqual(q.echo, { delay: 1000, feedback: 0.7, mix: 0.25 });
    // an edited spec still validates (the studio never produces something the server refuses for range reasons)
    assert.ok(checkSoundSpec(E.setProcessing(BANSHEE, 1, 0, { lowpass: 7000, highpass: 120, reverb: 0.3, echo: { delay: 200, feedback: 0.3, mix: 0.25 } }), { catalog: CAT, library: false }).ok);
  });
  it("slots: mob sets get the standard mob slots, items fire/reload; used events first", () => {
    assert.equal(E.setKindOf(BANSHEE), "mob"); assert.equal(E.setKindOf(GLOCK_S), "item");
    assert.equal(E.setKindOf({ version: 1, name: "orb", events: [] }, ["orb"]), "item");
    const sl = E.slotsFor(BANSHEE, "mob");
    assert.deepEqual(sl.map((s) => s.event), ["ambient", "hurt", "death", "attack", "step", "wail", "spawn"]);
    assert.equal(sl[6].index, null); assert.equal(sl[5].role, "ability");
    assert.deepEqual(E.slotsFor(GLOCK_S, "item").map((s) => s.event), ["fire", "reload"]);
  });
});

describe("sound-edit: subtitles (required, the validator's rule) and save blockers", () => {
  it("subtitleProblem agrees with checkSoundSpec on every sample", () => {
    for (const t of ["", "  ", "ab", "Banshee shrieks", "x".repeat(60), "x".repeat(61), "a <b>", "Gun §", "tab\there", "Ok!"]) {
      const spec = E.setSubtitle(BANSHEE, 1, t);
      const valid = checkSoundSpec({ ...spec, events: [spec.events[1]] }, { catalog: CAT, library: false }).ok;
      assert.equal(E.subtitleProblem(t) === null, valid, JSON.stringify(t));
    }
  });
  it("saveBlockers: missing subtitle, an event with no sound, a variant of silence only", () => {
    let s = E.setSubtitle(BANSHEE, 2, "");
    const e = E.addEvent(s, "spawn", "spawn"); s = (e as { spec: SoundSpec }).spec;
    s = { ...s, events: s.events.map((x, i) => (i === 0 ? { ...x, variants: [{ ...x.variants[0], layers: [E.silenceLayer()] }] } : x)) };
