});

describe("sound-edit: waveform drags (trim / fade / gain / move) and hit testing", () => {
  const lib = LAYER({ source: "lib:scream_female_2_648f", length: 0.42, trimStart: 0.1, pitch: 0, fadeOut: 80, start: 0.02 });
  it("move shifts the start; end trims the length; both clamp", () => {
    assert.equal(E.dragLayer(lib, "move", 0.3, 1.097).start, 0.32);
    assert.equal(E.dragLayer(lib, "move", -5, 1.097).start, 0);
    assert.equal(E.dragLayer(lib, "end", -0.2, 1.097).length, 0.22);
    assert.equal(E.dragLayer(lib, "end", 5, 1.097).length, 0.997); // never past the file's end
  });
  it("trimStart on a library layer moves the in-point and keeps the tail in place", () => {
    const t = E.dragLayer(lib, "trimStart", 0.1, 1.097);
    assert.deepEqual([t.trimStart, t.length, t.start], [0.2, 0.32, 0.12]);
    const syn = E.dragLayer(LAYER({ start: 0.1, length: 0.5 }), "trimStart", 0.1, null);
    assert.deepEqual([syn.start, syn.length, syn.trimStart], [0.2, 0.4, 0]);
  });
  it("fades follow the pointer and never overlap past the layer's length; gain drags add dB", () => {
    assert.equal(E.dragLayer(lib, "fadeIn", 0.05, 1.097).fadeIn, 50);
    assert.equal(E.dragLayer(lib, "fadeOut", -0.1, 1.097).fadeOut, 180);
    const over = E.dragLayer(lib, "fadeIn", 2, 1.097);
    assert.ok(over.fadeIn + over.fadeOut <= 420);
    assert.equal(E.dragLayer(lib, "gain", 0, 1.097, -6).gain, -6);
  });
  it("pitch shortens the span (Minecraft-style resample); hitHandle finds edges, fades, gain line, body", () => {
    const sp = E.layerSpan({ ...lib, pitch: 12 }, 1.097);
    assert.ok(Math.abs(sp.dur - 0.21) < 1e-9);
    const span = E.layerSpan(lib, 1.097), px = (s: number) => s * 1000;
    const o = { fadeRowY: 50, gainY: 50 };
    assert.equal(E.hitHandle(span, px, px(span.start), 120, o), "trimStart");
    assert.equal(E.hitHandle(span, px, px(span.end), 120, o), "end");
    assert.equal(E.hitHandle(span, px, px(span.end - span.fadeOut), 50, o), "fadeOut");
    assert.equal(E.hitHandle(span, px, px(span.start + 0.15), 50, o), "gain");
    assert.equal(E.hitHandle(span, px, px(span.start + 0.15), 120, o), "move");
    assert.equal(E.hitHandle(span, px, px(span.end + 0.2), 120, o), null);
  });
});

describe("sound-edit: candidates, browser audition, gates", () => {
  const cand = { ...BANSHEE.events[1], variants: [{ ...BANSHEE.events[1].variants[1], weight: 5 }] };
  it("applyCandidate: replace a variant (keeps its weight), add as a new variant, replace the event", () => {
    const a = E.applyCandidate(BANSHEE, 1, cand, "replace_variant", 0) as { spec: SoundSpec };
    assert.equal(a.spec.events[1].variants[0].weight, 2); assert.deepEqual(a.spec.events[1].variants[0].layers, cand.variants[0].layers);
    const b = E.applyCandidate(BANSHEE, 1, cand, "add_variant") as { spec: SoundSpec };
    assert.equal(b.spec.events[1].variants.length, 3); assert.equal(b.spec.events[1].variants[2].weight, 1);
    const c = E.applyCandidate(BANSHEE, 1, cand, "replace_event") as { spec: SoundSpec };
    assert.equal(c.spec.events[1].variants.length, 1);
  });
  it("browserVariant: library layers become their processed preview (nothing left to apply) or silence of the same span", () => {
    const v = BANSHEE_LIB.events[1].variants[0];
    const withP = E.browserVariant(v, () => true, () => 1.097);
    assert.equal(withP.silenced, 0);
    assert.deepEqual({ ...withP.variant.layers[1] }, { ...v.layers[1], source: "lib:__p1", trimStart: 0, length: null, pitch: 0, fadeIn: 0, fadeOut: 0 });
    const off = E.browserVariant(v, () => false, () => 1.097);
    assert.equal(off.silenced, 1); assert.equal(off.variant.layers[1].source, "silence");
    assert.ok(Math.abs((off.variant.layers[1].length ?? 0) - E.layerSpan(v.layers[1], 1.097).dur) < 0.001);
    // the browser mix with the host-processed preview equals the render host's chain on the raw source
    const src = synth("wail", 1.097, 9, {});
    const req = E.previewRequestOf(v.layers[1], 1.097)!;
    let pre = src.slice(Math.round(req.trimStart * 44100), Math.round(req.trimStart * 44100) + Math.round(req.length * 44100));
    const { repitch, fade } = require("../lib/cyrus/sound/dsp") as typeof import("../lib/cyrus/sound/dsp");
    pre = fade(repitch(pre, req.pitch), req.fadeIn, req.fadeOut);
    const host = renderVariant(v, "hurt", () => src).pcm, browser = renderVariant(withP.variant, "hurt", () => pre).pcm;
    assert.equal(browser.length, host.length);
    let d = 0; for (let i = 0; i < host.length; i++) d = Math.max(d, Math.abs(host[i] - browser[i]));
    assert.ok(d < 1e-9, `max diff ${d}`);
  });
  it("preview request + key; plain audition is the first <= 4 s, unpitched", () => {
    const r = E.previewRequestOf(BANSHEE_LIB.events[1].variants[0].layers[1], 1.097)!;
    assert.deepEqual(r, { libraryId: "scream_female_2_648f", trimStart: 0.1, length: 0.42, pitch: -5, fadeIn: 5, fadeOut: 80 });
    assert.equal(E.previewKey(r), "scream_female_2_648f|0.1|0.42|-5|5|80");
    assert.equal(E.previewRequestOf(LAYER(), null), null);
    assert.deepEqual(E.auditionRequest("x", 9), { libraryId: "x", trimStart: 0, length: 4, pitch: 0, fadeIn: 0, fadeOut: 40 });
  });
  it("audition gate per plan: library audio only when cleared AND Saka or the top plan; synth always", () => {
    for (const [cleared, plan, lib] of [[false, "all", false], [false, "saka", false], [true, "all", true], [true, "saka", true], [true, "katara", false], [true, null, false], [true, "bogus", false]] as const) {
      const d = E.auditionDecision({ cleared, plan });
      assert.equal(d.library, lib, `${cleared} ${plan}`); assert.equal(d.synth, true);
      if (!cleared) assert.match(d.reason!, /owner confirms the sound licence/);
    }
  });
});

