// ------------------------------------------------------------------------------------------------ in-memory store
type Mem = { projects: Map<string, ProjectRow>; revs: (RevRow & { projectId: string })[]; assets: AssetRow[]; ids: Set<string> };
function memStore(): StudioStore & { mem: Mem } {
  const mem: Mem = { projects: new Map(), revs: [], assets: [], ids: new Set() };
  let t = Date.parse("2026-10-10T10:00:00Z");
  return {
    mem,
    projectForRoot: async (root) => [...mem.projects.values()].find((p) => p.rootBuildId === root) ?? null,
    project: async (id) => mem.projects.get(id) ?? null,
    assets: async (pid) => mem.assets.filter((a) => a.projectId === pid),
    assetById: async (id) => mem.assets.find((a) => a.id === id) ?? null,
    revisions: async (pid) => mem.revs.filter((r) => r.projectId === pid),
    async addRevision(pid, input) {
      const p = mem.projects.get(pid)!;
      if (input.expectedHeadId !== undefined && input.expectedHeadId !== p.headRevisionId) throw Object.assign(new Error("stale"), { code: "stale_head" });
      const seq = mem.revs.filter((r) => r.projectId === pid).length + 1;
      const r = { id: `rev${mem.revs.length + 1}`, projectId: pid, seq, kind: input.kind, status: input.status ?? "pending", message: input.message ?? null, createdAt: new Date(t += 1000), manifest: input.manifest as RevRow["manifest"], modBuildId: input.modBuildId ?? null };
      mem.revs.push(r); p.headRevisionId = r.id;
      return r;
    },
    async recordAsset(pid, a) {
      const hit = mem.assets.find((x) => x.projectId === pid && x.kind === a.kind && x.assetKey === a.assetKey && x.sha256 === a.sha256);
      if (hit) return hit;
      const row: AssetRow = { id: `as${mem.assets.length + 1}`, projectId: pid, revisionId: a.revisionId, assetKey: a.assetKey, kind: a.kind, sha256: a.sha256, size: a.size, origin: a.origin, mime: a.mime ?? null, path: a.path ?? null, provenance: a.provenance ?? null, createdAt: new Date(t += 1000) };
      mem.assets.push(row);
      return row;
    },
    async reserve(pid, kind, key) { const b = buildIdentifier(mem.projects.get(pid)!.namespace, kind, key); if (!b.ok) throw new Error(b.error); mem.ids.add(b.id); return { fullId: b.id }; },
  };
}
const PID = "cp" + "2".repeat(20);
async function seeded(o: { plan?: unknown; cleared?: boolean; host?: boolean; spec?: SoundSpec; soundCands?: ChainInfo["soundCandidateBuilds"] } = {}) {
  const store = memStore();
  store.mem.projects.set(PID, { id: PID, userId: "u1", namespace: NS, rootBuildId: "mb1", headRevisionId: null, title: null });
  const specs = [o.spec ?? BANSHEE, GLOCK_S];
  const rev = await store.addRevision(PID, { kind: "generated", status: "passed", modBuildId: "mb1", expectedHeadId: null, manifest: specs.map((s) => ({ path: `assets/sounds/${s.name}.json`, sha256: specSha(s), role: "asset" as const })) });
  for (const s of specs) await store.recordAsset(PID, { revisionId: rev.id, assetKey: s.name, kind: "sound", sha256: specSha(s), size: 10, origin: "generated", mime: SOUND_SPEC_MIME, path: `assets/sounds/${s.name}.json`, provenance: { spec: s, modBuildId: "mb1", render: "rendered" } });
  const chain: ChainInfo = { rootBuildId: "mb1", latestBuildId: "mb1", mcVersion: "1.21.11", pluginName: "BansheeHunt", assets: null, candidateBuilds: [], soundCandidateBuilds: o.soundCands ?? [] };
  const host = fakeRenderHost();
  const deps: SoundServiceDeps = {
    store, planOf: async (u) => (u === "u1" ? (o.plan === undefined ? "saka" : o.plan) : "all"), chain: async (u, r) => (u === "u1" && r === "mb1" ? chain : null), deliveryOn: () => false,
    sound: { libraryCleared: () => o.cleared === true, renderHost: () => (o.host === false ? { ok: false, reason: "off" } : { ok: true, host }) },
  };
  return { store, deps, chain, headId: () => store.mem.projects.get(PID)!.headRevisionId };
}
const sets = async (s: Awaited<ReturnType<typeof seeded>>) => soundSetsOf(s.deps, PID, s.chain);

describe("sound sets from asset rows (resolveSoundSets)", () => {
  it("build rows -> current spec; studio rows supersede; candidate rows wait; decided ones disappear; other-set candidate rows skipped", async () => {
    const s = await seeded();
    let all = await sets(s);
    assert.deepEqual(all.map((x) => x.set), ["banshee", "glock_9mm"]);
    assert.equal(all[0].history.length, 1); assert.equal(all[0].origin, "generated");
    // a sound candidate build: its banshee row is a candidate, its untouched glock row is ignored
    const candSpec = norm({ ...BANSHEE, events: BANSHEE.events.map((e, i) => (i === 1 ? { ...e, variants: [e.variants[1]] } : e)) });
    const crev = await s.store.addRevision(PID, { kind: "generated", status: "passed", modBuildId: "cb1", expectedHeadId: s.headId(), manifest: [] });
    await s.store.recordAsset(PID, { revisionId: crev.id, assetKey: "banshee", kind: "sound", sha256: specSha(candSpec), size: 1, origin: "generated", mime: SOUND_SPEC_MIME, path: "x", provenance: { spec: candSpec, modBuildId: "cb1" } });
    await s.store.recordAsset(PID, { revisionId: crev.id, assetKey: "glock_9mm", kind: "sound", sha256: specSha(GLOCK_S) + "", size: 1, origin: "generated", mime: SOUND_SPEC_MIME, path: "y", provenance: { spec: GLOCK_S, modBuildId: "cb1", kept: true } });
    const cands = new Map([["cb1", { set: "banshee", event: "hurt" }]]);
    all = resolveSoundSets(await s.store.assets(PID), cands);
    assert.equal(all[0].spec.events[1].variants.length, 2, "the candidate is not current");
    assert.equal(all[0].candidates.length, 1); assert.equal(all[0].candidates[0].event, "hurt");
    assert.equal(all[1].candidates.length, 0);
    // texture-candidate build rows are ignored entirely
    assert.equal(resolveSoundSets(await s.store.assets(PID), new Map(), new Set(["cb1"]))[0].candidates.length, 0);
    // rejecting records the decision: the candidate disappears, the spec stays
    const ss: SoundServiceDeps = { ...s.deps, chain: async () => ({ ...s.chain, soundCandidateBuilds: [{ id: "cb1", set: "banshee", event: "hurt", status: "succeeded", error: null, createdAt: "", summary: "sharper" }] }) };
    const backend = fakeSoundCandidates();
    const r = await rejectSoundCandidate(ss, backend, { userId: "u1", projectId: PID, set: "banshee", requestId: "cb1", expectedHeadId: s.headId() });
    assert.equal(r.seq, 3);
    all = resolveSoundSets(await s.store.assets(PID), cands);
    assert.equal(all[0].candidates.length, 0); assert.equal(all[0].history[0].label, "Kept hurt (Cyrus candidate rejected)");
    assert.deepEqual(docOfSoundRow(s.store.mem.assets.find((a) => a.id === all[0].assetId)!)!.supersedes!.sort(), [specSha(BANSHEE), specSha(candSpec)].sort());
  });
});

describe("Sound Studio service: save = a NEW revision, never an overwrite", () => {
  it("saves an edited spec as revision 2 with a sound-doc row; the build row stays untouched", async () => {
    const s = await seeded();
    const [b] = await sets(s);
    const edited = E.setLayer(BANSHEE, 1, 0, 0, { gain: -3 });
    const r = await saveSoundSet(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: edited, baseAssetId: b.assetId, expectedHeadId: s.headId() });
    assert.equal(r.seq, 2); assert.match(r.pack.skipped, /next build/);
    assert.equal(s.store.mem.assets.length, 3);
    const row = s.store.mem.assets[2];
    assert.equal(row.mime, E.SOUND_DOC_MIME); assert.equal(row.origin, "edited");
    assert.deepEqual((row.provenance as { doc: E.SoundDoc }).doc.supersedes, [specSha(BANSHEE)]);
    assert.equal(s.store.mem.revs[1].manifest.find((e) => e.path === "assets/sounds/banshee.json")!.sha256, row.sha256);
    assert.equal(s.store.mem.revs[1].manifest.find((e) => e.path === "assets/sounds/glock_9mm.json")!.sha256, specSha(GLOCK_S));
    const now = await sets(s);
    assert.equal(now[0].spec.events[1].variants[0].layers[0].gain, -3); assert.equal(now[0].history.length, 2);
    // a stale head is refused
    await assert.rejects(saveSoundSet(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: edited, baseAssetId: b.assetId, expectedHeadId: "rev1" }), (e: { status: number; code: string }) => e.status === 409 && e.code === "stale_head");
  });
  it("blocks a missing subtitle and a library layer while the licence is open, with truthful messages", async () => {
    const s = await seeded();
    const [b] = await sets(s);
    await assert.rejects(saveSoundSet(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: E.setSubtitle(BANSHEE, 2, ""), baseAssetId: b.assetId, expectedHeadId: s.headId() }),
      (e: { status: number; code: string; message: string }) => e.status === 422 && e.code === "subtitle_required" && /^death subtitle is required/.test(e.message));
    await assert.rejects(saveSoundSet(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE_LIB, baseAssetId: b.assetId, expectedHeadId: s.headId() }),
      (e: { status: number; code: string; message: string }) => e.code === "library_not_cleared" && /owner confirms its licence/.test(e.message));
    const ok = await seeded({ cleared: true });
    const [b2] = await sets(ok);
    assert.equal((await saveSoundSet(ok.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE_LIB, baseAssetId: b2.assetId, expectedHeadId: ok.headId() })).seq, 2);
    assert.equal(s.store.mem.revs.length, 1, "nothing was written by the refused saves");
  });
  it("plan gate per plan: Saka and the top plan save; Free / Katara / unknown are refused (viewing stays open)", async () => {
    for (const [plan, ok, code] of [["saka", true, ""], ["all", true, ""], ["katara", false, "asset_locked"], [null, false, "asset_locked"], ["???", false, "plan_unknown"]] as const) {
      const s = await seeded({ plan: plan === "???" ? "mystery" : plan });
      const [b] = await sets(s);
      assert.equal(b.set, "banshee"); // always viewable
      const p = saveSoundSet(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE, baseAssetId: b.assetId, expectedHeadId: s.headId() });
      if (ok) assert.equal((await p).seq, 2);
      else await assert.rejects(p, (e: { status: number; code: string }) => e.status === 403 && (code === "plan_unknown" ? ["plan_unknown", "asset_locked"].includes(e.code) : e.code === code));
    }
  });
  it("render and preview: the (fake) host renders the event with real measurements; off -> 503", async () => {
    const s = await seeded();
    const r = await renderSoundEvent(s.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE, event: "hurt" });
    assert.equal(r.files.length, 2); assert.equal(r.fake, true); assert.equal(r.files[0].mime, "audio/wav");
    assert.ok((r.files[0].quality as { checks: { id: string }[] }).checks.some((c) => c.id === "loudness"));
    const off = await seeded({ host: false });
    await assert.rejects(renderSoundEvent(off.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE, event: "hurt" }), (e: { status: number; code: string }) => e.status === 503 && e.code === "render_off");
    const kat = await seeded({ plan: "katara" });
    await assert.rejects(renderSoundEvent(kat.deps, { userId: "u1", projectId: PID, set: "banshee", spec: BANSHEE, event: "hurt" }), (e: { status: number }) => e.status === 403);
  });
  it("checkStudioSpec maps validator errors to the studio's words", () => {
    const c = checkStudioSpec(E.setLayer(BANSHEE, 1, 0, 0, { source: "synth:nope" }), false);
    assert.equal(c.ok, false); assert.match((c as { error: string }).error, /^hurt V1 layer 1 source: unknown synth preset nope/);
  });
});

describe("library audition (gated preview: licence + plan, cached, size-capped, never the raw file)", () => {
  const raw = { libraryId: "scream_female_2_648f", trimStart: 0.1, length: 0.42, pitch: -5, fadeIn: 5, fadeOut: 80 };
  it("refused while the licence is open (any plan), and for Katara / unknown plans when cleared", async () => {
    for (const plan of ["all", "saka"]) await assert.rejects(libraryPreview((await seeded({ plan })).deps, lruCache(), { userId: "u1", raw }), (e: { status: number; code: string }) => e.status === 403 && e.code === "library_not_cleared");
    for (const plan of ["katara", null, "mystery"]) await assert.rejects(libraryPreview((await seeded({ plan, cleared: true })).deps, lruCache(), { userId: "u1", raw }), (e: { status: number }) => e.status === 403);
  });
  it("cleared + Saka: a short WAV from the host, then from the cache; the key binds the file's sha256 and every parameter", async () => {
    const s = await seeded({ cleared: true });
    const cache = lruCache();
    const a = await libraryPreview(s.deps, cache, { userId: "u1", raw });
    assert.equal(a.cached, false); assert.equal(a.wav.toString("ascii", 0, 4), "RIFF"); assert.ok(a.wav.length <= PREVIEW_MAX_BYTES);
    assert.ok(a.wav.length < 44 + 0.43 * 44100 * 2 + 4, "trimmed + pitched, not the whole file");
    const b = await libraryPreview(s.deps, cache, { userId: "u1", raw });
    assert.equal(b.cached, true); assert.equal(b.key, a.key);
    const n = normalisePreview(raw)!;
    assert.notEqual(previewCacheKey(n.req, n.sound.sha256), previewCacheKey({ ...n.req, pitch: -4 }, n.sound.sha256));
    assert.notEqual(previewCacheKey(n.req, n.sound.sha256), previewCacheKey(n.req, "0".repeat(64)));
    // clamped: never longer than 6 s, never past the file
    assert.equal(normalisePreview({ libraryId: "scream_female_2_648f", length: 60 })!.req.length, 1.097);
    assert.equal(normalisePreview({ libraryId: "../etc/passwd" }), null);
    await assert.rejects(libraryPreview(s.deps, cache, { userId: "u1", raw: { libraryId: "nope_0000" } }), (e: { status: number }) => e.status === 400);
  });
  it("a host answer that is not a short WAV is not passed on; the cache evicts by count and bytes", async () => {
    const s = await seeded({ cleared: true });
    s.deps.sound.renderHost = () => ({ ok: true, host: { id: "bad", render: async () => ({ ok: false, code: "bad_job", error: "x" }), preview: async () => ({ ok: true, tool: { runner: "x", render: "x" }, wav: Buffer.alloc(PREVIEW_MAX_BYTES + 10, 1).toString("base64"), bytes: 1, durationS: 9, samplePeakDb: 0 }) } });
    await assert.rejects(libraryPreview(s.deps, lruCache(), { userId: "u1", raw }), (e: { status: number; code: string }) => e.status === 502 && e.code === "preview_bad");
    const c = lruCache(2, 1000);
    c.set("a", Buffer.alloc(400)); c.set("b", Buffer.alloc(400)); c.get("a"); c.set("c", Buffer.alloc(400));
    assert.equal(c.size(), 2); assert.ok(c.get("a") && c.get("c") && !c.get("b"));
  });
});

describe("Sound Studio candidates (change-build interface, tested with the fake)", () => {
  it("markers: sound candidates are recognised and never mistaken for texture ones", () => {
    const t = soundCandidateRequestText("banshee", "hurt", "Make it sharper");
    assert.deepEqual(soundCandidateOf(t), { set: "banshee", event: "hurt" });
    assert.equal(candidateKeyOf(t), null);
