    assert.ok(doc.supersedes!.includes(ready.specSha256));
    // an unknown candidate can't be accepted
    assert.equal((await S.handleSoundSave(post("/s", { spec: applied.spec, baseAssetId: v.soundSets[0].assetId, expectedHeadId: null, acceptCandidate: "fakes9999zz" }), { projectId: PID, set: "banshee" }, a.deps)).status, 409);
