// ------------------------------------------------------------------------------------------------ HTTP handlers
async function api(o: { plan?: unknown; viewer?: boolean; cleared?: boolean; limit?: number } = {}) {
  const s = await seeded({ plan: o.plan, cleared: o.cleared });
  let hits = 0;
  const deps: H.StudioApiDeps = {
    viewer: async () => (o.viewer === false ? null : { userId: "u1", preview: true }),
    service: s.deps, candidates: { id: "none", request: async () => ({ ok: false, status: 400, code: "x", error: "x" }), poll: async () => ({ status: "failed", error: "x" }) },
    catalog: { providers: [SoundLibraryProvider, TextureLibraryProvider], planOf: s.deps.planOf },
    rateLimit: () => ({ ok: ++hits <= (o.limit ?? 1000), retryAfterSec: 9 }),
    uploads: null, sound: s.deps.sound, soundCandidates: fakeSoundCandidates({ readyAfter: 1 }), previewCache: lruCache(),
  };
  return { s, deps };
}
const U = "http://localhost/api/cyrus/assets/v1";
const get = (path: string) => new Request(U + path);
const post = (path: string, body: unknown) => new Request(U + path, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) });
const SP = { projectId: PID, set: "banshee" };

describe("/api/cyrus/assets/v1 sound handlers (fakes)", () => {
  it("404 outside the studios, 429 rate limit, 400 bad params; 503 when the sound deps aren't wired", async () => {
    assert.equal((await S.handleSoundHistory(get("/h"), SP, (await api({ viewer: false })).deps)).status, 404);
    const b = await api({ limit: 1 });
    assert.equal((await S.handleSoundHistory(get("/h"), SP, b.deps)).status, 200);
    assert.equal((await S.handleSoundHistory(get("/h"), SP, b.deps)).status, 429);
    const c = await api();
    assert.equal((await S.handleSoundHistory(get("/h"), { projectId: PID, set: "Bad Set" }, c.deps)).status, 400);
    assert.equal((await S.handleSoundRender(post("/r", { spec: BANSHEE, event: "Hurt!" }), SP, c.deps)).status, 400);
    const bare = { ...c.deps, sound: undefined };
    assert.equal((await S.handleSoundSave(post("/s", { spec: BANSHEE, baseAssetId: null, expectedHeadId: null }), SP, bare)).status, 503);
  });
  it("projects view: sound sets, capabilities (licence + render host) and library metadata (no audio)", async () => {
    const a = await api({ cleared: false });
    const v = await (await H.handleProjectAssets(get("/projects?root=mb1"), a.deps)).json();
    assert.deepEqual(v.soundSets.map((x: { set: string }) => x.set), ["banshee", "glock_9mm"]);
    assert.equal(v.sound.libraryCleared, false); assert.equal(v.sound.audition.library, false); assert.equal(v.sound.render, "fake");
    const lib = await api({ cleared: true });
    lib.s.deps.store.mem.assets[0].provenance = { spec: BANSHEE_LIB, modBuildId: "mb1" };
    const v2 = await (await H.handleProjectAssets(get("/projects?root=mb1"), lib.deps)).json();
    assert.equal(v2.sound.audition.library, true);
    assert.deepEqual(Object.keys(v2.soundLibrary), ["scream_female_2_648f"]);
    assert.equal(v2.soundLibrary.scream_female_2_648f.peaks.length, 64);
    assert.ok(!JSON.stringify(v2.soundLibrary).includes(".MP3") && !JSON.stringify(v2.soundLibrary).includes(".mp3"), "no file names reach the browser");
  });
  it("save -> history over HTTP; the subtitle rule is enforced server side", async () => {
    const a = await api();
    const v = await (await H.handleProjectAssets(get("/projects?root=mb1"), a.deps)).json();
    assert.equal((await S.handleSoundSave(post("/s", { spec: E.setSubtitle(BANSHEE, 0, ""), baseAssetId: v.soundSets[0].assetId, expectedHeadId: v.headRevisionId }), SP, a.deps)).status, 422);
    const ok = await S.handleSoundSave(post("/s", { spec: E.setWeight(BANSHEE, 1, 0, 3), baseAssetId: v.soundSets[0].assetId, expectedHeadId: v.headRevisionId }), SP, a.deps);
    assert.equal(ok.status, 201);
    const h = await (await S.handleSoundHistory(get("/h"), SP, a.deps)).json();
    assert.equal(h.history.length, 2); assert.equal(h.history[0].revisionSeq, 2); assert.equal(h.history[0].spec.events[1].variants[0].weight, 3);
  });
  it("preview route: 403 library_not_cleared with the truthful note; cleared -> audio/wav (cache header on repeat)", async () => {
    const body = { libraryId: "whoosh_11_21ca", trimStart: 0, length: 0.5, pitch: -1, fadeIn: 0, fadeOut: 40 };
    const off = await S.handleSoundPreview(post("/sound/preview", body), (await api()).deps);
    assert.equal(off.status, 403);
    assert.match((await off.json()).error, /off until the owner confirms the sound licence/);
    const a = await api({ cleared: true });
    const r = await S.handleSoundPreview(post("/sound/preview", body), a.deps);
    assert.equal(r.status, 200); assert.equal(r.headers.get("content-type"), "audio/wav"); assert.equal(r.headers.get("x-cyrus-preview"), "render");
    assert.equal((await S.handleSoundPreview(post("/sound/preview", body), a.deps)).headers.get("x-cyrus-preview"), "cache");
    assert.equal((await S.handleSoundPreview(post("/sound/preview", body), (await api({ cleared: true, plan: "katara" })).deps)).status, 403);
