  it("library/use for a sound: refused while not cleared; cleared -> a pitch -1 layer + the reserved identifier, nothing saved", async () => {
    const body = { projectId: PID, ref: "sound/builtin/whoosh_11_21ca", key: "banshee", event: "attack", expectedHeadId: null };
