    const j = await r.json();
    assert.equal(j.layer.source, "lib:whoosh_11_21ca"); assert.equal(j.layer.pitch, -1); assert.equal(j.identifier, `${NS}:banshee.attack`);
    assert.ok(a.s.store.mem.ids.has(`${NS}:banshee.attack`)); assert.equal(a.s.store.mem.revs.length, 1);
    assert.equal((await H.handleUse(post("/library/use", body), (await api({ cleared: true, plan: "katara" })).deps)).status, 403);
  });
  it("browse sounds: manifest metadata + peaks per item, length / loudness ranges, similar to", async () => {
    const a = await api();
