    assert.ok(r.total > 5);
    for (const i of r.items) { assert.equal(i.sound.peaks.length, 64); assert.equal(typeof i.sound.duration, "number"); assert.equal(i.preview, null); }
    const short = await (await H.handleBrowse(get("/library?kind=sound&maxDur=0.5&limit=60"), a.deps)).json();
    assert.ok(short.total > 0 && short.items.every((i: { sound: { duration: number } }) => i.sound.duration <= 0.5));
    const loud = await (await H.handleBrowse(get("/library?kind=sound&minLufs=-16&limit=60"), a.deps)).json();
    assert.ok(loud.items.every((i: { sound: { lufs: number } }) => i.sound.lufs >= -16));
    const sim = await (await H.handleBrowse(get("/library?kind=sound&similar=sound/builtin/whoosh_11_21ca"), a.deps)).json();
    assert.ok(sim.items.length > 0 && !sim.items.some((i: { id: string }) => i.id === "whoosh_11_21ca"));
    const k = await (await H.handleBrowse(get("/library?kind=sound&q=whoosh"), (await api({ plan: "katara" })).deps)).json();
    assert.equal(k.total, 0); assert.equal(k.denied[0].code, "asset_locked");
  });
});

describe("asset sync keeps Sound Studio edits a build did not replace", () => {
  const build = { id: "mb2", userId: "u1", rootBuildId: "mb1", mcVersion: "1.21.11", pluginName: "BansheeHunt", jarName: "B.jar", jarSha256: "a".repeat(64) };
  const svc = (spec: SoundSpec) => ({ namespace: NS, promptVersion: "p", kept: true, downgraded: [], warnings: [], textures: [], sounds: [{ key: spec.name, path: `assets/sounds/${spec.name}.json`, sha256: specSha(spec), spec, quality: null, events: [] }] });
  const deps = (studio: AssetSyncDeps["studioSoundFor"]) => {
    const recorded: { origin: string; sha256: string; mime: string | null | undefined; provenance: unknown }[] = [];
    const d: AssetSyncDeps = {
      selectStore: () => ({ ok: false, reason: "off" }),
      projectForRootBuild: async () => ({ id: PID, namespace: NS, userId: "u1" }), createProject: async () => { throw new Error("no"); },
      findRevisionForBuild: async () => null, headRevisionId: async () => null, addRevision: async () => ({ id: "revS" }),
      recordAsset: async (_p, a) => { recorded.push({ origin: a.origin, sha256: a.sha256, mime: a.mime, provenance: a.provenance }); return a; },
      selectRenderHost: () => ({ ok: false, reason: "off" }), studioSoundFor: studio,
    };
    return { d, recorded };
  };
  const edited = E.setWeight(BANSHEE, 1, 0, 7);
  const docRow = (supersedes: string[]) => { const doc: E.SoundDoc = { v: 1, spec: edited, supersedes }; const canonical = canonicalJson(doc); return { doc, canonical, sha256: sha256Hex(canonical) }; };
  it("build returns the spec the edit superseded -> the studio spec is the one recorded (and rendered when a host is on)", async () => {
    const x = deps(async () => docRow([specSha(BANSHEE)]));
    await syncBuildAssets(build, svc(BANSHEE) as never, x.d);
    const r = x.recorded.find((a) => (a.provenance as { spec?: SoundSpec }).spec?.name === "banshee")!;
    assert.equal(r.origin, "edited"); assert.equal(r.mime, E.SOUND_DOC_MIME);
    assert.equal(((r.provenance as { spec: SoundSpec }).spec).events[1].variants[0].weight, 7);
    assert.equal((r.provenance as { keptStudioEdit: boolean }).keptStudioEdit, true);
  });
  it("build CHANGED the set -> the build's spec wins; no dep -> unchanged behaviour", async () => {
    const x = deps(async () => docRow(["f".repeat(64)]));
    await syncBuildAssets(build, svc(BANSHEE) as never, x.d);
    assert.equal(x.recorded[0].origin, "generated"); assert.equal(x.recorded[0].sha256, specSha(BANSHEE));
    const y = deps(undefined);
    await syncBuildAssets(build, svc(BANSHEE) as never, y.d);
    assert.equal(y.recorded[0].origin, "generated"); assert.equal(y.recorded[0].mime, SOUND_SPEC_MIME);
  });
});

