// Cyrus Sound Studio (R1b): pure editing model, peaks, sound-set resolution, the service on an in-memory store, the
// gated library preview, candidates, the HTTP handlers with fakes, and builds keeping studio sound edits.
//   npx tsx --test test/cyrus-sound-studio.test.ts        (devhost test test/cyrus-sound-studio.test.ts)
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { checkSoundSpec, type SoundLayer, type SoundSpec } from "../lib/cyrus/sound/spec";
import { libraryCatalogDurations, librarySounds } from "../lib/cyrus/sound/library";
import { decodePeaks, encodePeaks, peakDiff, peaksOf, PEAK_BUCKETS } from "../lib/cyrus/sound/peaks";
import { libraryPeaks } from "../lib/cyrus/sound/library-peaks";
import { renderVariant } from "../lib/cyrus/sound/render";
import { synth } from "../lib/cyrus/sound/synth";
import * as E from "../lib/cyrus/studios/sound-edit";
import { docOfSoundRow, resolveSoundSets, specSha } from "../lib/cyrus/studios/sound-model";
import {
  checkStudioSpec, fakeRenderHost, fakeSoundCandidates, libraryPreview, lruCache, normalisePreview, previewCacheKey, PREVIEW_MAX_BYTES, rejectSoundCandidate, renderSoundEvent, saveSoundSet,
  soundSetsOf, type SoundServiceDeps,
} from "../lib/cyrus/studios/sound-service";
import type { AssetRow, ChainInfo, ProjectRow, RevRow, StudioStore } from "../lib/cyrus/studios/service";
import { soundCandidateOf, soundCandidateRequestText, candidateKeyOf } from "../lib/cyrus/studios/marker";
import * as H from "../lib/cyrus/studios/http";
import * as S from "../lib/cyrus/studios/sound-http";
import { SoundLibraryProvider, TextureLibraryProvider } from "../lib/cyrus/library/providers";
import { buildIdentifier } from "../lib/cyrus/engine-core/identifiers";
import { SOUND_SPEC_MIME } from "../lib/cyrus/assets/sounds";
import { syncBuildAssets, type AssetSyncDeps } from "../lib/cyrus/assets/sync";
import { canonicalJson, sha256Hex } from "../lib/cyrus/assets/textures";
import { bansheeSpec, glockSpec } from "../scripts/cyrus/sound-fixtures";

const CAT = libraryCatalogDurations();
const norm = (raw: unknown): SoundSpec => { const c = checkSoundSpec(raw, { catalog: CAT, library: true }); if (!c.ok) throw new Error(c.error); return c.spec; };
const BANSHEE = norm(bansheeSpec()), BANSHEE_LIB = norm(bansheeSpec(true)), GLOCK_S = norm(glockSpec());
const NS = "nx_7k2qf9wd";
const LAYER = (o: Partial<SoundLayer> = {}): SoundLayer => ({ source: "synth:wail", start: 0, gain: 0, pitch: 0, trimStart: 0, length: 0.5, fadeIn: 0, fadeOut: 0, seed: 1, params: {}, ...o });

// ------------------------------------------------------------------------------------------------ pure model
describe("sound-edit: layer / variant / event edits (immutable, clamped to the validator)", () => {
  it("fixtures are valid SoundSpecs with the library off (synth only) and on (one library layer)", () => {
    assert.ok(checkSoundSpec(bansheeSpec(), { catalog: CAT, library: false }).ok);
    assert.ok(checkSoundSpec(glockSpec(), { catalog: CAT, library: false }).ok);
    assert.equal(checkSoundSpec(bansheeSpec(true), { catalog: CAT, library: false }).ok, false);
    assert.ok(checkSoundSpec(bansheeSpec(true), { catalog: CAT, library: true }).ok);
  });
  it("clampLayer keeps every field inside the validator's ranges", () => {
    const c = E.clampLayer(LAYER({ start: 9, gain: 30, pitch: -40.6, fadeIn: -5, fadeOut: 9000, length: 20, params: { start: 99999, bogus: 1 } }));
    assert.deepEqual([c.start, c.gain, c.pitch, c.fadeIn, c.fadeOut, c.length], [5, 12, -24, 0, 4000, 8]);
