describe("sound-edit: waveform drags (trim / fade / gain / move) and hit testing", () => {
  const lib = LAYER({ source: "lib:scream_female_2_648f", length: 0.42, trimStart: 0.1, pitch: 0, fadeOut: 80, start: 0.02 });
  it("move shifts the start; end trims the length; both clamp", () => {
    assert.equal(E.dragLayer(lib, "move", 0.3, 1.097).start, 0.32);
    assert.equal(E.dragLayer(lib, "move", -5, 1.097).start, 0);
    assert.equal(E.dragLayer(lib, "end", -0.2, 1.097).length, 0.22);
    assert.equal(E.dragLayer(lib, "end", 5, 1.097).length, 0.997); // never past the file's end
  });
  it("trimStart on a library layer moves the in-point and keeps the tail in place", () => {
    const t = E.dragLayer(lib, "trimStart", 0.1, 1.097);
    assert.deepEqual([t.trimStart, t.length, t.start], [0.2, 0.32, 0.12]);
    const syn = E.dragLayer(LAYER({ start: 0.1, length: 0.5 }), "trimStart", 0.1, null);
    assert.deepEqual([syn.start, syn.length, syn.trimStart], [0.2, 0.4, 0]);
  });
  it("fades follow the pointer and never overlap past the layer's length; gain drags add dB", () => {
    assert.equal(E.dragLayer(lib, "fadeIn", 0.05, 1.097).fadeIn, 50);
    assert.equal(E.dragLayer(lib, "fadeOut", -0.1, 1.097).fadeOut, 180);
    const over = E.dragLayer(lib, "fadeIn", 2, 1.097);
    assert.ok(over.fadeIn + over.fadeOut <= 420);
    assert.equal(E.dragLayer(lib, "gain", 0, 1.097, -6).gain, -6);
  });
  it("pitch shortens the span (Minecraft-style resample); hitHandle finds edges, fades, gain line, body", () => {
    const sp = E.layerSpan({ ...lib, pitch: 12 }, 1.097);
    assert.ok(Math.abs(sp.dur - 0.21) < 1e-9);
    const span = E.layerSpan(lib, 1.097), px = (s: number) => s * 1000;
    const o = { fadeRowY: 50, gainY: 50 };
    assert.equal(E.hitHandle(span, px, px(span.start), 120, o), "trimStart");
    assert.equal(E.hitHandle(span, px, px(span.end), 120, o), "end");
    assert.equal(E.hitHandle(span, px, px(span.end - span.fadeOut), 50, o), "fadeOut");
    assert.equal(E.hitHandle(span, px, px(span.start + 0.15), 50, o), "gain");
    assert.equal(E.hitHandle(span, px, px(span.start + 0.15), 120, o), "move");
    assert.equal(E.hitHandle(span, px, px(span.end + 0.2), 120, o), null);
  });
});

describe("sound-edit: candidates, browser audition, gates", () => {
