    assert.deepEqual({ ...withP.variant.layers[1] }, { ...v.layers[1], source: "lib:__p1", trimStart: 0, length: null, pitch: 0, fadeIn: 0, fadeOut: 0 });
    const off = E.browserVariant(v, () => false, () => 1.097);
