    const { repitch, fade } = require("../lib/cyrus/sound/dsp") as typeof import("../lib/cyrus/sound/dsp");
    pre = fade(repitch(pre, req.pitch), req.fadeIn, req.fadeOut);
    const host = renderVariant(v, "hurt", () => src).pcm, browser = renderVariant(withP.variant, "hurt", () => pre).pcm;
    assert.equal(browser.length, host.length);
    let d = 0; for (let i = 0; i < host.length; i++) d = Math.max(d, Math.abs(host[i] - browser[i]));
    assert.ok(d < 1e-9, `max diff ${d}`);
  });
  it("preview request + key; plain audition is the first <= 4 s, unpitched", () => {
    const r = E.previewRequestOf(BANSHEE_LIB.events[1].variants[0].layers[1], 1.097)!;
