describe("library audition (gated preview: licence + plan, cached, size-capped, never the raw file)", () => {
  const raw = { libraryId: "scream_female_2_648f", trimStart: 0.1, length: 0.42, pitch: -5, fadeIn: 5, fadeOut: 80 };
  it("refused while the licence is open (any plan), and for Katara / unknown plans when cleared", async () => {
    for (const plan of ["all", "saka"]) await assert.rejects(libraryPreview((await seeded({ plan })).deps, lruCache(), { userId: "u1", raw }), (e: { status: number; code: string }) => e.status === 403 && e.code === "library_not_cleared");
    for (const plan of ["katara", null, "mystery"]) await assert.rejects(libraryPreview((await seeded({ plan, cleared: true })).deps, lruCache(), { userId: "u1", raw }), (e: { status: number }) => e.status === 403);
  });
  it("cleared + Saka: a short WAV from the host, then from the cache; the key binds the file's sha256 and every parameter", async () => {
    const s = await seeded({ cleared: true });
    const cache = lruCache();
    const a = await libraryPreview(s.deps, cache, { userId: "u1", raw });
    assert.equal(a.cached, false); assert.equal(a.wav.toString("ascii", 0, 4), "RIFF"); assert.ok(a.wav.length <= PREVIEW_MAX_BYTES);
    assert.ok(a.wav.length < 44 + 0.43 * 44100 * 2 + 4, "trimmed + pitched, not the whole file");
    const b = await libraryPreview(s.deps, cache, { userId: "u1", raw });
    assert.equal(b.cached, true); assert.equal(b.key, a.key);
    const n = normalisePreview(raw)!;
    assert.notEqual(previewCacheKey(n.req, n.sound.sha256), previewCacheKey({ ...n.req, pitch: -4 }, n.sound.sha256));
    assert.notEqual(previewCacheKey(n.req, n.sound.sha256), previewCacheKey(n.req, "0".repeat(64)));
    // clamped: never longer than 6 s, never past the file
    assert.equal(normalisePreview({ libraryId: "scream_female_2_648f", length: 60 })!.req.length, 1.097);
    assert.equal(normalisePreview({ libraryId: "../etc/passwd" }), null);
    await assert.rejects(libraryPreview(s.deps, cache, { userId: "u1", raw: { libraryId: "nope_0000" } }), (e: { status: number }) => e.status === 400);
  });
  it("a host answer that is not a short WAV is not passed on; the cache evicts by count and bytes", async () => {
    const s = await seeded({ cleared: true });
    s.deps.sound.renderHost = () => ({ ok: true, host: { id: "bad", render: async () => ({ ok: false, code: "bad_job", error: "x" }), preview: async () => ({ ok: true, tool: { runner: "x", render: "x" }, wav: Buffer.alloc(PREVIEW_MAX_BYTES + 10, 1).toString("base64"), bytes: 1, durationS: 9, samplePeakDb: 0 }) } });
    await assert.rejects(libraryPreview(s.deps, lruCache(), { userId: "u1", raw }), (e: { status: number; code: string }) => e.status === 502 && e.code === "preview_bad");
    const c = lruCache(2, 1000);
    c.set("a", Buffer.alloc(400)); c.set("b", Buffer.alloc(400)); c.get("a"); c.set("c", Buffer.alloc(400));
    assert.equal(c.size(), 2); assert.ok(c.get("a") && c.get("c") && !c.get("b"));
  });
});

