// Cyrus Sound Studio (R1b): screenshots of every Sound Studio screen and state (run ON node-2 against the devhost
// dev server; files are prefixed sound-). Two phases, because the library licence flag is a server env:
//   devhost db reset && devhost db push
//   devhost env set CYRUS_STUDIO_CANDIDATES=fake CYRUS_STUDIO_SOUND_RENDER=fake CYRUS_STUDIO_TEST_PLAN_UNKNOWN=usr_studio_unknown
//   A (licence open, the shipped default):  devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//                                           devhost dev; devhost run -- node test/e2e/cyrus-sound-studio.shots.mjs .studio-tokens.json .sound-shots A
//   B (cleared, fake library host):         devhost env set CYRUS_SOUND_LIBRARY_CLEARED=1; devhost db reset && devhost db push
//                                           devhost run -- env STUDIO_FIXTURE_LIBRARY=1 npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//                                           devhost stop dev; devhost dev; devhost run -- node test/e2e/cyrus-sound-studio.shots.mjs .studio-tokens.json .sound-shots B
//   devhost pull .sound-shots /root/agent-notes/cyrus-designs/impl-shots ; devhost env unset CYRUS_SOUND_LIBRARY_CLEARED ; devhost stop dev
import { chromium } from "playwright";
import { mkdirSync, readFileSync } from "node:fs";

const [, , tokFile, out = ".sound-shots", phase = "A", only = ""] = process.argv;
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
mkdirSync(out, { recursive: true });
const browser = await chromium.launch({ args: ["--autoplay-policy=no-user-gesture-required"] });
const VIEW = { desktop: { width: 1440, height: 900 }, narrow: { width: 390, height: 844 } };

async function shot(name, who, path, { view = "desktop", theme = "dark", act, full = false, wait = 2600 } = {}) {
  if (only && !name.includes(only)) return;
  const ctx = await browser.newContext({ viewport: VIEW[view], deviceScaleFactor: 1, isMobile: view === "narrow", hasTouch: view === "narrow", colorScheme: theme, reducedMotion: "reduce" });
  await ctx.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); localStorage.setItem("cyrus-sound", "off"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e).slice(0, 300)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  const res = await page.goto(BASE + path.replace("{build}", T[who].buildId), { waitUntil: "networkidle", timeout: 180000 }).catch((e) => (errs.push("goto " + e), null));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later", "Accept all"]) { const b = page.getByRole("button", { name: label, exact: true }); if (await b.count().catch(() => 0)) await b.first().click({ timeout: 800 }).catch(() => {}); }
  await page.waitForTimeout(wait);
  if (act) { try { await act(page); } catch (e) { errs.push("act " + String(e).slice(0, 200)); } }
  await page.waitForTimeout(900);
  const file = `${out}/${name}.png`;
  await page.screenshot({ path: file, fullPage: full });
  console.log(file, res?.status() ?? "-", page.url().replace(BASE, ""), errs.length ? "ERR " + errs.join(" | ").slice(0, 500) : "");
  await ctx.close();
}

const snd = "/dashboard/cyrus/{build}/studio/sound";
const hurt = snd + "?set=banshee&event=hurt";
const askFake = async (p) => {
  await p.getByTestId("dock-input").fill("Make the hurt sound sharper and shorter");
  await p.getByTestId("dock-input").press("Enter");
  await p.getByTestId("candidate").waitFor({ timeout: 30000 });
  await p.waitForTimeout(3400);
};
const clearDeath = async (p) => { await p.getByTestId("slot-banshee-death").click(); await p.getByTestId("subtitle").fill(""); await p.getByTestId("slot-banshee-hurt").click(); };

if (phase === "A") {
  await shot("sound-dark", "all", hurt, { act: clearDeath });
  await shot("sound-light", "all", hurt, { theme: "light", act: clearDeath });
  await shot("sound-dark-candidate", "all", hurt, { act: askFake });
  await shot("sound-dark-synth", "all", hurt, { act: async (p) => { await p.getByRole("tab", { name: /Synth/ }).click(); } });
  await shot("sound-dark-checks", "all", hurt, { act: async (p) => { await p.getByRole("tab", { name: /Checks/ }).click(); } });
  await shot("sound-dark-history", "all", hurt, { act: async (p) => { await p.getByTestId("layer-lane").first().click(); await p.getByLabel("gain").first().fill("-6"); await p.getByRole("tab", { name: /History/ }).click(); } });
  await shot("sound-dark-library-off", "all", hurt, { act: async (p) => { await p.getByRole("tab", { name: /Library/ }).click(); await p.waitForTimeout(1500); await p.getByTestId("sound-lib-row").nth(1).locator("button.nm").click(); } });
  await shot("sound-dark-subtitle-missing", "all", snd + "?set=banshee&event=death", { act: async (p) => { await p.getByTestId("subtitle").fill(""); await p.getByTestId("save-revision").click(); } });
  await shot("sound-dark-glock", "saka", snd + "?set=glock_9mm&event=fire");
  await shot("sound-dark-render-host", "all", hurt, { act: async (p) => { await p.getByTestId("render-host").click(); await p.waitForTimeout(2500); } });
  await shot("sound-dark-spawn-empty", "all", snd + "?set=banshee&event=spawn");
  await shot("sound-narrow", "all", hurt, { view: "narrow", full: true, act: async (p) => { await p.getByTestId("narrow-candidate").waitFor({ timeout: 4000 }).catch(() => {}); } });
  await shot("sound-locked-katara-light", "katara", snd, { theme: "light" });
  await shot("sound-locked-free-narrow", "free", snd, { view: "narrow", full: true });
  await shot("sound-locked-unknown-dark", "unknown", snd);
  await shot("sound-included-saka-plans-dark", "saka", "/dashboard/cyrus/{build}/studio/plans?studio=sound");
  await shot("sound-assets-dark", "all", "/dashboard/cyrus/{build}?tab=assets", { wait: 4500, act: async (p) => { await p.getByTestId("assets-sound-set").first().scrollIntoViewIfNeeded(); } });
  await shot("sound-assets-katara-dark", "katara", "/dashboard/cyrus/{build}?tab=assets", { wait: 4500, act: async (p) => { await p.getByTestId("assets-sound-set").first().scrollIntoViewIfNeeded(); } });
} else {
  await shot("sound-cleared-dark", "all", hurt, { act: async (p) => { await p.getByTestId("layer-lane").nth(1).click(); await p.waitForTimeout(1500); } });
  await shot("sound-cleared-library-dark", "all", hurt, { act: async (p) => { await p.getByRole("tab", { name: /Library/ }).click(); await p.waitForTimeout(1500); await p.getByTestId("sound-lib-row").nth(0).locator("button.nm").click(); } });
  await shot("sound-cleared-candidate-dark", "all", hurt, { act: askFake });
  await shot("sound-cleared-light", "all", hurt, { theme: "light", act: async (p) => { await p.getByTestId("layer-lane").nth(1).click(); await p.waitForTimeout(1500); } });
}
await browser.close();

