process.exit(failed ? 1 : 0);

toolu_01BzsmMNZZrtRLa9uo38QSvK.content:
// Cyrus Sound Studio (R1b): Playwright INTERACTION tests against the devhost dev server with the seeded fixtures.
// Nothing paid: the fake candidate backend and the fake render host (CYRUS_STUDIO_CANDIDATES=fake,
// CYRUS_STUDIO_SOUND_RENDER=fake). Two phases (the library licence flag is a server env):
//   A, licence open (the shipped default):
//     devhost db reset && devhost db push
//     devhost run -- npx tsx scripts/cyrus/studio-fixtures.ts > .studio-tokens.json
//     devhost dev ; devhost run -- node test/e2e/cyrus-sound-studio.e2e.mjs .studio-tokens.json A
//   B, licence cleared (CYRUS_SOUND_LIBRARY_CLEARED=1, fixtures with STUDIO_FIXTURE_LIBRARY=1, dev restarted):
//     devhost run -- node test/e2e/cyrus-sound-studio.e2e.mjs .studio-tokens-b.json B
// Covers: trim + fade drags on the waveform, add layers (silence, synth), subtitle required (save blocked) then set,
// save a revision (survives a reload, shows in History), a fake Cyrus candidate (replace V1 + save), the narrow
// approve, the locked states + API 403, the outsider 404, and library audition gating (403 + lock note in A; a gated
// WAV preview + "Add" a pitch -1 library layer in B).
import { chromium } from "playwright";
import { readFileSync } from "node:fs";

const [, , tokFile, phase = "A"] = process.argv;
const T = JSON.parse(readFileSync(tokFile, "utf8"));
const BASE = process.env.BASE ?? `http://127.0.0.1:${process.env.PORT}`;
const browser = await chromium.launch({ args: ["--autoplay-policy=no-user-gesture-required"] });
let failed = 0;
const ok = (cond, name, extra = "") => { console.log(`${cond ? "PASS" : "FAIL"}  ${name}${extra ? "  " + extra : ""}`); if (!cond) failed++; };
async function page(who, path, view = { width: 1440, height: 900 }) {
  const ctx = await browser.newContext({ viewport: view, isMobile: view.width < 500, hasTouch: view.width < 500 });
  await ctx.addCookies([{ name: T.cookie, value: T[who].token, url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  await ctx.addInitScript(() => { try { localStorage.setItem("nx-tour-dismissed", "1"); } catch {} });
  const p = await ctx.newPage();
  const res = await p.goto(BASE + path.replace("{build}", T[who].buildId), { waitUntil: "networkidle", timeout: 180000 });
  return { p, ctx, res };
}
const snd = "/dashboard/cyrus/{build}/studio/sound";
const hurt = snd + "?set=banshee&event=hurt";
const layerOf = async (p) => JSON.parse((await p.getByTestId("waveform").getAttribute("data-layer")) ?? "null");
async function geomOf(p) {
  const box = await p.getByTestId("waveform").boundingBox();
  await p.mouse.move(box.x + 5, box.y + box.height - 5); await p.mouse.move(box.x + 8, box.y + box.height - 6); // a re-render publishes the handle geometry
  await p.waitForTimeout(150);
  return { box, g: JSON.parse((await p.getByTestId("waveform").getAttribute("data-geom")) ?? "null") };
}
async function drag(p, from, to) { await p.mouse.move(from.x, from.y); await p.mouse.down(); await p.mouse.move(to.x, to.y, { steps: 8 }); await p.mouse.up(); await p.waitForTimeout(250); }
const apiPost = (p, path, body) => p.evaluate(async ([u, b]) => { const r = await fetch(u, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(b) }); return { status: r.status, type: r.headers.get("content-type"), body: r.headers.get("content-type")?.includes("json") ? await r.json() : null }; }, [path, body]);

if (phase === "A") {
  // 1. trim + fade drags, add layers, subtitle rule, save, reload
  {
    const { p, ctx } = await page("all", hurt);
    await p.getByTestId("waveform").waitFor();
    await p.waitForTimeout(1500);
    const before = await layerOf(p);
    let { box, g } = await geomOf(p);
    ok(!!g && g.x1 > g.x0, "selected layer geometry published", JSON.stringify(g));
    await drag(p, { x: box.x + g.x1, y: box.y + box.height * 0.6 }, { x: box.x + g.x1 - 60, y: box.y + box.height * 0.6 });
    const trimmed = await layerOf(p);
    ok(trimmed.length < before.length - 0.03, "dragging the right edge trims the layer", `${before.length} -> ${trimmed.length}`);
    ({ box, g } = await geomOf(p));
    await drag(p, { x: box.x + g.fi, y: box.y + g.gy }, { x: box.x + g.fi + 40, y: box.y + g.gy });
    const faded = await layerOf(p);
    ok(faded.fadeIn > before.fadeIn + 20, "dragging the top-left corner fades in", `${before.fadeIn} -> ${faded.fadeIn}`);
    ok(/2 unsaved edits/.test(await p.locator(".sd-savebar .st").textContent()), "each drag is one edit step", await p.locator(".sd-savebar .st").textContent());
    const lanes = await p.getByTestId("layer-lane").count();
    await p.getByTestId("add-silence").click();
    await p.getByRole("tab", { name: /Synth/ }).click();
    await p.getByRole("button", { name: "Play whoosh" }).waitFor();
    // select the silence layer first so the Synth tab is in "new layer" mode
    await p.getByTestId("add-synth").click();
    ok(await p.getByTestId("layer-lane").count() === lanes + 2, "Silence + Synth preset add two layers", `${lanes} -> ${await p.getByTestId("layer-lane").count()}`);
    // subtitle: required, save blocked with the truthful message, then fixed
    await p.getByTestId("slot-banshee-death").click();
    await p.getByTestId("subtitle").fill("");
    ok(await p.getByTestId("subtitle").getAttribute("aria-invalid") === "true", "an empty subtitle is marked invalid");
    await p.getByTestId("save-revision").click();
    await p.locator(".cys-toast").filter({ hasText: "Can't save yet" }).waitFor({ timeout: 5000 });
    ok(/subtitle required/i.test(await p.locator(".cys-toast").textContent()), "save is blocked without a subtitle", await p.locator(".cys-toast").textContent());
    await p.getByTestId("subtitle").fill("Banshee collapses");
    await p.waitForTimeout(300);
    ok(!(await p.locator(".sd-savebar .err").count()), "the blocker clears once the subtitle is set");
    await p.getByTestId("save-revision").click();
    await p.locator(".cys-toast").filter({ hasText: "Saved as revision" }).waitFor({ timeout: 20000 });
    ok(/next build/.test(await p.locator(".cys-toast").textContent()), "the save says servers get it with the next build", await p.locator(".cys-toast").textContent());
    await p.reload({ waitUntil: "networkidle" });
    await p.getByTestId("slot-banshee-death").click();
    ok(await p.getByTestId("subtitle").inputValue() === "Banshee collapses", "the saved subtitle survives a reload");
    await p.getByTestId("slot-banshee-hurt").click();
    ok(await p.getByTestId("layer-lane").count() === lanes + 2, "the added layers survive a reload");
    await p.getByRole("tab", { name: /History/ }).click();
    ok(await p.getByTestId("sound-revision").count() >= 2, "History lists the new revision", String(await p.getByTestId("sound-revision").count()));
    await ctx.close();
  }
  // 2. a fake Cyrus candidate: ask, replace V1, save
  {
    const { p, ctx } = await page("all", hurt);
    await p.getByTestId("dock-input").fill("Make the hurt sound sharper and shorter");
    await p.getByTestId("dock-input").press("Enter");
    await p.getByTestId("candidate").waitFor({ timeout: 30000 });
    ok(true, "the candidate arrives through the change-build interface (fake backend)");
    await p.getByTestId("accept-candidate").click();
    ok(/Replaced V1/.test(await p.locator(".cys-toast").textContent() + (await p.locator(".sd-savebar").textContent())) || (await p.locator(".sd-savebar .st").textContent()).includes("unsaved"), "Replace V1 is one unsaved edit step");
    await p.getByTestId("save-revision").click();
    await p.locator(".cys-toast").filter({ hasText: "Saved as revision" }).waitFor({ timeout: 20000 });
    await p.getByRole("tab", { name: /History/ }).click();
    ok(/Cyrus/.test(await p.getByTestId("sound-revision").first().textContent()), "History records the candidate decision", await p.getByTestId("sound-revision").first().textContent());
    await ctx.close();
  }
  // 3. the narrow review: approve the seeded candidate (Saka account, untouched)
  {
    const { p, ctx } = await page("saka", hurt, { width: 390, height: 844 });
    await p.getByTestId("narrow-candidate").waitFor({ timeout: 20000 });
    await p.getByTestId("narrow-approve").click();
    await p.locator(".cys-toast").filter({ hasText: "Saved as revision" }).waitFor({ timeout: 20000 });
    ok(true, "narrow approve saves a revision");
    ok(!(await p.getByTestId("narrow-candidate").count()), "the approved candidate is gone");
    await ctx.close();
  }
  // 4. library audition gating (licence open): locked buttons, the truthful note, 403 from the API, refused "Add"
  {
    const { p, ctx } = await page("all", hurt);
    await p.getByRole("tab", { name: /Library/ }).click();
    await p.getByTestId("library-licence-note").waitFor({ timeout: 10000 });
    ok(/owner confirms the sound licence/.test(await p.getByTestId("library-licence-note").textContent()), "library tab shows the licence note");
    ok(await p.getByTestId("lib-audition").first().getAttribute("aria-disabled") === "true", "library audition buttons are off");
    const r = await apiPost(p, "/api/cyrus/assets/v1/sound/preview", { libraryId: "whoosh_11_21ca", trimStart: 0, length: 0.5, pitch: 0, fadeIn: 0, fadeOut: 40 });
    ok(r.status === 403 && r.body?.code === "library_not_cleared", "the preview route refuses while the licence is open", JSON.stringify(r));
    await p.getByTestId("sound-lib-row").first().getByRole("button", { name: "Add" }).click();
    await p.locator(".cys-toast").waitFor({ timeout: 5000 });
    ok(/licence/.test(await p.locator(".cys-toast").textContent()), "Use in project is refused with the licence reason", await p.locator(".cys-toast").textContent());
    await ctx.close();
  }
  // 5. locks + API gates
  {
    const { p, ctx } = await page("katara", snd);
    await p.locator(".lk-lock").waitFor({ timeout: 20000 });
    ok(/part of the Saka plan/i.test(await p.locator(".lk-lock h2").textContent()), "Katara gets the locked Sound Studio in place", await p.locator(".lk-lock h2").textContent());
    ok(await p.getByTestId("lock-sound-row").count() === 8, "the mod's 8 sound events stay listed (read only)");
    const r = await apiPost(p, `/api/cyrus/assets/v1/projects/${T.katara.projectId}/sounds/banshee/revisions`, { spec: { version: 1, name: "banshee", events: [] }, baseAssetId: null, expectedHeadId: null });
    ok(r.status === 403 || r.status === 422, "the API refuses a Katara save", String(r.status));
    const r2 = await apiPost(p, `/api/cyrus/assets/v1/projects/${T.katara.projectId}/sounds/banshee/candidates`, { event: "hurt", prompt: "Make it sharper" });
    ok(r2.status === 403, "the API refuses a Katara candidate", String(r2.status));
    await ctx.close();
    const f = await page("free", snd, { width: 390, height: 844 });
    await f.p.locator(".lk-lock").waitFor({ timeout: 20000 });
    ok(true, "Free (narrow) gets the locked state");
    await f.ctx.close();
    const u = await page("unknown", snd);
    await u.p.locator(".lk-lock").waitFor({ timeout: 20000 });
    ok(/couldn.t (check|confirm)/i.test(await u.p.locator(".lk-lock").textContent()), "an unknown plan fails closed for editing (assets still listed)", (await u.p.locator(".lk-lock h2").textContent()) ?? "");
    await u.ctx.close();
    const o = await page("outsider", snd);
    ok(/not found|404|could not be found/i.test(await o.p.locator("body").textContent()), "a non-preview account gets the not-found page");
    const r3 = await apiPost(o.p, "/api/cyrus/assets/v1/sound/preview", { libraryId: "whoosh_11_21ca" });
    ok(r3.status === 404, "and the API answers 404", String(r3.status));
    await o.ctx.close();
  }
} else {
  // B: licence cleared, fake library host
  const { p, ctx } = await page("all", hurt);
  await p.getByRole("tab", { name: /Library/ }).click();
  await p.getByTestId("sound-lib-row").first().waitFor({ timeout: 10000 });
  ok(!(await p.getByTestId("library-licence-note").count()), "no licence note once cleared");
  const resp = p.waitForResponse((r) => r.url().endsWith("/sound/preview"), { timeout: 15000 });
  await p.getByTestId("lib-audition").first().click();
  const r = await resp;
  ok(r.status() === 200 && r.headers()["content-type"] === "audio/wav", "audition fetches a short WAV preview through the gated route", `${r.status()} ${r.headers()["content-type"]}`);
  ok((await r.body()).length <= 44 + 6 * 44100 * 2, "the preview is size-capped");
  const lanes = await p.getByTestId("layer-lane").count();
  await p.getByTestId("sound-lib-row").nth(2).getByRole("button", { name: "Add" }).click();
  await p.waitForTimeout(800);
  ok(await p.getByTestId("layer-lane").count() === lanes + 1, "Add puts a library layer on the open variant", `${lanes} -> ${await p.getByTestId("layer-lane").count()}`);
  const l = await layerOf(p);
  ok(l?.source?.startsWith("lib:") && l.pitch === -1, "the library layer defaults to pitch -1 (never shipped unchanged)", JSON.stringify(l));
  const kat = await page("katara", hurt);
  const rk = await apiPost(kat.p, "/api/cyrus/assets/v1/sound/preview", { libraryId: "whoosh_11_21ca", length: 0.5 });
  ok(rk.status === 403, "Katara can't audition the library even when cleared", String(rk.status));
  await kat.ctx.close();
  await ctx.close();
}
await browser.close();
console.log(failed ? `\n${failed} FAILED` : "\nall passed");
process.exit(failed ? 1 : 0);

