cat > /tank/dev-worktrees/cyrus-r9/scripts/cyrus/sound-preview-real.ts <<'EOF'
// Cyrus Sound Studio (R1b): one REAL audition preview of library sounds ON node-2 (where the library lives), through
// the same runner code the render host runs (runPreview). Prints metadata only; no audio is written anywhere.
//   devhost run -- npx tsx scripts/cyrus/sound-preview-real.ts
import { createHash } from "node:crypto";
import path from "node:path";
import { runPreview } from "../../lib/cyrus/sound/runner";
import { librarySound } from "../../lib/cyrus/sound/library";
import { SOUND_FFMPEG_DIR, SOUND_LIBRARY_DIR } from "../../lib/cyrus/sound/host";
import { normalisePreview, PREVIEW_MAX_BYTES } from "../../lib/cyrus/studios/sound-service";

const ff = { ffmpeg: path.join(SOUND_FFMPEG_DIR, "ffmpeg"), ffprobe: path.join(SOUND_FFMPEG_DIR, "ffprobe") };
const out: unknown[] = [];
for (const raw of [
  { libraryId: "scream_female_2_648f", trimStart: 0.1, length: 0.42, pitch: -5, fadeIn: 5, fadeOut: 80 },
  { libraryId: "whoosh_11_21ca", trimStart: 0, length: 4, pitch: 0, fadeIn: 0, fadeOut: 40 },
  { libraryId: "gunshot_9mm_single_2_a5a6", trimStart: 0, length: 60, pitch: -1, fadeIn: 0, fadeOut: 150 },
]) {
  const n = normalisePreview(raw)!;
  const s = librarySound(n.req.libraryId)!;
  const t = Date.now();
  const a = runPreview({ v: 1, kind: "preview", library: { id: s.id, file: s.file, sha256: s.sha256, channels: s.channels, duration: s.duration }, ...n.req }, { ff, libraryDir: SOUND_LIBRARY_DIR });
  const b = runPreview({ v: 1, kind: "preview", library: { id: s.id, file: s.file, sha256: s.sha256, channels: s.channels, duration: s.duration }, ...n.req }, { ff, libraryDir: SOUND_LIBRARY_DIR });
  if (!a.ok || !b.ok) { out.push({ id: s.id, error: a.ok ? (b as { error: string }).error : a.error }); continue; }
  const wav = Buffer.from(a.wav, "base64");
  out.push({ id: s.id, request: n.req, ms: Date.now() - t, sourceSeconds: s.duration, previewSeconds: a.durationS, bytes: a.bytes, underCap: a.bytes <= PREVIEW_MAX_BYTES, riff: wav.toString("ascii", 0, 4) + "/" + wav.toString("ascii", 8, 12), samplePeakDb: a.samplePeakDb, deterministic: a.wav === b.wav, wavSha256: createHash("sha256").update(wav).digest("hex").slice(0, 16), sameAsSourceFile: createHash("sha256").update(wav).digest("hex") === s.sha256 });
}
